                      this.log("ERR", `  🔒 denylisted on ${trigger} — proxy=${burned.burnedProxy ? this.maskProxyCreds(proxyDisplay || "?") : "(already burned)"} seed=${burned.burnedSeed ? String(burnSeed) : "(already burned)"}`);
                    } else {
