    } else if (level === 3) {
      // Level 3: Aggressive Reload
      this.learnFromFailure(email, data.url, 'chronic_freeze');
      this.executeCdpIntervention(email, { type: 'reload' });
      // Reset timer so it gets 10s to load
      state.firstSeen = Date.now();
