    process.on('SIGINT', () => {
      log.info('🛑 Shutting down Hermes Orchestrator gracefully...');
      hermes.saveMemory();
      process.exit(0);
    });
    process.on('SIGTERM', () => {
      log.info('🛑 Shutting down Hermes Orchestrator gracefully...');
      hermes.saveMemory();
      process.exit(0);
    });

    process.on('message', (msg: any) => {
      if (msg && msg.type === 'review-now') {
