export async function verifyLoginSuccessVisually(page: Page): Promise<boolean> {
  if (!GEMINI_API_KEY) {
    console.warn("[Hermes Verifier] GEMINI_API_KEY not set. Falling back to true.");
    return true; // Fallback to pass if no API key
  }

  try {
    console.log(`[Hermes Verifier] Capturing visual snapshot for confidence verification...`);
    // Capture screenshot via raw CDP to bypass Python bridge latency (Zendriver fix)
    let base64Image = "";
    try {
      const cdp = await page.context().newCDPSession(page);
      const res = await cdp.send('Page.captureScreenshot', { format: 'jpeg', quality: 60 });
      base64Image = res.data;
    } catch {
      // Fallback to standard Playwright if CDP fails
      const screenshotBuffer = await page.screenshot({ type: "jpeg", quality: 60 });
      base64Image = screenshotBuffer.toString("base64");
    }

    const promptText = `
You are a strict QA automation AI. Look at this screenshot of a web application.
Your goal is to determine if the user is SUCCESSFULLY logged into their account.

Indicators of SUCCESS:
- You see account balances, deposit/withdrawal buttons, cashier dashboard, or an account menu.
- You see "Welcome!" or any variation with an exclamation mark (case doesn't matter, but the "!" is required).

Indicators of FAILURE / FALSE POSITIVE:
- The page is still asking for a password or login.
- The page shows a CAPTCHA or Cloudflare challenge.
- The page is a generic marketing home page without any logged-in state indicators.
- The page shows an error message.

Output EXACTLY one word: "YES" if they are logged in, or "NO" if they are not.
    `;

    const url = "https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-pro:generateContent?key=" + GEMINI_API_KEY;
    const response = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        contents: [{ 
            parts: [
                { text: promptText },
                { inlineData: { mimeType: "image/jpeg", data: base64Image } }
            ] 
        }]
      })
    });

    const json = await response.json();
    const aiResponse = json.candidates?.[0]?.content?.parts?.[0]?.text?.trim().toUpperCase();

    if (aiResponse && aiResponse.includes("YES")) {
      console.log(`[Hermes Verifier] AI Confirmed successful login (Confidence: HIGH)`);
      return true;
    } else {
      console.warn(`[Hermes Verifier] AI REJECTED success classification. Output: ${aiResponse}`);
      return false;
    }
  } catch (e: unknown) {
    console.warn(`[Hermes Verifier] Visual verification failed due to error: ${e instanceof Error ? e.message : String(e)}`);
    return true; // Fail open to not block execution
  }
}

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unused-expressions, @typescript-eslint/no-unused-vars, @typescript-eslint/require-await */
import type { Page } from "playwright-core";
import { humanClickSelector, humanScroll } from "./mouse-humanizer.js";
import { globalRLLedger } from "./ai-rl-ledger.js";

async function sleepWithSignal(ms: number, signal?: AbortSignal): Promise<void> {
  if (signal?.aborted) return;
  if (ms <= 0) return;
  return new Promise((resolve) => {
    const timer = setTimeout(() => {
      signal?.removeEventListener("abort", onAbort);
      resolve();
    }, ms);
    const onAbort = () => {
      clearTimeout(timer);
      resolve();
    };
    signal?.addEventListener("abort", onAbort);
  });
}

/**
 * Parses the page text and executes a series of logically sound but random
 * human decoy interactions (reading text, clicking non-submit links) to 
 * heavily obfuscate the bot's deterministic signature.
 * 
 * Runs concurrently and aborts instantly if the main flow signals readiness.
 */
export async function executeGenerativeDecoys(page: Page, signal?: AbortSignal): Promise<void> {
  if (signal?.aborted) return;

  const possibleDecoySelectors = [
    "text='Forgot'",
    "text='Remember'",
    "text='Help'",
    "text='Terms'",
    "text='Privacy'",
    "text='Login'"
  ];

  const scope = (page as any).__sessionId || "global";

  // 1. Synthesize a random scroll burst
  if (Math.random() < 0.6) {
    if (signal?.aborted) return;
    const scrollDelta = globalRLLedger.getTiming(scope, "decoy_scroll", 150, 50, 50, 400);
    await humanScroll(page, scrollDelta).catch(() => {});
    await sleepWithSignal(globalRLLedger.getTiming(scope, "decoy_read_pause", 100, 50, 10, 200), signal);

    if (signal?.aborted) return;
    // Scroll back up
    await humanScroll(page, -scrollDelta).catch(() => {});
  }

  // 2. Synthesize random clicks on non-destructive text
  const decoyCount = Math.floor(globalRLLedger.getTiming(scope, "decoy_count", 1, 0.5, 0, 2));

  for (let i = 0; i < decoyCount; i++) {
    if (signal?.aborted) return;
    const selector = possibleDecoySelectors[Math.floor(Math.random() * possibleDecoySelectors.length)]!;

    try {
      const isVisible = await page.locator(selector).first().isVisible({ timeout: 50 }).catch(() => false);
      if (isVisible && !signal?.aborted) {
        await humanClickSelector(page, selector, { timeout: 200 });
        await sleepWithSignal(globalRLLedger.getTiming(scope, "decoy_inter_click", 50, 25, 10, 100), signal);
      }
    } catch {
      // Ignore if element is missing or not clickable
    }
  }
}

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unused-expressions, @typescript-eslint/no-unused-vars, @typescript-eslint/require-await */
/**
 * AI Screenshot Self-Diagnosis — Improvement #1
 *
 * When a login attempt fails with a non-decisive outcome, this module
 * screenshots the page and sends it to Gemini Vision to diagnose
 * what the user is actually seeing: CAPTCHA, overlay, error message,
 * cookie wall, bot challenge, etc.
 *
 * This enables intelligent retry strategies instead of blind retries.
 */
import { GoogleGenerativeAI, type Part } from "@google/generative-ai";
import { createLogger } from "../core/logger.js";

const log = createLogger("ai-diagnosis");

const GEMINI_API_KEY = (process.env.GEMINI_API_KEY || process.env.GOOGLE_AI_API_KEY || process.env.GOOGLE_AGENT_PLATFORM_API_KEY || "").trim();
const MODEL_NAME = "gemini-2.5-flash";
const DIAGNOSIS_TIMEOUT_MS = 15_000;

export interface AiDiagnosis {
  /** Recommended action for the engine */
  action: "retry" | "dismiss_overlay" | "solve_captcha" | "switch_backend" | "abort" | "continue";
  /** What was detected on the page */
  pageState: "captcha" | "cookie_wall" | "error_message" | "bot_challenge" | "overlay" | "login_form" | "logged_in" | "unknown";
  /** Type of CAPTCHA if detected */
  captchaType?: "recaptcha" | "turnstile" | "hcaptcha" | "funcaptcha" | "custom" | null;
  /** Human-readable description of what was seen */
  details: string;
  /** Confidence level */
  confidence: "high" | "medium" | "low";
  /** Whether AI analysis was actually performed */
  signalAvailable: boolean;
  /** Processing time */
  durationMs: number;
}

const DIAGNOSIS_PROMPT = `You are an expert automation engineer analyzing a screenshot of a web page during an automated login attempt.

Analyze the screenshot and determine:
1. What is currently visible on the page?
2. Is there anything blocking the login flow?
3. What should the automation do next?

CLASSIFICATION RULES for pageState:
- "captcha" → A CAPTCHA challenge is visible (reCAPTCHA, Turnstile, hCaptcha, FunCaptcha, or custom image challenge)
- "cookie_wall" → A cookie consent banner or GDPR overlay is blocking interaction
- "bot_challenge" → A bot detection challenge page (Cloudflare "checking your browser", DataDome, Akamai challenge)
- "overlay" → Any non-login overlay/modal blocking the form (popup, ad, notification prompt)
- "error_message" → An error message is visible (wrong password, account disabled, rate limited, etc.)
- "login_form" → The login form is visible and ready for interaction
- "logged_in" → The user appears to be successfully logged in
- "unknown" → Cannot determine the page state

ACTION RULES:
- "retry" → The login form is visible, just retry the input (e.g., field wasn't filled correctly)
- "dismiss_overlay" → There's a dismissable overlay/cookie wall — click dismiss/accept/close first
- "solve_captcha" → A CAPTCHA needs solving before proceeding
- "switch_backend" → Bot challenge detected, this backend is likely fingerprinted — try another
- "abort" → Unrecoverable state (account disabled, permanent block)
- "continue" → Page looks normal, continue with login flow

If a CAPTCHA is detected, also identify the captchaType:
- "recaptcha" → Google reCAPTCHA (v2 checkbox or v3 invisible)
- "turnstile" → Cloudflare Turnstile
- "hcaptcha" → hCaptcha
- "funcaptcha" → FunCaptcha/Arkose Labs
- "custom" → Any other type of challenge

Return ONLY valid JSON matching this schema.`;

/**
 * Diagnose the current page state using AI vision.
 * Takes a screenshot buffer (PNG/JPEG) and returns actionable diagnosis.
 */
export async function aiDiagnosePage(
  screenshotBuffer: Buffer,
  context?: string,
): Promise<AiDiagnosis> {
  if (!GEMINI_API_KEY) {
    return {
      action: "continue",
      pageState: "unknown",
      details: "AI diagnosis unavailable — no Gemini API key",
      confidence: "low",
      signalAvailable: false,
      durationMs: 0,
    };
  }

  const start = Date.now();

  try {
    const genAI = new GoogleGenerativeAI(GEMINI_API_KEY);
    const model = genAI.getGenerativeModel({ model: MODEL_NAME });

    const parts: Part[] = [
      {
        inlineData: {
          mimeType: "image/png",
          data: screenshotBuffer.toString("base64"),
        },
      },
      {
        text: `${context ? `Context: ${context}\n\n` : ""}${DIAGNOSIS_PROMPT}`,
      },
    ];

    const responseSchema = {
      type: "object",
      properties: {
        action: {
          type: "string",
          description: "One of: retry, dismiss_overlay, solve_captcha, switch_backend, abort, continue",
        },
        pageState: {
          type: "string",
          description: "One of: captcha, cookie_wall, error_message, bot_challenge, overlay, login_form, logged_in, unknown",
        },
        captchaType: {
          type: "string",
          description: "If CAPTCHA detected: recaptcha, turnstile, hcaptcha, funcaptcha, custom, or null",
        },
        details: {
          type: "string",
          description: "Brief description of what is visible on the page",
        },
        confidence: {
          type: "string",
          description: "One of: high, medium, low",
        },
      },
      required: ["action", "pageState", "details", "confidence"],
    };

    let timer: NodeJS.Timeout;
    const result = await Promise.race([
      model.generateContent({
        contents: [{ role: "user", parts }],
        generationConfig: {
          responseMimeType: "application/json",
          responseSchema: responseSchema as Parameters<typeof model.generateContent>[0] extends { generationConfig?: { responseSchema?: infer S } } ? S : never,
        },
      }),
      new Promise<never>((_, reject) => {
        timer = setTimeout(() => reject(new Error("AI diagnosis timeout")), DIAGNOSIS_TIMEOUT_MS);
      })
    ]).finally(() => clearTimeout(timer));

    const responseText = result.response.text().trim();
    const durationMs = Date.now() - start;

    let parsed: { action?: string; pageState?: string; captchaType?: string | null; details?: string; confidence?: string };
    try {
      parsed = JSON.parse(responseText);
    } catch {
      log.warn(`AI diagnosis response not valid JSON: ${responseText.slice(0, 200)}`);
      return {
        action: "continue",
        pageState: "unknown",
        details: `Failed to parse AI response: ${responseText.slice(0, 100)}`,
        confidence: "low",
        signalAvailable: false,
        durationMs,
      };
    }

    const validActions = new Set(["retry", "dismiss_overlay", "solve_captcha", "switch_backend", "abort", "continue"]);
    const validStates = new Set(["captcha", "cookie_wall", "error_message", "bot_challenge", "overlay", "login_form", "logged_in", "unknown"]);

    const diagnosis: AiDiagnosis = {
      action: validActions.has(parsed.action ?? "") ? parsed.action as AiDiagnosis["action"] : "continue",
      pageState: validStates.has(parsed.pageState ?? "") ? parsed.pageState as AiDiagnosis["pageState"] : "unknown",
      captchaType: (parsed.captchaType as AiDiagnosis["captchaType"]) || null,
      details: parsed.details || "No details provided",
      confidence: (["high", "medium", "low"] as const).includes(parsed.confidence as "high" | "medium" | "low") ? parsed.confidence as AiDiagnosis["confidence"] : "low",
      signalAvailable: true,
      durationMs,
    };

    log.info(
      `🤖 AI Diagnosis: [${diagnosis.pageState}] → ${diagnosis.action} ` +
      `(${diagnosis.confidence}) — ${diagnosis.details} [${durationMs}ms]`
    );

    return diagnosis;
  } catch (err) {
    const durationMs = Date.now() - start;
    log.warn(`AI diagnosis failed: ${err instanceof Error ? err.message : String(err)}`);
    return {
      action: "continue",
      pageState: "unknown",
      details: `AI API error: ${err instanceof Error ? err.message : String(err)}`,
      confidence: "low",
      signalAvailable: false,
      durationMs,
    };
  }
}

/**
 * Quick pre-login CAPTCHA check — Improvement #4
 * Lightweight check specifically for CAPTCHA/bot challenge presence.
 */
export async function aiDetectCaptcha(
  screenshotBuffer: Buffer,
): Promise<{ hasCaptcha: boolean; type: string | null; hasBotChallenge: boolean }> {
  const diagnosis = await aiDiagnosePage(screenshotBuffer, "Pre-login page check — looking for CAPTCHAs or bot challenges");

  return {
    hasCaptcha: diagnosis.pageState === "captcha",
    type: diagnosis.captchaType || null,
    hasBotChallenge: diagnosis.pageState === "bot_challenge",
  };
}

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unused-expressions, @typescript-eslint/no-unused-vars, @typescript-eslint/require-await */
/**
 * AI-Driven Behavioral Profile Generation — Improvement #5
 *
 * Uses Gemini to generate persona-based behavioral parameters:
 * typing speed, mouse speed, scroll patterns, reading speed, error rates.
 * Each email seed gets a unique, realistic persona that feeds into
 * the Gaussian RNG distributions for typing, mouse, and scroll behaviors.
 *
 * Results are cached per email seed to avoid repeated API calls.
 */
import fs from 'node:fs';
import path from 'node:path';
import { createLogger } from "../core/logger.js";
import { GoogleGenerativeAI } from "@google/generative-ai";

const log = createLogger("ai-persona");

const GEMINI_API_KEY = (process.env.GEMINI_API_KEY || process.env.GOOGLE_AI_API_KEY || process.env.GOOGLE_AGENT_PLATFORM_API_KEY || "").trim();
const MODEL_NAME = "gemini-2.5-flash";
const CACHE_FILE = path.resolve(process.cwd(), "persona-cache.json");
const AI_TIMEOUT_MS = 15_000;

export interface BehavioralPersona {
  /** Words per minute for typing (30-90 range) */
  typingWpm: number;
  /** Base inter-key delay in ms */
  baseKeyDelayMs: number;
  /** Mouse speed multiplier (0.5 = slow, 1.0 = normal, 1.5 = fast) */
  mouseSpeedMultiplier: number;
  /** Scroll speed multiplier */
  scrollSpeedMultiplier: number;
  /** Reading speed — ms per word on screen */
  readingMsPerWord: number;
  /** Probability of typing error (0.01-0.08) */
  typoRate: number;
  /** Tendency to pause while typing (0.0-1.0) */
  pauseTendency: number;
  /** How erratic mouse movements are (0.3-1.5) */
  mouseJitter: number;
  /** Generated persona description */
  personaDescription: string;
  /** Whether this was AI-generated or fallback */
  source: "ai" | "fallback";
}

// In-memory cache loaded from disk
let personaCache: Record<string, BehavioralPersona> = {};
try {
  if (fs.existsSync(CACHE_FILE)) {
    personaCache = JSON.parse(fs.readFileSync(CACHE_FILE, "utf-8"));
  }
} catch (e) {
  log.warn(`Failed to load persona cache: ${String(e)}`);
}

function saveCache() {
  try {
    fs.writeFileSync(CACHE_FILE, JSON.stringify(personaCache, null, 2), "utf-8");
  } catch (e) {
    log.warn(`Failed to save persona cache: ${String(e)}`);
  }
}

const PERSONA_PROMPT = `You are generating realistic browser interaction behavioral parameters for a simulated human user.

Create a believable persona with natural browsing characteristics. The persona should feel like a real person — not a power user, not unusually slow, just normal human variation.

Generate the following parameters:
- typingWpm: Words per minute (realistic range: 25 for elderly/non-native to 85 for fast typist. Average: 40-55)
- baseKeyDelayMs: Milliseconds between keystrokes (derived from WPM but with personality. 70-200ms range)
- mouseSpeedMultiplier: How fast they move the mouse (0.6 = deliberate/careful, 1.0 = average, 1.4 = quick/impatient)
- scrollSpeedMultiplier: How fast they scroll (0.5 = reads carefully, 1.0 = normal, 1.5 = skims)
- readingMsPerWord: How long they spend per word when reading (150-400ms)
- typoRate: Probability of making a typo per character (0.01 = careful, 0.06 = sloppy)
- pauseTendency: How often they pause mid-action (0.1 = focused, 0.7 = easily distracted)
- mouseJitter: How shaky/imprecise their mouse movements are (0.3 = precise gamer, 1.2 = elderly/touchpad)
- personaDescription: One-sentence description of this persona (e.g., "A 45-year-old office worker browsing during lunch break on a Windows laptop")

Make the parameters internally consistent — e.g., a fast typist should have low baseKeyDelayMs, a careful reader should have high readingMsPerWord and low scrollSpeedMultiplier.

Return ONLY valid JSON.`;

/**
 * Generate or retrieve a behavioral persona for an email seed.
 * Uses AI when available, falls back to deterministic generation from seed.
 */
export async function getPersona(emailSeed: number): Promise<BehavioralPersona> {
  const cacheKey = `persona-${emailSeed}`;

  // Return cached persona
  if (personaCache[cacheKey]) {
    return personaCache[cacheKey];
  }

  // Try AI generation
  if (GEMINI_API_KEY) {
    try {
      const persona = await generateAiPersona(emailSeed);
      personaCache[cacheKey] = persona;
      saveCache();
      log.info(`🤖 AI Persona generated: ${persona.personaDescription} (WPM=${persona.typingWpm}, mouse=${persona.mouseSpeedMultiplier.toFixed(2)})`);
      return persona;
    } catch (err) {
      log.warn(`AI persona generation failed, using fallback: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  // Deterministic fallback from seed
  const fallback = generateFallbackPersona(emailSeed);
  personaCache[cacheKey] = fallback;
  saveCache();
  return fallback;
}

async function generateAiPersona(seed: number): Promise<BehavioralPersona> {
  const genAI = new GoogleGenerativeAI(GEMINI_API_KEY);
  const model = genAI.getGenerativeModel({ model: MODEL_NAME });

  const responseSchema = {
    type: "object",
    properties: {
      typingWpm: { type: "number" },
      baseKeyDelayMs: { type: "number" },
      mouseSpeedMultiplier: { type: "number" },
      scrollSpeedMultiplier: { type: "number" },
      readingMsPerWord: { type: "number" },
      typoRate: { type: "number" },
      pauseTendency: { type: "number" },
      mouseJitter: { type: "number" },
      personaDescription: { type: "string" },
    },
    required: [
      "typingWpm", "baseKeyDelayMs", "mouseSpeedMultiplier",
      "scrollSpeedMultiplier", "readingMsPerWord", "typoRate",
      "pauseTendency", "mouseJitter", "personaDescription",
    ],
  };

  let timer: NodeJS.Timeout;
  const result = await Promise.race([
    model.generateContent({
      contents: [{
        role: "user",
        parts: [{ text: `Seed: ${seed}\n\n${PERSONA_PROMPT}` }],
      }],
      generationConfig: {
        responseMimeType: "application/json",
        responseSchema: responseSchema as any,
      },
    }),
    new Promise<never>((_, reject) => {
      timer = setTimeout(() => reject(new Error("AI persona timeout")), AI_TIMEOUT_MS);
    }),
  ]).finally(() => clearTimeout(timer));

  const parsed = JSON.parse(result.response.text().trim());

  return {
    typingWpm: clamp(parsed.typingWpm || 45, 20, 100),
    baseKeyDelayMs: clamp(parsed.baseKeyDelayMs || 100, 40, 250),
    mouseSpeedMultiplier: clamp(parsed.mouseSpeedMultiplier || 1.0, 0.4, 1.8),
    scrollSpeedMultiplier: clamp(parsed.scrollSpeedMultiplier || 1.0, 0.3, 2.0),
    readingMsPerWord: clamp(parsed.readingMsPerWord || 250, 100, 500),
    typoRate: clamp(parsed.typoRate || 0.03, 0.005, 0.10),
    pauseTendency: clamp(parsed.pauseTendency || 0.3, 0.05, 0.8),
    mouseJitter: clamp(parsed.mouseJitter || 0.6, 0.2, 1.8),
    personaDescription: parsed.personaDescription || "AI-generated persona",
    source: "ai",
  };
}

/**
 * Deterministic fallback persona generation from seed.
 * Uses hash-based distribution to create varied but consistent personas.
 */
function generateFallbackPersona(seed: number): BehavioralPersona {
  // Use seed to deterministically generate persona parameters
  const h = (offset: number) => {
    const x = Math.sin(seed + offset) * 10000;
    return x - Math.floor(x); // 0-1 range
  };

  const typingWpm = Math.round(30 + h(1) * 50); // 30-80
  const baseKeyDelayMs = Math.round(60000 / (typingWpm * 5)); // Derived from WPM

  return {
    typingWpm,
    baseKeyDelayMs,
    mouseSpeedMultiplier: 0.6 + h(2) * 0.8, // 0.6-1.4
    scrollSpeedMultiplier: 0.5 + h(3) * 1.0, // 0.5-1.5
    readingMsPerWord: Math.round(150 + h(4) * 250), // 150-400
    typoRate: 0.01 + h(5) * 0.05, // 0.01-0.06
    pauseTendency: 0.1 + h(6) * 0.5, // 0.1-0.6
    mouseJitter: 0.3 + h(7) * 0.9, // 0.3-1.2
    personaDescription: `Deterministic persona (seed ${seed})`,
    source: "fallback",
  };
}

function clamp(val: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, val));
}

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unused-expressions, @typescript-eslint/no-unused-vars, @typescript-eslint/require-await */
import fs from "fs";
import path from "path";
import { gaussianClamped } from "../core/gaussian-rng.js";

const LEDGER_PATH = path.join(process.cwd(), "rl-timings.json");

interface LedgerEntry {
  mean: number;
  stdDev: number;
  min: number;
  max: number;
  successes: number;
  failures: number;
}

interface LedgerData {
  [key: string]: LedgerEntry;
}

export class RLLedger {
  private data: LedgerData = {};
  private currentRunKeys: Map<string, Set<string>> = new Map();

  constructor() {
    this.load();
  }

  private load() {
    try {
      if (fs.existsSync(LEDGER_PATH)) {
        this.data = JSON.parse(fs.readFileSync(LEDGER_PATH, "utf-8"));
      }
    } catch {
      this.data = {};
    }
  }

  public save() {
    try {
      fs.writeFileSync(LEDGER_PATH, JSON.stringify(this.data, null, 2), "utf-8");
    } catch { /* intentional */ }
  }

  /**
   * Get a timing value, automatically using the learned mean/stdDev if it exists,
   * otherwise falling back to the defaults and registering it.
   */
  public getTiming(scope: string, key: string, defaultMean: number, defaultStdDev: number, defaultMin: number, defaultMax: number): number {
    if (!this.currentRunKeys.has(scope)) {
      this.currentRunKeys.set(scope, new Set());
    }
    this.currentRunKeys.get(scope)!.add(key);

    if (!this.data[key]) {
      this.data[key] = {
        mean: defaultMean,
        stdDev: defaultStdDev,
        min: defaultMin,
        max: defaultMax,
        successes: 0,
        failures: 0
      };
      this.save();
    }

    const entry = this.data[key];
    // Clamp the learned mean to reasonable bounds (never less than 50% of default min)
    const activeMean = Math.max(defaultMin * 0.5, Math.min(entry.mean, defaultMax * 1.5));
    const activeStdDev = Math.max(defaultStdDev * 0.5, Math.min(entry.stdDev, defaultStdDev * 2));

    return gaussianClamped(activeMean, activeStdDev, defaultMin, defaultMax);
  }

  /**
   * Call this at the end of a session to score the timings.
   * If success = true, the timings slightly tighten (speed up).
   * If success = false, the timings slightly widen (slow down, more human).
   */
  public reportOutcome(scope: string, success: boolean) {
    const keys = this.currentRunKeys.get(scope);
    if (!keys) return;

    for (const key of keys) {
      const entry = this.data[key];
      if (!entry) continue;

      const alpha = 0.1; // learning rate
      if (success) {
        entry.successes++;
        // Speed up target (10% faster)
        const targetMean = entry.mean * 0.9;
        const targetStdDev = entry.stdDev * 0.95;
        // Exponential Moving Average update
        entry.mean = (1 - alpha) * entry.mean + alpha * targetMean;
        entry.stdDev = (1 - alpha) * entry.stdDev + alpha * targetStdDev;
      } else {
        entry.failures++;
        // Slow down target (20% slower, more human caution)
        const targetMean = entry.mean * 1.2;
        const targetStdDev = entry.stdDev * 1.2;
        // Exponential Moving Average update
        entry.mean = (1 - alpha) * entry.mean + alpha * targetMean;
        entry.stdDev = (1 - alpha) * entry.stdDev + alpha * targetStdDev;
      }
    }
    this.save();
    this.currentRunKeys.delete(scope);
  }

  /**
   * Return a snapshot of the current learned timings for telemetry capture.
   */
  public getTimingSnapshot(): Record<string, LedgerEntry> {
    return JSON.parse(JSON.stringify(this.data));
  }
}

export const globalRLLedger = new RLLedger();

