// Mobile-only geo entries. Coordinates are slight offsets from each capital's
// CBD to mimic tower-level dispersion. Network-type weighting biases 5G in
// metros, 4G elsewhere.
const AU_MOBILE_GEOS: Array<{
  city: string;
  region: "VIC" | "NSW" | "QLD" | "WA" | "SA";
