function isMobileScreen(x: unknown): boolean {
  if (x === undefined) return true;
  if (!x || typeof x !== "object") return false;
  const s = x as Record<string, unknown>;
  return typeof s.width === "number" && Number.isFinite(s.width)
    && typeof s.height === "number" && Number.isFinite(s.height)
    && typeof s.pixelRatio === "number" && Number.isFinite(s.pixelRatio);
}

function isMobileConnection(x: unknown): boolean {
  if (x === undefined) return true;
  if (!x || typeof x !== "object") return false;
  const c = x as Record<string, unknown>;
  return typeof c.type === "string" && c.type.length > 0
    && typeof c.downlink === "number" && Number.isFinite(c.downlink)
    && typeof c.rtt === "number" && Number.isFinite(c.rtt);
}

function isUAProfile(x: unknown): x is UAProfile {
  if (!x || typeof x !== "object") return false;
  const o = x as Record<string, unknown>;
  const baseOk = typeof o.ua === "string" && o.ua.startsWith("Mozilla/5.0")
    && typeof o.chromeVersion === "string" && typeof o.chromeMajor === "number"
    && typeof o.platformVersion === "string" && typeof o.windowsVersion === "string"
    && (o.os === "windows" || o.os === "macos" || o.os === "linux" || o.os === "android")
    && (o.architecture === "x64" || o.architecture === "arm64")
    && typeof o.windowsLabel === "string"
    && (o.isBot === undefined || typeof o.isBot === "boolean")
    && (o.mobile === undefined || typeof o.mobile === "boolean");
  if (!baseOk) return false;

  if (o.deviceModel !== undefined && typeof o.deviceModel !== "string") return false;
  if (o.deviceMemory !== undefined && (typeof o.deviceMemory !== "number" || !Number.isFinite(o.deviceMemory))) return false;
  if (!isMobileScreen(o.screen)) return false;
  if (o.touchSupport !== undefined && typeof o.touchSupport !== "boolean") return false;
  if (o.webgl !== undefined) {
    if (!o.webgl || typeof o.webgl !== "object") return false;
    const w = o.webgl as Record<string, unknown>;
    if (typeof w.vendor !== "string" || typeof w.renderer !== "string") return false;
  }
  if (o.battery !== undefined) {
    if (!o.battery || typeof o.battery !== "object") return false;
    const b = o.battery as Record<string, unknown>;
    if (typeof b.charging !== "boolean") return false;
    if (typeof b.level !== "number" || !Number.isFinite(b.level)) return false;
  }
  if (!isMobileConnection(o.connection)) return false;
  return true;
}

function loadPool(filename: string): UAProfile[] {
  const candidates = [
    path.resolve(process.cwd(), "data", filename),
    path.resolve(__dirname, "data", filename),
    path.resolve(__dirname, "..", "data", filename),
  ];
  for (const p of candidates) {
    try {
      if (!fs.existsSync(p)) continue;
      const raw = JSON.parse(fs.readFileSync(p, "utf-8"));
      const pool: unknown[] = Array.isArray(raw?.pool) ? raw.pool : Array.isArray(raw) ? raw : [];
      const valid = pool.filter(isUAProfile);
      const dropped = pool.length - valid.length;
      if (dropped > 0) {
        log.warn(`${p}: dropped ${dropped} of ${pool.length} entries failing shape validation`);
      }
      if (valid.length > 0) return valid;
    } catch (e: unknown) {
      log.warn(`failed to load ${p}: ${(e instanceof Error ? e.message : String(e)) || e}`);
    }
  }
  log.warn(`data/${filename} not found — falling back to bundled pool`);
  return BUNDLED_POOL;
}

const UA_POOL_CHROME: UAProfile[] = loadPool("ua-pool-chrome.json");
const UA_POOL_FIREFOX: UAProfile[] = loadPool("ua-pool-firefox.json");

function hashEmail(email: string, rotation: number = 0): number {
  let normalized = email.trim().toLowerCase();
  if (rotation > 0) normalized = `${normalized}:rot${rotation}`;
  const digest = crypto.createHash("sha256").update(normalized).digest();
  return digest.readUInt32BE(0);
}

export type TargetOS = "off" | "auto" | "auto-proxy" | "mixed" | "macos" | "windows" | "android" | "linux";
/** Only 3 valid strategies remain after audit-driven consolidation:
 *  - "optimal"     → Auto-selects per-backend tier (stealth=zero JS, cloak=supplementary, zendriver=full)
 *  - "native-only" → Zero JS injection, rely entirely on binary-level patches
 *  - "full-stealth" → Maximum JS injection regardless of backend
 *  Legacy aliases kept for backward compat with saved configs: */
export type FpStrategy = "optimal" | "native-only" | "full-stealth" | "fp-auto" | "fp-camoufox" | "fp-cloak" | "fp-zendriver" | "none" | "fp-fb-optimized" | "apify";

type PrecomputedMap = Record<TargetOS, UAProfile[]>;

function buildPrecomputedPools(pool: UAProfile[]): PrecomputedMap {
  const noBots = pool.filter(p => !p.isBot);
  const mixed = noBots.length > 0 ? noBots : pool;
  return {
    off: [],
    auto: [],
    "auto-proxy": [],
    mixed,
    macos: noBots.filter(p => p.os === "macos"),
    windows: noBots.filter(p => p.os === "windows"),
    android: noBots.filter(p => p.os === "android"),
    linux: noBots.filter(p => p.os === "linux")
  };
}

const PRECOMPUTED_POOLS_CHROME = buildPrecomputedPools(UA_POOL_CHROME);
const PRECOMPUTED_POOLS_FIREFOX = buildPrecomputedPools(UA_POOL_FIREFOX);

export function getConsistentUserAgent(
  email: string, 
  targetOs: TargetOS = "mixed",
  proxyString?: string,
  engine: "chrome" | "firefox" = "chrome",
  rotation: number = 0
): UAProfile | undefined {
  if (targetOs === "off") return undefined;

  let resolvedOs = targetOs;
  if (targetOs === "auto") {
    const h = hashEmail(email, rotation) % 100;
    if (h < 60) resolvedOs = "windows";
    else if (h < 75) resolvedOs = "macos";
    else if (h < 95) resolvedOs = "android";
    else resolvedOs = "linux";
  } else if (targetOs === "auto-proxy") {
    if (proxyString && proxyString.includes("spider") && proxyString.includes("au")) {
      const h = hashEmail(email, rotation) % 100;
      resolvedOs = h < 70 ? "windows" : "macos";
    } else {
      resolvedOs = "mixed";
    }
  }

  const precomputed = engine === "chrome" ? PRECOMPUTED_POOLS_CHROME : PRECOMPUTED_POOLS_FIREFOX;

  let pool = precomputed[resolvedOs as keyof typeof precomputed];
  if (!pool || pool.length === 0) {
    pool = precomputed.mixed;
  }

  if (!pool || pool.length === 0) return undefined;

  const h = hashEmail(email, rotation);
  return pool[h % pool.length];
}

export function getConsistentUserAgentWithLog(
  email: string,
  targetOs: TargetOS = "mixed",
  proxyString?: string,
  onLog?: (msg: string) => void,
  rotation: number = 0
): UAProfile | undefined {
  const ua = getConsistentUserAgent(email, targetOs, proxyString, "chrome", rotation);
  if (ua) {
    const mut = rotation > 0 ? ` (mut${rotation})` : "";
    const msg = `UA freshness${mut}: ${email} → Chrome ${ua.chromeMajor} on ${ua.windowsLabel} (${ua.windowsVersion})`;
    if (onLog) onLog(msg);
  }
  return ua;
}

export function getUserAgentArgs(profile: UAProfile): string[] {
  const platform = profile.os === "macos" ? "macOS"
    : profile.os === "android" ? "Android"
    : profile.os === "linux" ? "Linux"
    : "Windows";
  const args = [
    `--fingerprint-platform=${platform}`,
    `--fingerprint-platform-version=${profile.platformVersion}`,
    `--fingerprint-architecture=${profile.architecture}`,
    `--fingerprint-browser-version=${profile.chromeVersion}`,
  ];
  if (profile.mobile) {
    args.push("--fingerprint-mobile");
    if (profile.screen) {
      args.push(`--fingerprint-screen=${profile.screen.width}x${profile.screen.height}`);
      args.push(`--fingerprint-device-scale-factor=${profile.screen.pixelRatio}`);
    }
    if (profile.touchSupport) args.push("--fingerprint-touch-events");
    if (profile.deviceMemory) args.push(`--fingerprint-device-memory=${profile.deviceMemory}`);
    if (profile.connection) args.push(`--fingerprint-network-type=${profile.connection.type}`);
  }
  return args;
}

export function getUserAgentPoolSize(): number {
  return UA_POOL_CHROME.length;
}

export function listUserAgentPool(): readonly UAProfile[] {
  return UA_POOL_CHROME;
}

export const _test = {
  isMobileScreen,
  isMobileConnection,
  isUAProfile,
  loadPool
};

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unused-expressions, @typescript-eslint/no-unused-vars, @typescript-eslint/require-await */
/**
 * Profile Bundle Validator
 *
 * Each profile sub-module (UA, cache, geo, resolution, hardware, fonts) is
 * deterministic in isolation. Bot-detection vendors don't query them in
 * isolation though — they cross-check (e.g. UA Chrome major vs. the
 * client_id cached under a stale browser_version key, or navigator.timezone
 * vs. the proxy exit country). validateProfileBundle() catches the
 * cross-field drifts that cause those vendor checks to fire.
 *
 * Determinism is re-asserted by recomputing each profile from the email and
 * comparing — if a caller stitched together values from different runs (or
 * different libraries), the mismatch surfaces here instead of at runtime.
 */
import { getConsistentHardware, type HardwareProfile } from "./profile-determinism.js";
import { getConsistentUserAgent, type UAProfile } from "./profile-useragent.js";
import { alignGeoToProxy, type GeoProfile } from "./profile-geo-alignment.js";
import { getConsistentResolution, type Resolution } from "./profile-resolution.js";
import { getFontProfile, type FontProfile } from "./profile-fonts.js";
import { getCacheProfile, type CacheProfile } from "./profile-cache.js";
import { profileMetrics } from "./profile-metrics.js";

export interface ProfileBundle {
  email: string;
  ua?: UAProfile;
  cache?: CacheProfile;
  geo?: GeoProfile;
  resolution?: Resolution;
  hardware?: HardwareProfile;
  fonts?: FontProfile;
  /** Optional proxy server string used to derive the expected geo. */
  proxy?: string;
}

export interface ProfileBundleValidation {
  ok: boolean;
  errors: string[];
  warnings: string[];
}

function pushIf<_T>(arr: string[], cond: boolean, msg: string): void {
  if (cond) arr.push(msg);
}

function shallowEqual(a: any, b: any): boolean {
  if (a === b) return true;
  if (!a || !b || typeof a !== "object" || typeof b !== "object") return false;
  const ka = Object.keys(a);
  const kb = Object.keys(b);
  if (ka.length !== kb.length) return false;
  for (const k of ka) {
    const va = a[k];
    const vb = b[k];
    if (va && typeof va === "object") {
      if (!shallowEqual(va, vb)) return false;
    } else if (va !== vb) {
      return false;
    }
  }
  return true;
}

export function validateProfileBundle(bundle: ProfileBundle): ProfileBundleValidation {
  const errors: string[] = [];
  const warnings: string[] = [];
  const { email } = bundle;

  if (!email || !email.trim()) {
    errors.push("email: missing");
    profileMetrics.recordValidationFailed();
    return { ok: false, errors, warnings };
  }

  if (bundle.ua) {
    const expected = getConsistentUserAgent(email)!;
    pushIf(errors, !shallowEqual(bundle.ua, expected),
      `ua: drift — got chromeMajor=${bundle.ua.chromeMajor}/${bundle.ua.windowsLabel}, expected ${expected.chromeMajor}/${expected.windowsLabel}`);
  }

  if (bundle.hardware) {
    // Hardware drift is OS-conditional: an NVIDIA renderer on a macOS UA is a
    // separate concern from a same-OS preset mismatch. Use the bundle UA's OS
    // so the expected hardware is drawn from the matching pool.
    const expected = getConsistentHardware(email, bundle.ua?.os);
    pushIf(errors, !shallowEqual(bundle.hardware, expected),
      `hardware: drift — got ${bundle.hardware.cores}c/${bundle.hardware.memory}GB ${bundle.hardware.gpu.renderer}, expected ${expected.cores}c/${expected.memory}GB ${expected.gpu.renderer}`);
  }

  if (bundle.fonts) {
    const expected = getFontProfile(email);
    pushIf(errors, bundle.fonts.name !== expected.name,
      `fonts: drift — got ${bundle.fonts.name}, expected ${expected.name}`);
  }

  if (bundle.resolution) {
    const expected = getConsistentResolution(email);
    pushIf(errors,
      bundle.resolution.width !== expected.width || bundle.resolution.height !== expected.height,
      `resolution: drift — got ${bundle.resolution.width}x${bundle.resolution.height}, expected ${expected.width}x${expected.height}`);
    pushIf(errors, bundle.resolution.width <= 0 || bundle.resolution.height <= 0,
      `resolution: invalid dimensions ${bundle.resolution.width}x${bundle.resolution.height}`);
  }

  if (bundle.cache) {
    const expected = getCacheProfile(email, bundle.cache.chromeMajor);
    pushIf(errors, bundle.cache.clientId !== expected.clientId,
      `cache: clientId drift — got ${bundle.cache.clientId}, expected ${expected.clientId}`);
    pushIf(errors, bundle.cache.lastVisitDaysAgo !== expected.lastVisitDaysAgo,
      `cache: lastVisitDaysAgo drift — got ${bundle.cache.lastVisitDaysAgo}, expected ${expected.lastVisitDaysAgo}`);
  }

  // Cross-field: UA chromeMajor must match the cache profile's chromeMajor.
  // Vendors inspect localStorage.browser_version (seeded from the cache
  // profile) and the actual navigator.userAgent — when they disagree the
  // session looks like a profile that survived a Chrome version change
  // without clearing localStorage, which is a "stale automation" tell.
  if (bundle.ua && bundle.cache) {
    pushIf(errors, bundle.ua.chromeMajor !== bundle.cache.chromeMajor,
      `cross: UA.chromeMajor=${bundle.ua.chromeMajor} ≠ cache.chromeMajor=${bundle.cache.chromeMajor}`);
  }

  // Cross-field: geo profile country must match proxy-derived country.
  // Mismatched timezone/locale vs. IP geo is one of the cheapest "headless
  // automation" tells — covered by alignGeoToProxy at session creation,
  // but a bundle might be constructed from cached pieces.
  if (bundle.geo && bundle.proxy !== undefined) {
    const expected = alignGeoToProxy(bundle.proxy);
    pushIf(errors, bundle.geo.countryCode !== expected.countryCode,
      `cross: geo.countryCode=${bundle.geo.countryCode} ≠ proxy-derived ${expected.countryCode}`);
  }

  // Warn-only: missing recommended fields. These don't break the session but
  // weaken the consistency story across the bundle.
  pushIf(warnings, !bundle.ua, "ua: missing");
  pushIf(warnings, !bundle.cache, "cache: missing");
  pushIf(warnings, !bundle.hardware, "hardware: missing");
  pushIf(warnings, !bundle.resolution, "resolution: missing");

  const ok = errors.length === 0;
  if (!ok) profileMetrics.recordValidationFailed();
  return { ok, errors, warnings };
}

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unused-expressions, @typescript-eslint/no-unused-vars, @typescript-eslint/require-await */
import os from "node:os";
import { exec as execCb } from "node:child_process";
import { promisify } from "node:util";
const exec = promisify(execCb);
import { getEnvInt } from "../core/env-utils.js";
import { createLogger } from "../core/logger.js";

const log = createLogger("viewport-resolver");
import {
  getConsistentResolution,
  getConsistentDeviceScaleFactor,
  type Resolution
} from "./profile-resolution.js";

export type ResolverMode = "headless" | "headless-live" | "headed-grid" | "headed-live";

export interface ScreenBounds {
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface ResolvedViewport {
  viewport: { width: number; height: number } | null;
  windowSize: { width: number; height: number } | null;
  windowPosition: { x: number; y: number } | null;
  deviceScaleFactor: number;
  forceDpr: boolean;
  resolutionLabel: string;
}

export interface ResolverInput {
  email?: string;
  mode: ResolverMode;
  screen: ScreenBounds;
  slotBounds?: ScreenBounds;
  explicitViewport?: { width: number; height: number };
  nativeDpr?: number;
  rotation?: number;
}

const PLATFORM = os.platform();
const IS_MAC = PLATFORM === "darwin";

let cachedScreenBounds: ScreenBounds | null = null;

/**
 * Detect the actual usable screen size. Platform-aware (macOS, Windows).
 * Cached after first call. Never throws.
 */
export async function resolveScreenBounds(): Promise<ScreenBounds> {
  if (cachedScreenBounds) return cachedScreenBounds;

  const fallback = IS_MAC
    ? { width: 1512, height: 945, menuY: 26 }
    : { width: 1920, height: 1040, menuY: 0 };

  const opts = { encoding: "utf-8" as const, timeout: 2500, stdio: ["ignore", "pipe", "ignore"] as any };
  let detected = { ...fallback };

  try {
    if (IS_MAC) {
      try {
        const { stdout: sp } = await exec(`system_profiler SPDisplaysDataType 2>/dev/null`, opts);
        const m = sp.match(/Resolution:\s*(\d+)\s*x\s*(\d+)/);
        if (m) {
          // @ts-expect-error noUncheckedIndexedAccess
          const w = parseInt(m[1], 10);
          // @ts-expect-error noUncheckedIndexedAccess
          const h = parseInt(m[2], 10);
          const logicalW = w > 2000 ? Math.round(w / 2) : w;
          const logicalH = h > 1400 ? Math.round(h / 2) : h;
          detected = { width: logicalW, height: logicalH - 26, menuY: 26 };
        }
      } catch {
        const { stdout } = await exec(
          `osascript -e 'tell application "Finder" to get bounds of window of desktop'`,
          opts
        );
        const out = stdout.trim();
        const m = out.match(/(\d+),\s*(\d+),\s*(\d+),\s*(\d+)/);
        if (m) {
          // @ts-expect-error noUncheckedIndexedAccess
          const right = parseInt(m[3], 10);
          // @ts-expect-error noUncheckedIndexedAccess
          const bottom = parseInt(m[4], 10);
          detected = { width: right, height: bottom - 26, menuY: 26 };
        }
      }
    } else if (PLATFORM === "win32") {
      const { stdout } = await exec(
        `powershell -Command "Add-Type -AssemblyName System.Windows.Forms; [System.Windows.Forms.Screen]::PrimaryScreen.WorkingArea | Select Width,Height | ConvertTo-Csv -NoTypeInformation"`,
        opts
      );
      const out = stdout;
      const lines = out.trim().split(/\r?\n/);
      if (lines.length >= 2) {
        // @ts-expect-error noUncheckedIndexedAccess
        const [w, h] = lines[1].replace(/"/g, "").split(",").map((s) => parseInt(s, 10));
        if (w && h) detected = { width: w, height: h, menuY: 0 };
      }
    }
  } catch {
    // Keep fallback
  }

  const width = getEnvInt("SCREEN_WIDTH", detected.width);
  const height = getEnvInt("SCREEN_HEIGHT", detected.height);
  const index = getEnvInt("SCREEN_INDEX", 0);
  const x = getEnvInt("SCREEN_X", index * width);
  const y = getEnvInt("SCREEN_Y", detected.menuY);

  cachedScreenBounds = { x, y, width, height };
  log.info(`Screen: ${width}×${height} @ (${x},${y}) (index=${index})`);
  return cachedScreenBounds;
}

/**
 * Single source of truth for window/viewport/DPR selection.
 */
export function resolveViewport(input: ResolverInput): ResolvedViewport {
  const { email, mode, screen, slotBounds, explicitViewport, nativeDpr, rotation = 0 } = input;

  // 1. Determine base resolution and DPR from credential (or fallback)
  let res: Resolution;
  let dpr: number;

  if (email) {
    res = getConsistentResolution(email, undefined, rotation);
    dpr = getConsistentDeviceScaleFactor(email, rotation);
  } else {
    res = { width: 1920, height: 1080, share: 0, label: "FHD-fallback" };
    dpr = 1.0;
  }

  // Defensive: swap to landscape if pool produces portrait (existing pool is all landscape)
  if (res.height > res.width) {
    log.warn(`Swap portrait to landscape for ${res.label}`);
    const tmp = res.width;
    res.width = res.height;
    res.height = tmp;
  }

  // 2. Resolve Viewport
  let viewport: { width: number; height: number } | null = null;

  if (mode === "headed-live" || mode === "headed-grid") {
    // headed-live or headed-grid: let Chromium use real window area
    // explicitViewport MUST be ignored to comply with strict-dynamic-viewports
    viewport = null;
  } else if (explicitViewport) {
    viewport = { ...explicitViewport };
  } else if (mode === "headless") {
    // Mathematically align inner viewport with realistic OS taskbar and browser chrome footprint.
    // Typical Windows/Mac chrome + taskbar footprint is ~104px height.
    viewport = { width: res.width, height: Math.max(500, res.height - 104) };
  } else if (mode === "headless-live") {
    // Live diagnostics should match the visible headed-live surface as closely
    // as possible while still running without a native window.
    viewport = { width: screen.width, height: screen.height };
  }

  // 3. Resolve Window Size & Position
  let windowSize: { width: number; height: number } | null = null;
  let windowPosition: { x: number; y: number } | null = null;
  let resolutionLabel = res.label;

  if (mode === "headed-live") {
    windowSize = { width: screen.width, height: screen.height };
    windowPosition = { x: screen.x, y: screen.y };
    resolutionLabel = `headed-live (${windowSize.width}x${windowSize.height})`;
  } else if (mode === "headless-live") {
    resolutionLabel = `headless-live (${screen.width}x${screen.height})`;
  } else if (mode === "headed-grid" && slotBounds) {
    windowSize = { width: slotBounds.width, height: slotBounds.height };
    windowPosition = { x: slotBounds.x, y: slotBounds.y };
    resolutionLabel = `headed-grid (${windowSize.width}x${windowSize.height})`;
  }

  // 4. Determine if we should force DPR
  // forceDpr is true ONLY for headless mode (or headed when nativeDpr matches within ±0.01)
  let forceDpr = false;
  if (mode === "headless" || mode === "headless-live") {
    forceDpr = true;
  } else if (mode === "headed-live" || mode === "headed-grid") {
    // Reduce zoom/scale for headful modes so we can see the full viewport when tiled
    dpr = 0.7;
    forceDpr = true;
  } else if (nativeDpr !== undefined && Math.abs(nativeDpr - dpr) <= 0.01) {
    forceDpr = true;
  }

  return {
    viewport,
    windowSize,
    windowPosition,
    deviceScaleFactor: dpr,
    forceDpr,
    resolutionLabel,
  };
}

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unused-expressions, @typescript-eslint/no-unused-vars, @typescript-eslint/require-await */
import * as http from "http";
import * as net from "net";
import { SocksClient } from "socks";
import { SocksProxyAgent } from "socks-proxy-agent";

export type ForwardProxyEntry = { server: string; username?: string; password?: string };

export interface ProxyForwarder {
  serverUrl: string;
  close: () => Promise<void>;
}

/**
 * Local unauthenticated HTTP forward proxy.
 *
 * Chromium headed has long-standing edge cases where authenticated upstream
 * proxies intermittently surface as net::ERR_INVALID_AUTH_CREDENTIALS even
 * when credentials are correct. The robust workaround is to point Chromium at
 * localhost without credentials and let this forwarder inject
 * Proxy-Authorization for both CONNECT and plain HTTP requests.
 * 
 * SOCKS5 upstreams are now natively bridged to this local HTTP proxy, preventing
 * Playwright SOCKS5 auth bugs.
 */
export async function startProxyForwarder(upstream: ForwardProxyEntry, _clientProfile: string = "chrome"): Promise<ProxyForwarder> {
  if (!upstream?.server || typeof upstream.server !== "string") {
    throw new Error("proxy forwarder requires upstream.server");
  }
  let u: URL;
  try {
    u = new URL(upstream.server);
  } catch (err: unknown) {
    throw new Error(`invalid upstream proxy URL: ${(err instanceof Error ? err.message : String(err)) || err}`);
  }
  if (u.protocol !== "http:" && u.protocol !== "socks5:") {
    throw new Error(`proxy forwarder only supports http and socks5 upstream proxies, got ${u.protocol}`);
  }
  if (!u.hostname) throw new Error("upstream proxy URL is missing hostname");
  const upstreamHost = u.hostname;
  const upstreamPort = Number(u.port || (u.protocol === "socks5:" ? 1080 : 80));
  if (!Number.isInteger(upstreamPort) || upstreamPort < 1 || upstreamPort > 65535) {
    throw new Error(`invalid upstream proxy port: ${u.port}`);
  }
  const auth = upstream.username
    ? `Basic ${Buffer.from(`${upstream.username}:${upstream.password || ""}`).toString("base64")}`
    : undefined;

  const isSocks = u.protocol === "socks5:";
  const socksAgent = isSocks ? new SocksProxyAgent(upstream.server) : undefined;

  const sockets = new Set<net.Socket>();
  const server = http.createServer((req, res) => {
    const headers: http.OutgoingHttpHeaders = { ...req.headers };
    if (!isSocks) {
      delete headers["proxy-authorization"];
      if (auth) headers["proxy-authorization"] = auth;
    }

    const upstreamReq = isSocks 
      ? http.request(req.url!, { method: req.method, headers, agent: socksAgent }, (upstreamRes) => {
          res.writeHead(upstreamRes.statusCode || 502, upstreamRes.statusMessage, upstreamRes.headers);
          upstreamRes.on("error", () => res.destroy());
          res.on("error", () => upstreamRes.destroy());
          upstreamRes.pipe(res);
        })
      : http.request({
          host: upstreamHost,
          port: upstreamPort,
          method: req.method,
          path: req.url,
          headers,
        }, (upstreamRes) => {
          res.writeHead(upstreamRes.statusCode || 502, upstreamRes.statusMessage, upstreamRes.headers);
          upstreamRes.on("error", () => res.destroy());
          res.on("error", () => upstreamRes.destroy());
          upstreamRes.pipe(res);
        });

    upstreamReq.on("socket", (socket) => {
      socket.setTimeout(3000);
      socket.on("timeout", () => {
        socket.destroy();
        if (!res.headersSent) res.writeHead(504);
        res.end("upstream tarpit timeout");
      });
    });

    upstreamReq.on("error", () => {
      if (!res.headersSent) res.writeHead(502);
      res.end("proxy forwarder error");
    });
    req.on("error", () => {
      upstreamReq.destroy();
      res.destroy();
      req.destroy();
    });
    res.on("error", () => {
      upstreamReq.destroy();
      req.destroy();
      res.destroy();
    });
    upstreamReq.on("error", () => {
      req.destroy();
      res.destroy();
      upstreamReq.destroy();
    });
    req.pipe(upstreamReq);
  });

  server.on("connect", async (req, clientSocket, head) => {
    clientSocket.on("error", () => {}); // Catch early disconnects to prevent unhandled EPIPE
    // Node types declare clientSocket as stream.Duplex but it's always net.Socket
    // at runtime. Cast once so setNoDelay/setTimeout are available without per-call guards.
    const clientSock = clientSocket as unknown as net.Socket;
    const target = req.url;
    if (!target) {
      try { clientSocket.end("HTTP/1.1 400 Bad Request\r\n\r\n"); } catch { /* intentional */ }
      return;
    }

    if (isSocks) {
      try {
        let targetHost = target;
        let targetPort = 443;
        const portMatch = target.match(/:(\d+)$/);
        if (portMatch && portMatch[1]) {
          targetPort = parseInt(portMatch[1], 10);
          targetHost = target.slice(0, portMatch.index);
        }
        const info = await SocksClient.createConnection({
          proxy: {
            host: upstreamHost,
            port: upstreamPort,
            type: 5,
            ...(upstream.username ? { userId: upstream.username, password: upstream.password || "" } : {})
          },
          command: 'connect',
          timeout: 8000,
          destination: {
            host: targetHost,
            port: targetPort
          }
        });
        const upstreamSocket = info.socket;
        // SocksClient types declare .socket as Duplex but it's net.Socket at
        // runtime. Cast so we can call setNoDelay/setTimeout. Guard with typeof.
        const rawSock = upstreamSocket;

        // Issue 16: Track upstream socket so close() can destroy it
        sockets.add(upstreamSocket);
        upstreamSocket.on("close", () => sockets.delete(upstreamSocket));

        // Issue 14: Disable Nagle's algorithm — eliminates up to 200ms
        // coalescing delay on small packets (TLS fragments, form POSTs)
        if (typeof rawSock.setNoDelay === "function") rawSock.setNoDelay(true);
        clientSock.setNoDelay(true);

        // Issue 13: Idle timeout — destroy both ends if the tunnel is
        // silent for 60s (dead browser tab, network partition)
        const TUNNEL_IDLE_MS = 60_000;
        if (typeof rawSock.setTimeout === "function") rawSock.setTimeout(TUNNEL_IDLE_MS, () => { upstreamSocket.destroy(); clientSocket.destroy(); });
        clientSock.setTimeout(TUNNEL_IDLE_MS, () => { clientSocket.destroy(); upstreamSocket.destroy(); });

        clientSocket.write("HTTP/1.1 200 Connection Established\r\n\r\n");
        if (head.length) upstreamSocket.write(head);

        upstreamSocket.on("error", () => { clientSocket.destroy(); upstreamSocket.destroy(); });
        clientSocket.on("error", () => { upstreamSocket.destroy(); clientSocket.destroy(); });
        upstreamSocket.on("close", () => { clientSocket.destroy(); upstreamSocket.destroy(); });
        clientSocket.on("close", () => { upstreamSocket.destroy(); clientSocket.destroy(); });
        upstreamSocket.on("end", () => clientSocket.end());
        clientSocket.on("end", () => upstreamSocket.end());

        upstreamSocket.pipe(clientSocket);
        clientSocket.pipe(upstreamSocket);
      } catch (err) {
        try { clientSocket.end("HTTP/1.1 502 Bad Gateway\r\n\r\n"); } catch { /* intentional */ }
      }
      return;
    }

    const upstreamSocket = net.connect(upstreamPort, upstreamHost, () => {
      // Issue 14: Disable Nagle on both ends once connected
      upstreamSocket.setNoDelay(true);
      clientSock.setNoDelay(true);

      // Reset connect timeout → idle timeout for established tunnel
      // Issue 13: 60s idle timeout prevents leaked sockets from dead tabs
      const TUNNEL_IDLE_MS = 60_000;
      upstreamSocket.setTimeout(TUNNEL_IDLE_MS, () => { upstreamSocket.destroy(); clientSocket.destroy(); });
      clientSock.setTimeout(TUNNEL_IDLE_MS, () => { clientSocket.destroy(); upstreamSocket.destroy(); });

      const lines = [
        `CONNECT ${target} HTTP/1.1`,
        `Host: ${target}`,
        "Proxy-Connection: Keep-Alive",
        auth ? `Proxy-Authorization: ${auth}` : undefined,
        "",
        "",
      ].filter((v): v is string => v !== undefined);
      upstreamSocket.write(lines.join("\r\n"));
      if (head.length) upstreamSocket.write(head);
    });

    // Issue 19: Track upstream socket so close() can destroy it
    sockets.add(upstreamSocket);
    upstreamSocket.on("close", () => sockets.delete(upstreamSocket));

    // Aggressive fast-fail timeout for dead proxies during connect phase
    upstreamSocket.setTimeout(3000);
    upstreamSocket.on("timeout", () => {
      upstreamSocket.destroy();
      try { clientSocket.end("HTTP/1.1 504 Gateway Timeout\r\n\r\n"); } catch { /* intentional */ }
    });

    let buffered = Buffer.alloc(0);
    const onData = (chunk: Buffer) => {
      buffered = Buffer.concat([buffered, chunk]);
      const headerEnd = buffered.indexOf("\r\n\r\n");
      if (headerEnd < 0) return;
      upstreamSocket.off("data", onData);
      const header = buffered.subarray(0, headerEnd).toString("latin1");
      const rest = buffered.subarray(headerEnd + 4);
      if (!/^HTTP\/1\.[01] 200\b/i.test(header)) {
        clientSocket.write(buffered);
        clientSocket.end();
        upstreamSocket.end();
        return;
      }
      clientSocket.write("HTTP/1.1 200 Connection Established\r\n\r\n");
      if (rest.length) clientSocket.write(rest);
      upstreamSocket.on("error", () => { clientSocket.destroy(); upstreamSocket.destroy(); });
      clientSocket.on("error", () => { upstreamSocket.destroy(); clientSocket.destroy(); });
      upstreamSocket.pipe(clientSocket);
      clientSocket.pipe(upstreamSocket);
    };
    upstreamSocket.on("data", onData);
    upstreamSocket.on("error", () => { clientSocket.destroy(); upstreamSocket.destroy(); });
    clientSocket.on("error", () => { upstreamSocket.destroy(); clientSocket.destroy(); });
  });

  server.on("connection", (s) => {
    sockets.add(s);
    s.on("close", () => sockets.delete(s));
  });

  await new Promise<void>((resolve, reject) => {
    server.once("error", reject);
    server.listen(0, "127.0.0.1", () => {
      server.off("error", reject);
      // Permanent error handler after listen succeeds (Rule 44: strict-httpcloak-error-handling).
      // Without this, a post-startup server error (e.g., EMFILE) would crash the process
      // with an unhandled 'error' event on the net.Server.
      server.on("error", (_err: Error) => {
        // Non-fatal: log and continue. The individual socket error handlers
        // on each connection already handle per-request failures.
      });
      resolve();
    });
  });
  const addr = server.address();
  if (!addr || typeof addr === "string") throw new Error("proxy forwarder failed to bind");
  let closed = false;
  return {
    serverUrl: `http://127.0.0.1:${addr.port}`,
    close: async () => {
      if (closed) return;
      closed = true;
      // Issue 15: Destroy all tracked sockets FIRST to unblock server.close().
      // server.close() waits for existing connections to end naturally —
      // which would be never for piped CONNECT tunnels, causing a shutdown deadlock.
      for (const s of sockets) s.destroy();
      sockets.clear();
      // Now close the server — safe because all connections are already destroyed
      await new Promise<void>((resolve) => server.close(() => resolve()));
    },
  };
}

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unused-expressions, @typescript-eslint/no-unused-vars, @typescript-eslint/require-await */
/**
 * Proxy reputation tracker. Records success/fail counts per proxy server
 * and biases future picks toward proxies with healthy history via Laplace-
 * smoothed weighted random selection. Persists to a sidecar JSON file.
 *
 * - Score:    s.success / (s.success + s.fail + 1)   (Laplace smoothing)
 * - Quarantine: trials >= minTrials AND score < minScore → weight 0
 * - Unknown proxies get a neutral weight so fresh entries can compete.
 */
import fs from "node:fs";
import { type ProxyEntry } from "../../backends/index.js";
import { createLogger } from "../core/logger.js";
import { detectCountryFromProxy } from "../profiles/profile-geo-alignment.js";

const log = createLogger("proxy-score-tracker");

/**
 * Unique identifier for a proxy entry. Sticky-residential pools commonly ship
 * many entries that share the same gateway host:port and differ only in the
 * username (the sticky-session token). Excluding by `server` alone collapses
 * all 200 entries into one, defeating row-level proxy rotation; we therefore
 * key by `server#username` so each sticky session can be rotated independently.
 */
export function proxyEntryKey(p: ProxyEntry): string {
  return `${p.server}#${p.username || ""}`;
}

export interface ProxyScore {
  key: string;
  success: number;
  fail: number;
  lastUsed: number; // ms epoch
  server?: string;  // display-friendly host:port, set the last time record() was called with a server
  isJailed?: boolean;
}

export interface ProxyHealthInfo {
  key: string;
  server: string;
  success: number;
  fail: number;
  trials: number;
  score: number;
  isJailed: boolean;
  lastUsed: number;
}

export interface ProxyScoreTrackerOptions {
  minScore?: number;   // default 0.2 — below this and trials >= minTrials → quarantine
  minTrials?: number;  // default 5   — need at least this many trials before quarantining
}

export class ProxyScoreTracker {
  private scores = new Map<string, ProxyScore>();
  private readonly minScore: number;
  private readonly minTrials: number;
  private readonly maxEntries: number;
  private patternBlacklist = new Map<RegExp, number>();

  constructor(opts: ProxyScoreTrackerOptions & { maxEntries?: number; scoresFile?: string } = {}) {
    this.minScore = opts.minScore ?? 0.2;
    this.minTrials = opts.minTrials ?? 5;
    this.maxEntries = opts.maxEntries ?? 10000;
  }

  // Subnet tracking for cluster failures (Item 24)
  private subnetFailures = new Map<string, { count: number; lastFail: number; banLevel: number }>();

  private extractSubnet(server: string): string | undefined {
    const ipMatch = server.match(/(\d+\.\d+\.\d+)\.\d+/);
    return ipMatch ? ipMatch[1] : undefined;
  }

  /** Record a per-row outcome against a proxy server. `server` is the
   *  display-friendly host/port string;
   *  optional, kept on the score so diagnostic dumps can surface which
   *  upstream gateway each sticky-session key actually routes through. */
  record(key: string, success: boolean, server?: string): void {
    let existing = this.scores.get(key);
    if (existing) {
      this.scores.delete(key); // Remove to re-insert at the end (LRU behavior)
    } else {
      existing = { key, success: 0, fail: 0, lastUsed: 0 };
    }

    if (success) existing.success++;
    else existing.fail++;
    existing.lastUsed = Date.now();
    if (server) existing.server = server;

    this.scores.set(key, existing);

    // Active Upstream Proxy IP Rotation
    if (!success && this.trialsFor(existing) >= this.minTrials && this.scoreFor(existing) < this.minScore) {
      if (!existing.isJailed) {
        existing.isJailed = true; // Temporary flag to prevent spamming rotation
        import('../core/metrics.js').then(m => m.proxyQuarantineCount.inc({ proxyServer: server || key })).catch(() => {});
        if (process.env.PROXY_ROTATE_URL_TEMPLATE) {
          const url = process.env.PROXY_ROTATE_URL_TEMPLATE.replace(/\[session\]/g, key).replace(/\[host\]/g, server || "");
          fetch(url).catch(err => console.error(`[ProxyRotate] Failed to rotate ${key}: ${err instanceof Error ? err.message : String(err)}`));
        }
      }
    }

    // Subnet-Level Quarantine Intelligence (Item 24)
    if (!success && server) {
      const subnet = this.extractSubnet(server);
      if (subnet) {
        const now = Date.now();
        const info = this.subnetFailures.get(subnet) || { count: 0, lastFail: 0, banLevel: 0 };
        // Reset count and banLevel if older than 1 hour (allows recovery)
        if (now - info.lastFail > 60 * 60 * 1000) {
          info.count = 0;
          info.banLevel = 0;
        }
        info.count++;
        info.lastFail = now;
        this.subnetFailures.set(subnet, info);

        // Quarantine /24 subnet if 3+ consecutive failures across different IPs
        if (info.count >= 3) {
          info.banLevel++;
          // Exponential backoff: 5, 15, 60, 240 mins (capped at 4 hours)
          const banMinutes = [5, 15, 60, 240][Math.min(info.banLevel - 1, 3)] || 240;
          const banDurationMs = banMinutes * 60 * 1000;

          const pattern = new RegExp(`//${subnet.replace(/\./g, '\\.')}\\.`);
          this.patternBlacklist.set(pattern, now + banDurationMs);
          log.warn(`Subnet quarantine triggered for ${subnet}.x (/24) for ${banMinutes} minutes (level ${info.banLevel}).`);

          info.count = 0; // Reset consecutive fail count but maintain banLevel
        }
      }
    } else if (success && server) {
      const subnet = this.extractSubnet(server);
      if (subnet) this.subnetFailures.delete(subnet);
    }

    if (this.scores.size > this.maxEntries) {
      // Map iterates in insertion order. The first item is the oldest.
      const firstKey = this.scores.keys().next().value;
      if (firstKey !== undefined) {
        this.scores.delete(firstKey);
      }
    }
  }

  /** Laplace-smoothed score: gives unseen proxies a chance, penalises losers. Decays older scores using a 2-hour half-life. */
  private scoreFor(s: ProxyScore): number {
    const ageMs = Date.now() - s.lastUsed;
    const halfLifeMs = 2 * 60 * 60 * 1000; // 2 hours
    const decay = Math.pow(0.5, ageMs / halfLifeMs);
    const effSuccess = s.success * decay;
    const effFail = s.fail * decay;
    return effSuccess / (effSuccess + effFail + 1);
  }

  private trialsFor(s: ProxyScore): number {
    const ageMs = Date.now() - s.lastUsed;
    const halfLifeMs = 2 * 60 * 60 * 1000;
    const decay = Math.pow(0.5, ageMs / halfLifeMs);
    return (s.success + s.fail) * decay;
  }

  /**
   * Returns a detailed list of all tracked proxies and their current health/quarantine status.
   * Useful for UI visualization.
   */
  getDetailedScores(): ProxyHealthInfo[] {
    const arr: ProxyHealthInfo[] = [];
    for (const [key, s] of this.scores.entries()) {
      const trials = this.trialsFor(s);
      const score = this.scoreFor(s);
      const isJailed = trials >= this.minTrials && score < this.minScore;
      arr.push({
        key,
        server: s.server || key,
        success: s.success,
        fail: s.fail,
        trials,
        score,
        isJailed,
        lastUsed: s.lastUsed
      });
    }
    // Sort so jailed are at the bottom, then by highest score first
    return arr.sort((a, b) => {
      if (a.isJailed !== b.isJailed) return a.isJailed ? 1 : -1;
      return b.score - a.score;
    });
  }

  /**
   * Weighted random selection over the candidate pool. Quarantined proxies
   * (trials >= minTrials && score < minScore) get weight 0. Unknown proxies
   * get a neutral baseline weight (avg of seen scores, capped at 0.5) so
   * they can compete fairly with the established pool.
   * Falls back to raw smoothed weights if every candidate is quarantined,
   * so we never return undefined when candidates exist.
   * If targetCountry is provided, matching proxies receive a 2x weight boost (Item 22).
   */
  weightedPick(pool: ProxyEntry[], exclude: string[] = [], targetCountry?: string): ProxyEntry | undefined {
    if (pool.length === 0) return undefined;

    // Precompute keys and filter out excluded proxies in one pass.
    // This avoids repeatedly calling proxyEntryKey inside the loops.
    const excludeSet = exclude.length > 0 ? new Set(exclude) : null;
    const candidatePairs: { p: ProxyEntry; key: string }[] = [];

    for (const p of pool) {
      const key = proxyEntryKey(p);
      if (excludeSet && excludeSet.has(key)) continue;
      candidatePairs.push({ p, key });
    }

    if (candidatePairs.length === 0) return undefined;

    // Neutral baseline for unknown proxies — average of seen scores among CURRENT candidates, capped at 0.5.
    // This prevents historical scores of dead/removed proxies from dragging down the baseline for fresh proxies.
    let sumSeen = 0;
    let countSeen = 0;
    for (const { key } of candidatePairs) {
      const s = this.scores.get(key);
      if (s) {
        sumSeen += this.scoreFor(s);
        countSeen++;
      }
    }
    const avgSeen = countSeen > 0 ? sumSeen / countSeen : 0.5;
    // Give unknown proxies at least a minimal baseline (e.g. 0.2) so they can out-compete 0-weighted quarantined proxies.
    const unknownWeight = Math.max(0.2, Math.min(0.5, avgSeen));

    const computeWeight = (key: string, quarantineEnabled: boolean): number => {
      if (quarantineEnabled) {
        for (const [pattern, expiry] of this.patternBlacklist.entries()) {
          if (Date.now() > expiry) {
            this.patternBlacklist.delete(pattern);
          } else if (pattern.test(key)) {
            return 0; // Temporarily banned via pattern/subnet block
          }
        }
      }

      const s = this.scores.get(key);
      if (!s) {
        if (targetCountry && detectCountryFromProxy(key) === targetCountry) return unknownWeight * 2;
        return unknownWeight;
      }
      if (quarantineEnabled && this.trialsFor(s) >= this.minTrials && this.scoreFor(s) < this.minScore) {
        return 0;
      }
      let weight = this.scoreFor(s);
      if (targetCountry && detectCountryFromProxy(key) === targetCountry) {
        weight *= 2; // boost geo-aligned proxies
      }
      return weight;
    };

    // First pass: with quarantine. If everything zero, retry without.
    let weights = candidatePairs.map(({ key }) => computeWeight(key, true));
    let total = weights.reduce((a, b) => a + b, 0);
    if (total === 0) {
      weights = candidatePairs.map(({ key }) => computeWeight(key, false));
      total = weights.reduce((a, b) => a + b, 0);
      // Still zero (e.g. all unknown with avgSeen=0): pick uniformly.
      if (total === 0) {
        return candidatePairs[Math.floor(Math.random() * candidatePairs.length)]!.p;
      }
    }

    let r = Math.random() * total;
    for (let i = 0; i < candidatePairs.length; i++) {
      const weight = weights[i];
      if (weight !== undefined) r -= weight;
      if (r <= 0) return candidatePairs[i]!.p;
    }
    return candidatePairs[candidatePairs.length - 1]!.p; // numerical-safety fallback
  }

  private saveTimeout: ReturnType<typeof setTimeout> | null = null;
  private pendingSave = false;

  /** Best-effort write of the scores map to a sidecar JSON file with debouncing (Item 23). */
  async saveScores(filePath: string): Promise<void> {
    this.pendingSave = true;
    if (this.saveTimeout) return; // Debounced

    this.saveTimeout = setTimeout(async () => {
      this.saveTimeout = null;
      if (!this.pendingSave) return;
      this.pendingSave = false;

      const arr = Array.from(this.scores.values());
      const tmpPath = `${filePath}.tmp`;
      try {
        await fs.promises.writeFile(tmpPath, JSON.stringify(arr, null, 2));
        await fs.promises.rename(tmpPath, filePath);
      } catch (e: unknown) {
        const msg = e instanceof Error ? e.message : String(e);
        log.warn(`Failed to save scores to ${filePath}: ${msg}`);
      }

      // Issue 17: Re-check after write — if new records arrived during the
      // async writeFile, pendingSave will be true again and we need to
      // re-arm the save to avoid silently losing data.
      if (this.pendingSave) {
        void this.saveScores(filePath);
      }
    }, 5000);
  }

  /** Best-effort load of scores from a sidecar JSON file. No-op if absent. */
  async loadScores(filePath: string): Promise<void> {
    if (!fs.existsSync(filePath)) return;
    try {
      const raw = await fs.promises.readFile(filePath, "utf-8");
      const arr = JSON.parse(raw);
      if (!Array.isArray(arr)) {
        log.warn(`${filePath} is not an array — ignoring`);
        return;
      }
      this.scores.clear();
      for (const item of arr) {
        const key = item.key || (typeof item.server === "string" ? (item.server.includes("#") ? item.server : `${item.server}#""`) : null);
        if (key && typeof key === "string") {
          this.scores.set(key, {
            key,
            success: Number(item.success) || 0,
            fail: Number(item.fail) || 0,
            lastUsed: Number(item.lastUsed) || 0,
            server: typeof item.server === "string" ? item.server : undefined,
          });
        }
      }
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : String(e);
      log.warn(`Failed to parse ${filePath}: ${msg}`);
    }
  }

  /** Diagnostics — number of tracked proxies. */
  size(): number {
    return this.scores.size;
  }

  /**
   * Temporarily ban a cluster of proxies (e.g. subnet, specific domain)
   * if multiple instances fail identically.
   */
  banPattern(pattern: RegExp, durationMs: number = 300000): void {
    this.patternBlacklist.set(pattern, Date.now() + durationMs);
    log.warn(`[ProxyScoreTracker] Subnet/Pattern ${pattern} banned for ${durationMs / 1000}s`);
  }
}

