export function checkpointWAL(): void {
  try {
    db.pragma('wal_checkpoint(TRUNCATE)');
    log.info('WAL checkpoint complete — DB file is self-contained');
  } catch (e: unknown) {
    log.warn(`WAL checkpoint failed: ${e instanceof Error ? e.message : String(e)}`);
  }
}

