}

export class ScreenshotService extends EventEmitter {
  private opts: ScreenshotServiceOpts;
  private cleanupTimer: NodeJS.Timeout | null = null;
  // In-flight disk writes. Bounded by queueMax — any capture that arrives
  // while the count is at/above the cap is dropped before any I/O happens
  // and a "queue-pressure" event ({ current, max }) is emitted as a fire-
  // and-forget signal for dashboards / observability.
  private pendingCount = 0;
  private queueMax: number;
  // In-flight write promises tracked for flush(). Each entry is removed in
  // its own .finally() so the set stays bounded by pendingCount.
  private pendingWrites: Set<Promise<void>> = new Set();
  // Optional GCS uploader — set via setGcsUploader() after construction
  private _gcsUploader: GcsUploader | null = null;

  private get modalCropEnabled(): boolean {
    return this.opts.modalCrop ?? true;
  }

  constructor(opts: ScreenshotServiceOpts) {
    super();
    this.opts = opts;
    this.queueMax = opts.queueMax ?? Timings.SCREENSHOT_QUEUE_MAX;
    if (!fs.existsSync(this.opts.baseDir)) {
      fs.mkdirSync(this.opts.baseDir, { recursive: true });
    }
  }

  /** Attach a GCS uploader for cloud screenshot storage. */
  setGcsUploader(uploader: GcsUploader | null): void {
    this._gcsUploader = uploader;
    if (uploader?.isReady) {
      this.log("INFO", "GCS uploader attached — screenshots will be uploaded to cloud");
    }
  }

  private log(level: string, msg: string) {
    if (this.opts.logger) { this.opts.logger(level, msg); return; }
    const lvl = level.toLowerCase();
    if (lvl === "warn") defaultLog.warn(msg);
    else if (lvl === "error") defaultLog.error(msg);
    else if (lvl === "debug") defaultLog.debug(msg);
    else defaultLog.info(msg);
  }

  async capture(page: Page, ctx: ScreenshotCaptureCtx): Promise<{ path: string; relativePath: string; sizeBytes: number; durationMs: number; cropBox?: ClipBox; hash?: string } | null> {
    const startTime = Date.now();
    try {
      const { buffer: buf, cropBox } = await this.captureBuffer(page, ctx);
      return this._saveBuffer(buf, ctx, startTime, cropBox);
    } catch (err: unknown) {
      this.log("WARN", `Screenshot capture failed for "${ctx.label}": ${err instanceof Error ? err.message : String(err)}`);
      this.emit("screenshot-error", { label: ctx.label, error: (err instanceof Error ? err.message : String(err)), stack: err instanceof Error ? err.stack : undefined });
      return null;
    }
  }

  async captureFromBuffer(rawBuffer: Buffer, ctx: ScreenshotCaptureCtx): Promise<{ path: string; relativePath: string; sizeBytes: number; durationMs: number; cropBox?: ClipBox; hash?: string } | null> {
    const startTime = Date.now();
    try {
      let buf = rawBuffer;
      let cropBox: ClipBox | undefined;
      // Apply Tier 2 cropping if enabled, otherwise save raw
      if (!ctx.fullPage && this.modalCropEnabled && (this.opts.pixelCropFallback ?? true)) {
        const cropped = await this.cropWhiteModalFromBuffer(rawBuffer).catch((e: any) => {
          this.log("DEBUG", `Pixel modal crop skipped for "${ctx.label}": ${e?.message || e}`);
          return null;
        });
        if (cropped && cropped.buffer.length > 0) {
          buf = await this.normalizeSize(cropped.buffer).catch(() => cropped.buffer);
          cropBox = cropped.cropBox;
        }
      }
      return this._saveBuffer(buf, ctx, startTime, cropBox);
    } catch (err: unknown) {
      this.log("WARN", `Screenshot captureFromBuffer failed for "${ctx.label}": ${err instanceof Error ? err.message : String(err)}`);
      this.emit("screenshot-error", { label: ctx.label, error: (err instanceof Error ? err.message : String(err)), stack: err instanceof Error ? err.stack : undefined });
      return null;
    }
  }

  private _saveBuffer(buf: Buffer, ctx: ScreenshotCaptureCtx, startTime: number, cropBox?: ClipBox) {
    const captureDuration = Date.now() - startTime;
    const emailSlug = sanitizePathSegment(ctx.email?.trim().toLowerCase(), "nocred").slice(0, 64);
    const now = new Date();
    const mm = String(now.getMonth() + 1).padStart(2, '0');
    const dd = String(now.getDate()).padStart(2, '0');
    const hh = String(now.getHours()).padStart(2, '0');
    const min = String(now.getMinutes()).padStart(2, '0');
    const sec = String(now.getSeconds()).padStart(2, '0');
    const tsShort = `${mm}${dd}_${hh}${min}${sec}`;

    const safeLabel = sanitizePathSegment(ctx.label, "capture");
    const target = sanitizePathSegment(ctx.target, "n_a");
    const configStr = ctx.configAcronym ? `__${ctx.configAcronym}` : "";
    const backendStr = ctx.backend ? `__${ctx.backend}` : "";
    const fileName = `${emailSlug}${configStr}${backendStr}__${target}__${safeLabel}__${tsShort}__${crypto.randomUUID()}.${this.opts.defaultFormat}`;
    const safeSubdir = ctx.subdir ? sanitizePathSegment(ctx.subdir, "") : "";
    const relativePath = safeSubdir ? path.join(safeSubdir, fileName) : fileName;
    const fullPath = safeJoinUnder(this.opts.baseDir, relativePath);

    this.enqueueWriteAndEmit(buf, ctx, fullPath, relativePath);

    const hashSum = crypto.createHash('sha256');
    hashSum.update(buf);
    const hash = hashSum.digest('hex');

    return {
      path: fullPath,
      relativePath,
      sizeBytes: buf.length,
      durationMs: captureDuration,
      cropBox: cropBox || undefined,
      hash,
    };
  }

  /**
   * Three-tier capture pipeline with a mandatory full-page final fallback so
   * a cropping miss can never produce a 0-byte file or skip the visual
   * record entirely.
   *
   *   Tier 1 — Playwright DOM-based modal clip (`input[type="password"]`
   *            ancestor card, or one of `modalSelectors`). If a valid clip
   *            is produced AND `page.screenshot` returns a non-empty buffer,
   *            this is the preferred output.
   *   Tier 2 — Sharp pixel-level pass over a viewport screenshot. Identifies
   *            the dominant neutral-white modal component and crops to it.
   *            Only consumed if Tier 1 yielded no clip / no buffer.
   *   Tier 3 — Mandatory `fullPage: true` capture. Runs whenever Tier 1 and
   *            Tier 2 both fail to yield a usable buffer, guaranteeing a
   *            non-empty visual record regardless of cropping miss.
   *
   * `ctx.fullPage = true` short-circuits to Tier 3 directly. The Tier 3
   * call is also re-issued if any earlier-tier buffer comes back 0-byte,
   * which Playwright should not produce but is defended against here.
   */
  private async captureBuffer(page: Page, ctx: ScreenshotCaptureCtx): Promise<{ buffer: Buffer; cropBox?: ClipBox }> {
    const screenshotOpts = {
      type: this.opts.defaultFormat,
      quality: this.opts.defaultFormat === "jpeg" ? this.opts.defaultQuality : undefined,
    } as const;

    // Explicit full-page request — bypass both cropping tiers.
    if (ctx.fullPage) {
      return { buffer: await this.captureFullPage(page, screenshotOpts, ctx.label) };
    }

    // Tier 1: DOM-based modal clip.
    if (this.modalCropEnabled) {
      const clip = await this.findModalClip(page).catch(() => null);
      if (clip) {
        const buf = await page.screenshot({ ...screenshotOpts, clip, animations: "disabled", caret: "hide" }).catch((e: any) => {
          this.log("DEBUG", `DOM-clip screenshot failed for "${ctx.label}": ${e?.message || e}`);
          return null;
        });
        if (buf && buf.length > 0) {
          const normalized = await this.normalizeSize(buf).catch(() => buf);
          return { buffer: normalized, cropBox: clip };
        }
      }
    }

    // Tier 2: Sharp pixel-level crop on a viewport screenshot.
    if (this.modalCropEnabled && (this.opts.pixelCropFallback ?? true)) {
      const viewport = await page.screenshot({ ...screenshotOpts, fullPage: false }).catch((e: any) => {
        this.log("DEBUG", `Viewport screenshot failed for "${ctx.label}": ${e?.message || e}`);
        return null;
      });
      if (viewport && viewport.length > 0) {
        const cropped = await this.cropWhiteModalFromBuffer(viewport).catch((e: any) => {
          this.log("DEBUG", `Pixel modal crop skipped for "${ctx.label}": ${e?.message || e}`);
          return null;
        });
        if (cropped && cropped.buffer.length > 0) {
          const normalized = await this.normalizeSize(cropped.buffer).catch(() => cropped.buffer);
          return { buffer: normalized, cropBox: cropped.cropBox };
        }
        this.log("DEBUG", `DOM + pixel crops both missed for "${ctx.label}" — falling back to full-page capture`);
      }
    }

    // Tier 3: mandatory full-page fallback.
    return { buffer: await this.captureFullPage(page, screenshotOpts, ctx.label) };
  }

  /**
   * Normalize a cropped screenshot to consistent dimensions so every
   * screenshot in the evidence trail has identical width × height regardless
   * of which cropping tier produced it.
   *
   * Strategy:
   *   1. Read the source dimensions.
   *   2. Pick the closest standard canvas (landscape 720×540 or portrait
   *      480×640) based on the source aspect ratio.
   *   3. Resize with `fit: 'contain'` so the crop is scaled to fit inside
   *      the canvas without distortion, then pad the remaining area with
   *      a dark background that matches the site's dark theme.
   */
  private async normalizeSize(buf: Buffer): Promise<Buffer> {
    const meta = await sharp(buf).metadata();
    const srcW = meta.width ?? 0;
    const srcH = meta.height ?? 0;
    if (srcW === 0 || srcH === 0) return buf;

    // Choose canvas based on aspect ratio
    const isPortrait = srcH > srcW * 1.15;
    const targetW = isPortrait ? 480 : 720;
    const targetH = isPortrait ? 640 : 540;

    // Skip if already at (or very close to) target size
    if (Math.abs(srcW - targetW) <= 4 && Math.abs(srcH - targetH) <= 4) return buf;

    const pipeline = sharp(buf).resize(targetW, targetH, {
      fit: "contain",
      background: { r: 26, g: 26, b: 46, alpha: 1 }, // #1a1a2e — dark theme
    });

    return this.opts.defaultFormat === "png"
      ? await pipeline.png().toBuffer()
      : await pipeline.jpeg({ quality: this.opts.defaultQuality, mozjpeg: true }).toBuffer();
  }

  /**
   * Final-fallback full-page capture. Defends against the rare case where
   * Playwright returns a 0-byte buffer by re-issuing the screenshot once.
   * Any error propagates to `capture()` so the outer error path fires.
   */
  private async captureFullPage(
    page: Page,
    screenshotOpts: { type: "jpeg" | "png"; quality?: number },
    label: string,
  ): Promise<Buffer> {
    const buf = await page.screenshot({ ...screenshotOpts, fullPage: true });
    if (buf && buf.length > 0) return buf;
    this.log("WARN", `Full-page screenshot returned 0-byte buffer for "${label}" — re-attempting once`);
    return await page.screenshot({ ...screenshotOpts, fullPage: true });
  }

  private async findModalClip(page: Page): Promise<ClipBox | null> {
    const viewport = await this.getViewportSize(page);
    const padding = this.opts.modalPadding ?? DEFAULT_MODAL_PADDING;
    const box = await this.detectLoginModalBox(page) ?? await this.findSelectorBox(page);
    if (!box) return null;
    return clampClip(box, viewport, padding);
  }

  private async getViewportSize(page: Page): Promise<{ width: number; height: number }> {
    const viewport = page.viewportSize?.();
    if (viewport) return viewport;
    return await page.evaluate(() => ({ width: window.innerWidth, height: window.innerHeight }));
  }

  private async detectLoginModalBox(page: Page): Promise<ClipBox | null> {
    if (typeof (page as any).evaluate !== "function") return null;
    return await page.evaluate(() => {
      const password = document.querySelector<HTMLInputElement>('input[type="password"]');
      if (!password) return null;
      let best: Element = password.closest("form") ?? password;
      let node: Element | null = best;
      while (node && node !== document.body) {
        const r = node.getBoundingClientRect();
        const style = getComputedStyle(node);
        const bg = style.backgroundColor;
        const radius = parseFloat(style.borderRadius || "0");
        const visibleBg = bg && bg !== "transparent" && bg !== "rgba(0, 0, 0, 0)";
        const looksLikeCard = r.width >= 240 && r.height >= 220 && visibleBg && radius >= 4;
        if (looksLikeCard) best = node;
        node = node.parentElement;
      }
      const r = best.getBoundingClientRect();
      return { x: r.x, y: r.y, width: r.width, height: r.height };
    });
  }

  private async findSelectorBox(page: Page): Promise<ClipBox | null> {
    if (typeof (page as any).locator !== "function") return null;
    for (const selector of this.opts.modalSelectors ?? DEFAULT_MODAL_SELECTORS) {
      try {
        const locator = page.locator(selector).first();
        await locator.waitFor({ state: "visible", timeout: 800 });
        const box = await locator.boundingBox();
        if (box && box.width >= 80 && box.height >= 80) return box;
      } catch { /* try next selector */ }
    }
    return null;
  }

  private async cropWhiteModalFromBuffer(buf: Buffer): Promise<{ buffer: Buffer; cropBox?: ClipBox } | null> {
    const { data, info } = await sharp(buf).ensureAlpha().raw().toBuffer({ resolveWithObject: true });
    const crop = detectWhiteModalCrop(data, info.width, info.height, this.opts.modalPadding ?? DEFAULT_MODAL_PADDING);
    if (!crop) return null;
    const out = sharp(buf).extract({ left: crop.x, top: crop.y, width: crop.width, height: crop.height });
    const croppedBuf = this.opts.defaultFormat === "png"
      ? await out.png().toBuffer()
      : await out.jpeg({ quality: this.opts.defaultQuality, mozjpeg: true }).toBuffer();
    return { buffer: croppedBuf, cropBox: crop };
  }

  private enqueueWriteAndEmit(buf: Buffer, ctx: ScreenshotCaptureCtx, fullPath: string, relativePath: string) {
    // Hard cap on concurrent in-flight writes. When saturated we drop the
    // new write entirely — no Promise allocation, no filesystem touch — and
    // emit "queue-pressure" so dashboards / observability can react. Previous
    // implementation only deleted the Promise reference, leaving the write
    // running to completion (unbounded queue in practice).
    if (this.pendingCount >= this.queueMax) {
      this.log("WARN", `Screenshot queue full (${this.pendingCount}/${this.queueMax}) — dropping new write`);
      this.emit("queue-pressure", { current: this.pendingCount, max: this.queueMax });
      return;
    }
    this.pendingCount++;

    const p = (async () => {
      try {
        const subDirPath = path.dirname(fullPath);
        if (!fs.existsSync(subDirPath)) {
          await fs.promises.mkdir(subDirPath, { recursive: true });
        }

        await fs.promises.writeFile(fullPath, buf);

        const event: ScreenshotEvent = {
          label: ctx.label,
          relativePath,
          sizeBytes: buf.length,
          timestamp: new Date().toISOString(),
          target: ctx.target,
          email: ctx.email,
          backend: ctx.backend,
          configAcronym: ctx.configAcronym,
          proxyPool: ctx.proxyPool,
          inputMode: ctx.inputMode,
          concurrency: ctx.concurrency,
          bypass: ctx.bypass,
          cloak: ctx.cloak,
        };

        if (this.opts.emitBase64) {
          event.base64 = buf.toString("base64");
        }

        this.emit("screenshot", event);

        // Async GCS upload (non-blocking — dashboard already has the screenshot via emit above)
        if (this._gcsUploader?.isReady) {
          this._gcsUploader.upload(fullPath, {
            email: ctx.email,
            label: ctx.label,
            target: ctx.target,
          }).then(result => {
            if (result) {
              this.emit("gcs-uploaded", {
                ...event,
                gcsUrl: result.publicUrl,
              });
            }
          }).catch(() => { /* logged by uploader */ });
        }
      } catch (err: unknown) {
        this.log("WARN", `Background screenshot write failed for "${ctx.label}": ${err instanceof Error ? err.message : String(err)}`);
        this.emit("screenshot-error", {
          label: ctx.label,
          error: (err instanceof Error ? err.message : String(err)),
          stack: (err instanceof Error ? err.stack : ''),
        });
      }
    })();

    this.pendingWrites.add(p);
      void p.finally(() => {
      this.pendingCount--;
      this.pendingWrites.delete(p);
    });
  }

  /** Resolves once all in-flight background writes have completed. Useful for
   *  graceful shutdown and for tests that need to clean their tmp dir without
   *  racing the non-blocking writes spawned by capture(). */
  async flush(): Promise<void> {
    while (this.pendingWrites.size > 0) {
      await Promise.allSettled(Array.from(this.pendingWrites));
    }
  }

  async prune(): Promise<{ deleted: number; existed: boolean }> {
    if (!fs.existsSync(this.opts.baseDir)) return { deleted: 0, existed: false };

    let deletedCount = 0;
    const now = Date.now();

    const scanDir = async (dir: string) => {
      const entries = await fs.promises.readdir(dir, { withFileTypes: true });
      for (const entry of entries) {
        const fullPath = path.join(dir, entry.name);
        if (entry.isDirectory()) {
          await scanDir(fullPath);
          // Try to remove empty directory
          const children = await fs.promises.readdir(fullPath);
          if (children.length === 0) {
            await fs.promises.rmdir(fullPath).catch(() => { });
          }
        } else if (entry.isFile()) {
          const stats = await fs.promises.stat(fullPath);
          if (now - stats.mtimeMs > this.opts.retentionMs) {
            await fs.promises.unlink(fullPath).catch(() => { });
            deletedCount++;
          }
        }
      }
    };

    try {
      await scanDir(this.opts.baseDir);
      return { deleted: deletedCount, existed: true };
    } catch (err: unknown) {
      this.log("WARN", `Prune failed: ${err instanceof Error ? err.message : String(err)}`);
      return { deleted: deletedCount, existed: true };
    }
  }

  startAutoPrune(): void {
    if (this.cleanupTimer) return;
    this.cleanupTimer = setInterval(async () => {
      const result = await this.prune();
      if (result.deleted > 0) {
        this.log("INFO", `Auto-prune: deleted ${result.deleted} screenshots`);
      }
    }, this.opts.cleanupIntervalMs);
  }

  stopAutoPrune(): void {
    if (this.cleanupTimer) {
      clearInterval(this.cleanupTimer);
      this.cleanupTimer = null;
    }
  }
}

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unused-expressions, @typescript-eslint/no-unused-vars, @typescript-eslint/require-await */
/**
 * AI-powered video verification for login-outcome recordings.
 *
 * Extracts key frames from .webm recordings via ffmpeg, sends them to
 * Gemini 2.5 Flash vision, and returns a structured verification result.
 *
 * Purpose: prevents false denylist burns on "all-terminal-bad" outcomes
 * (double noaccount, double permdisabled, or mixed) by cross-checking
 * the engine's DOM-based verdict against what a vision model actually
 * sees in the recording.
 */
import fs from 'node:fs';
import path from 'node:path';
import { createLogger } from "../core/logger.js";
import { GoogleGenerativeAI, type Part } from "@google/generative-ai";

const log = createLogger("video-verifier");

// ─── Types ─────────────────────────────────────────────────────────────────────

export type AiVerdict =
  | "disabled"         // "Your account has been disabled" / permdisabled
  | "temp-disabled"    // "temporarily disabled" / tempdisabled
  | "wrong-password"   // "incorrect password" / noaccount-via-exhaustion
  | "no-account"       // "no account found" / explicit noaccount
  | "success"          // logged in successfully
  | "2fa"              // two-factor auth prompt
  | "unclear";         // model couldn't determine

export interface VerificationResult {
  aiVerdict: AiVerdict;
  confidence: "high" | "medium" | "low";
  matches: boolean;           // AI agrees with engine outcome
  reasoning: string;          // one-line AI explanation
  framesAnalyzed: number;
  modelUsed: string;
  durationMs: number;
  /** False when the verifier could not actually inspect the recording (no API
   *  key, no extractable frames, model timed out, unparseable response). The
   *  engine uses this to gate signal-missing fallbacks instead of treating an
   *  empty verdict as a real "no-match" result. */
  signalAvailable?: boolean;
}

export interface VerificationJob {
  email: string;
  rowIndex: number;
  autoBurnCandidate?: boolean; // True if the credential was all-terminal-bad and should be burned if AI matches
  sites: Array<{
    name: string;
    engineOutcome: string;
    videoPath: string;
  }>;
}

// ─── Configuration ─────────────────────────────────────────────────────────────

const GEMINI_API_KEY = (process.env.GEMINI_API_KEY || process.env.GOOGLE_AI_API_KEY || process.env.GOOGLE_AGENT_PLATFORM_API_KEY || "").trim();
const MODEL_NAME = process.env.GEMINI_MODEL || "gemini-3.1-pro-preview" || "gemini-2.5-flash";
const MAX_FRAMES = 4;
const FRAME_POSITIONS = [0.25, 0.50, 0.75, 0.90]; // fallback % of video duration
const FFMPEG_FRAME_TIMEOUT_MS = 25_000;
const GEMINI_TIMEOUT_MS = 30_000;

let IS_GEMINI_VALID = !!GEMINI_API_KEY;

export function isVerificationAvailable(): boolean {
  return IS_GEMINI_VALID;
}

// ─── Frame Extraction ──────────────────────────────────────────────────────────

/**
 * Extract key frames from a .webm recording using ffmpeg.
 * Returns JPEG buffers for each extracted frame.
 */
export async function extractKeyFrames(
  videoPath: string,
  positions: number[] = FRAME_POSITIONS,
): Promise<Buffer[]> {
  const isRemote = videoPath.startsWith("http://") || videoPath.startsWith("https://");
  if (!isRemote && !fs.existsSync(videoPath)) {
    log.warn(`Video not found: ${videoPath}`);
    return [];
  }

  const ffmpegPath = await getFfmpegPath();
  if (!ffmpegPath) {
    log.warn("ffmpeg not available for frame extraction");
    return [];
  }

  const vvFramesBase = path.join(process.cwd(), ".vv-frames");
  await fs.promises.mkdir(vvFramesBase, { recursive: true });
  const tmpDir = await fs.promises.mkdtemp(path.join(vvFramesBase, "job-"));
  const frames: Buffer[] = [];

  try {
    const { spawn } = await import("child_process");

    // Attempt adaptive scene detection extraction first
    await new Promise<void>((resolve, reject) => {
      const outPattern = path.join(tmpDir, "adaptive-%03d.jpg");
      let proc: import("child_process").ChildProcess;

      const timeout = setTimeout(() => {
        if (proc) proc.kill("SIGKILL");
        reject(new Error("ffmpeg adaptive frame extraction timed out"));
      }, FFMPEG_FRAME_TIMEOUT_MS);

      proc = spawn(ffmpegPath, [
        "-i", videoPath,
        "-vf", "select='gt(scene,0.3)'",
        "-vsync", "vfr",
        "-frames:v", String(MAX_FRAMES),
        "-q:v", "2",
        "-y",
        outPattern,
      ], { stdio: ["ignore", "pipe", "pipe"] });

      proc.on("close", () => {
        clearTimeout(timeout);
        resolve();
      });
      proc.on("error", (err) => {
        clearTimeout(timeout);
        reject(err);
      });
    });

    const dirFiles = await fs.promises.readdir(tmpDir);
    const extractedFiles = dirFiles.filter(f => f.startsWith("adaptive-")).sort();

    if (extractedFiles.length > 0) {
      // Scene detection worked
      for (const file of extractedFiles) {
        frames.push(await fs.promises.readFile(path.join(tmpDir, file)));
      }
    } else {
      // Fallback to old time-based extraction if scene detection found 0 frames
      log.warn(`Scene detection yielded 0 frames, falling back to time-based extraction`);
      let duration = 0;
      for (let attempt = 1; attempt <= 3; attempt++) {
        duration = await getVideoDuration(ffmpegPath, videoPath);
        if (duration > 0) break;
        if (attempt < 3) await new Promise(r => setTimeout(r, 1000 * attempt));
      }

      if (duration > 0) {
        const extractionPromises = positions.slice(0, MAX_FRAMES).map(async (pos, i) => {
          const timestamp = duration * pos;
          const outPath = path.join(tmpDir, `frame-${i}.jpg`);

          await new Promise<void>((resolve, reject) => {
            let proc: import("child_process").ChildProcess;
            const timeout = setTimeout(() => {
              if (proc) proc.kill("SIGKILL");
              reject(new Error("ffmpeg frame extraction timed out"));
            }, FFMPEG_FRAME_TIMEOUT_MS);

            proc = spawn(ffmpegPath, [
              "-ss", String(timestamp),
              "-i", videoPath,
              "-frames:v", "1",
              "-q:v", "2",         // high quality JPEG
              "-y",                // overwrite
              outPath,
            ], { stdio: ["ignore", "pipe", "pipe"] });

            proc.on("close", (code) => {
              clearTimeout(timeout);
              if (code === 0 && fs.existsSync(outPath)) resolve();
              else reject(new Error(`ffmpeg frame extraction failed (exit ${code})`));
            });
            proc.on("error", (err) => {
              clearTimeout(timeout);
              reject(err);
            });
          });

          if (fs.existsSync(outPath)) {
            return fs.promises.readFile(outPath);
          }
          return null;
        });

        const results = await Promise.all(extractionPromises);
        for (const res of results) {
          if (res) frames.push(res);
        }
      }
    }
  } catch (err) {
    log.warn(`Frame extraction error: ${err instanceof Error ? err.message : String(err)}`);
  } finally {
    // Cleanup temp directory
    await fs.promises.rm(tmpDir, { recursive: true, force: true });
  }

  return frames;
}

async function getVideoDuration(ffmpegPath: string, videoPath: string): Promise<number> {
  const ffprobePath = ffmpegPath.replace(/ffmpeg$/, "ffprobe");
  const { spawn } = await import("child_process");

  return new Promise<number>((resolve) => {
    // Try ffprobe first, fall back to ffmpeg -i
    const bin = fs.existsSync(ffprobePath) ? ffprobePath : ffmpegPath;
    const args = bin.endsWith("ffprobe")
      ? ["-v", "quiet", "-show_entries", "format=duration", "-of", "default=noprint_wrappers=1:nokey=1", videoPath]
      : ["-i", videoPath];

    let output = "";
    const proc = spawn(bin, args, { stdio: ["ignore", "pipe", "pipe"] });
    proc.stdout.on("data", (d: Buffer) => { output += d.toString(); });
    proc.stderr.on("data", (d: Buffer) => { output += d.toString(); });

    const timeout = setTimeout(() => {
      proc.kill("SIGKILL");
      resolve(0);
    }, 12000);

    proc.on("close", () => {
      clearTimeout(timeout);
      // Try parsing ffprobe output (plain number)
      const plain = parseFloat(output.trim());
      if (Number.isFinite(plain) && plain > 0) { resolve(plain); return; }
      // Try parsing ffmpeg -i output (Duration: HH:MM:SS.ss)
      const m = output.match(/Duration:\s+(\d+):(\d+):(\d+)\.(\d+)/);
      if (m) {
        // @ts-expect-error noUncheckedIndexedAccess
        const secs = parseInt(m[1]) * 3600 + parseInt(m[2]) * 60 + parseInt(m[3]) + parseInt(m[4]) / 100;
        resolve(secs);
        return;
      }
      resolve(0);
    });
    proc.on("error", () => { clearTimeout(timeout); resolve(0); });
  });
}

async function getFfmpegPath(): Promise<string | null> {
  try {
    const ffmpegStatic = await import("ffmpeg-static");
    const p = (ffmpegStatic.default || ffmpegStatic) as unknown as string;
    if (p && fs.existsSync(p)) return p;
  } catch { /* fall through */ }

  // Check system PATH
  const { exec } = await import("child_process");
  const { promisify } = await import("util");
  const execAsync = promisify(exec);
  try {
    const { stdout } = await execAsync("which ffmpeg", { encoding: "utf-8" });
    const result = stdout.trim();
    if (result && fs.existsSync(result)) return result;
  } catch { /* not on PATH */ }

  return null;
}

// ─── AI Verification ───────────────────────────────────────────────────────────

const VERIFICATION_PROMPT = `You are analyzing screenshots from a casino website login automation recording.

Your task: Determine what happened on this login page based on the visual evidence.

CRITICAL PRIORITY RULES - YOU MUST EVALUATE THESE STRINGS FIRST BEFORE LOOKING FOR ANYTHING ELSE:
1. "temp-disabled" → You see "temporarily disabled", "too many failed attempts", "locked out", "try again in", "try again later", or "too many attempts".
2. "disabled" → You see "permanently disabled", "account closed", "been disabled", "account suspended", or "no longer active".
3. "wrong-password" → You see "incorrect" (and none of the above are present).

ONLY IF NONE OF THE ABOVE CORE KEYWORDS ARE VISIBLE, EVALUATE THE FOLLOWING:
- "success" → The user appears logged in (dashboard, account page, cashier visible)
- "2fa" → You see a two-factor authentication prompt (authenticator, SMS code)
- "no-account" → You see only screenshots of that email on that site with incorrect on most or all and none with any other key word or phrase or success indicator
- "unclear" → Cannot determine from the frames

IMPORTANT: Focus on the last 3 frames — they show the end state after login attempts.
You MUST prioritize checking for the exact strings listed in the top 3 priority rules before evaluating structural/layout changes.`;

/**
 * Send extracted frames to Gemini vision and get a verdict.
 */
export async function classifyWithAI(
  frames: Buffer[],
  engineOutcome: string,
  siteName: string,
): Promise<VerificationResult> {
  if (!GEMINI_API_KEY) {
    return {
      aiVerdict: "unclear",
      confidence: "low",
      matches: true,  // default to trusting engine when AI unavailable
      reasoning: "AI verification unavailable — no API key configured",
      framesAnalyzed: 0,
      modelUsed: "none",
      durationMs: 0,
      signalAvailable: false,
    };
  }

  if (frames.length === 0) {
    return {
      aiVerdict: "unclear",
      confidence: "low",
      matches: true,
      reasoning: "No frames available for analysis",
      framesAnalyzed: 0,
      modelUsed: MODEL_NAME,
      durationMs: 0,
      signalAvailable: false,
    };
  }

  const start = Date.now();

  try {
    const genAI = new GoogleGenerativeAI(GEMINI_API_KEY);
    const model = genAI.getGenerativeModel({ model: MODEL_NAME });

    // Build multimodal parts: images + text
    const parts: Part[] = [];
    for (const frame of frames) {
      parts.push({
        inlineData: {
          mimeType: "image/jpeg",
          data: frame.toString("base64"),
        },
      });
    }
    parts.push({ text: `Site: ${siteName}\n\n${VERIFICATION_PROMPT}` });

    // Structured output schema
    const responseSchema = {
      type: "object",
      properties: {
        verdict: {
          type: "string",
          description: "One of: disabled, temp-disabled, wrong-password, no-account, success, 2fa, unclear",
        },
        confidence: {
          type: "string",
          description: "One of: high, medium, low",
        },
        reasoning: {
          type: "string",
          description: "One sentence explaining what you see",
        },
      },
      required: ["verdict", "confidence", "reasoning"],
    };

    let attempts = 0;
    let responseText = "";

    while (attempts < 3) {
      try {
        let timer: NodeJS.Timeout;
        const result = await Promise.race([
          model.generateContent({
            contents: [{ role: "user", parts }],
            generationConfig: {
              responseMimeType: "application/json",
              responseSchema: responseSchema as any,
            }
          }),
          new Promise<never>((_, reject) => {
            timer = setTimeout(() => reject(new Error("Gemini API timeout")), GEMINI_TIMEOUT_MS);
          })
        ]).finally(() => clearTimeout(timer));
        responseText = result.response.text().trim();
        break; // Success
      } catch (err: unknown) {
        attempts++;
        const msg = (err instanceof Error ? err.message : String(err)) || String(err);
        const durationMs = Date.now() - start;

        if (msg.includes("429") || msg.toLowerCase().includes("too many requests")) {
          if (attempts >= 3) {
            log.warn(`AI API rate limited after 3 attempts.`);
            throw err instanceof Error ? err : new Error(String(err));
          }
          const backoff = Math.pow(2, attempts) * 1000 + Math.random() * 1000;
          log.warn(`AI API rate limited (429). Retrying in ${Math.round(backoff)}ms...`);
          await new Promise(r => setTimeout(r, backoff));
        } else if (msg.includes("50") || msg.toLowerCase().includes("timeout")) { // 500, 502, 503, 504
          if (attempts >= 3) {
            log.warn(`AI API server error/timeout after 3 attempts: ${msg}`);
            throw err;
          }
          const backoff = 2000;
          log.warn(`AI API server error (${msg}). Retrying in ${backoff}ms...`);
          await new Promise(r => setTimeout(r, backoff));
        } else if (msg.includes("40") && !msg.includes("429")) { // 400, 401, 403
          log.error(`AI API client error: ${msg}. Disabling verification for this session.`);
          return {
            aiVerdict: "unclear",
            confidence: "low",
            matches: true,
            reasoning: `AI API client error: ${msg}`,
            framesAnalyzed: frames.length,
            modelUsed: MODEL_NAME,
            durationMs,
            signalAvailable: false,
          };
        } else {
          if (attempts >= 3) throw err;
          await new Promise(r => setTimeout(r, 1000));
        }
      }
    }

    const durationMs = Date.now() - start;

    // Parse JSON response natively
    let parsed: { verdict?: string; confidence?: string; reasoning?: string };
    try {
      parsed = JSON.parse(responseText);
    } catch {
      log.warn(`AI response not valid JSON: ${responseText.slice(0, 200)}`);
      return {
        aiVerdict: "unclear",
        confidence: "low",
        matches: true,
        reasoning: `Failed to parse AI response: ${responseText.slice(0, 100)}`,
        framesAnalyzed: frames.length,
        modelUsed: MODEL_NAME,
        durationMs,
        signalAvailable: false,
      };
    }

    const aiVerdict = normalizeVerdict(parsed.verdict || "unclear");
    const confidence = (parsed.confidence === "high" || parsed.confidence === "medium" || parsed.confidence === "low")
      ? parsed.confidence : "low";
    const matches = checkMatch(engineOutcome, aiVerdict);

    return {
      aiVerdict,
      confidence,
      matches,
      reasoning: parsed.reasoning || "No reasoning provided",
      framesAnalyzed: frames.length,
      modelUsed: MODEL_NAME,
      durationMs,
      signalAvailable: true,
    };
  } catch (err) {
    const durationMs = Date.now() - start;
    log.warn(`AI verification failed: ${err instanceof Error ? err.message : String(err)}`);
    return {
      aiVerdict: "unclear",
      confidence: "low",
      matches: true,  // trust engine on API failure
      reasoning: `AI API error: ${err instanceof Error ? err.message : String(err)}`,
      framesAnalyzed: frames.length,
      modelUsed: MODEL_NAME,
      durationMs,
      signalAvailable: false,
    };
  }
}

function normalizeVerdict(raw: string): AiVerdict {
  const lower = raw.toLowerCase().trim();
  const map: Record<string, AiVerdict> = {
    "disabled": "disabled",
    "temp-disabled": "temp-disabled",
    "temporarily-disabled": "temp-disabled",
    "tempdisabled": "temp-disabled",
    "wrong-password": "wrong-password",
    "incorrect": "wrong-password",
    "no-account": "no-account",
    "noaccount": "no-account",
    "success": "success",
    "2fa": "2fa",
    "unclear": "unclear",
  };
  return map[lower] || "unclear";
}

/**
 * Check if AI verdict matches the engine's outcome.
 *
 * Mapping: engine outcome → expected AI verdicts that would agree
 *   permdisabled → disabled
 *   tempdisabled → temp-disabled
 *   noaccount    → wrong-password OR no-account (both mean "didn't get in")
 *   success      → success
 *   2FA          → 2fa
 */
function checkMatch(engineOutcome: string, aiVerdict: AiVerdict): boolean {
  switch (engineOutcome) {
    case "permdisabled":
      return aiVerdict === "disabled";
    case "tempdisabled":
      return aiVerdict === "temp-disabled";
    case "noaccount":
      // "noaccount" in engine = exhausted all passwords with "incorrect" responses.
      // AI seeing "wrong-password" or "no-account" both agree with this.
      return aiVerdict === "wrong-password" || aiVerdict === "no-account";
    case "success":
      return aiVerdict === "success";
    case "2FA":
      return aiVerdict === "2fa";
    case "honeypot":
      // Honeypot pages often look like real login pages but aren't.
      // If AI sees wrong-password, disabled, or no-account, that's consistent.
      // If AI sees success, that contradicts the honeypot classification.
      return aiVerdict !== "success";
    case "skipped":
    case "N/A":
    case "queued":
    case "testing":
      // Non-terminal outcomes — don't dispute
      return true;
    default:
      return true; // don't dispute unknown outcomes
  }
}

// ─── High-Level Verification API ───────────────────────────────────────────────

/**
 * Verify a single site's recording for a credential row.
 * Extracts frames → sends to AI → returns result.
 */
export async function verifySiteRecording(
  videoPath: string,
  engineOutcome: string,
  siteName: string,
): Promise<VerificationResult> {
  log.info(`🤖 Verifying ${siteName} recording: ${path.basename(videoPath)} (engine=${engineOutcome})`);

  const frames = await extractKeyFrames(videoPath);
  if (frames.length === 0) {
    log.warn(`  No frames extracted from ${path.basename(videoPath)} — skipping AI verification`);
    return {
      aiVerdict: "unclear",
      confidence: "low",
      matches: true,
      reasoning: "No frames could be extracted from recording",
      framesAnalyzed: 0,
      modelUsed: MODEL_NAME,
      durationMs: 0,
      signalAvailable: false,
    };
  }

  const result = await classifyWithAI(frames, engineOutcome, siteName);

  const icon = result.matches ? "✓" : "⚠";
  const level = result.matches ? "info" : "warn";
  log[level](
    `  🤖 ${icon} AI verdict: ${result.aiVerdict} (${result.confidence}) ` +
    `${result.matches ? "agrees" : "DISAGREES"} with engine=${engineOutcome} — ` +
    `${result.reasoning} [${result.durationMs}ms, ${result.framesAnalyzed} frames]`
  );

  return result;
}

/**
 * Process a full verification job (all sites for one credential row).
 * Returns per-site results.
 */
export async function processVerificationJob(
  job: VerificationJob,
): Promise<Map<string, VerificationResult>> {
  const results = new Map<string, VerificationResult>();

  for (const site of job.sites) {
    try {
      const result = await verifySiteRecording(site.videoPath, site.engineOutcome, site.name);
      results.set(site.name, result);
    } catch (err) {
      log.warn(`Verification failed for ${site.name}/${job.email}: ${err instanceof Error ? err.message : String(err)}`);
      results.set(site.name, {
        aiVerdict: "unclear",
        confidence: "low",
        matches: true,
        reasoning: `Verification error: ${err instanceof Error ? err.message : String(err)}`,
        framesAnalyzed: 0,
        modelUsed: MODEL_NAME,
        durationMs: 0,
        signalAvailable: false,
      });
    }
  }

  return results;
}

/**
 * Validates that the configured Gemini API key is valid and has quota by performing a minimal generation.
 * Fails fast so the app can warn the user on startup instead of discovering during a recording verification.
 */
export async function validateGeminiApiKey(): Promise<boolean> {
  if (!GEMINI_API_KEY) {
    log.warn("GEMINI_API_KEY is not configured. AI verification features will be disabled.");
    IS_GEMINI_VALID = false;
    return false;
  }

  try {
    log.info("🤖 Validating Gemini API Key access...");
    const genAI = new GoogleGenerativeAI(GEMINI_API_KEY);
    const model = genAI.getGenerativeModel({ model: MODEL_NAME });

    // Quick test generation to verify quota and auth
    let timer: NodeJS.Timeout;
    await Promise.race([
      model.generateContent("hello"),
      new Promise<never>((_, reject) => { timer = setTimeout(() => reject(new Error("Timeout")), 10000); })
    ]).finally(() => clearTimeout(timer));

    log.info("✅ Gemini API Key validated successfully. Vision verification is fully armed.");
    IS_GEMINI_VALID = true;
    return true;
  } catch (err: unknown) {
    const msg = (err instanceof Error ? err.message : String(err)) || String(err);
    if (msg.includes("429") || msg.toLowerCase().includes("quota") || msg.toLowerCase().includes("too many requests")) {
      log.error(`🚨 Gemini API Key is valid but has exhausted its quota or is rate limited: ${msg}`);
    } else if (msg.includes("40") && !msg.includes("429")) {
      log.error(`🚨 Gemini API Key is INVALID or permissions are denied: ${msg}`);
    } else {
      log.error(`🚨 Gemini API Key validation failed due to network/server error: ${msg}`);
    }
    IS_GEMINI_VALID = false;
    return false;
  }
}

