      ["DARK RED", "🚫 Permanently disabled"],
      ["PURPLE", "🛡 Blocked"],
      ["YELLOW", "🔐 2FA required"],
      ["GRAY", "👻 No account found"],
      ["BLUE", "⏳ Currently testing"],
      ["NO FILL", "📋 Queued / not yet tested"],
    ];
    legendData.forEach(([color, meaning], i) => {
      const row = legend.addRow([color, meaning]);
      if (i === 0) {
        row.eachCell(c => { c.font = HEADER_FONT; c.fill = HEADER_FILL; });
      } else {
        const colorMap: any = { GREEN: "success", RED: "incorrect", ORANGE: "tempdisabled", "DARK RED": "permdisabled", PURPLE: "blocked", YELLOW: "2FA", GRAY: "noaccount", BLUE: "testing" };
        const key = colorMap[color as string];
        if (key) {
          const fill = getCellFill(key);
          if (fill) row.getCell(1).fill = fill;
          row.getCell(1).font = getCellFont(key);
        }
      }
    });

    await workbook.xlsx.writeFile(outputPath);
    parentPort?.postMessage({ status: "done" });
  } catch (err: unknown) {
    parentPort?.postMessage({ status: "error", message: (err instanceof Error ? err.message : String(err)) });
  }
});

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unused-expressions, @typescript-eslint/no-unused-vars, @typescript-eslint/require-await */
/**
 * Centralized in-memory sanitization for a Playwright BrowserContext.
 *
 * Cloak's headed and headless reuse paths each had a hand-rolled "close
 * extras → about:blank → clearCookies → clear local/session storage"
 * sequence. Those variants drifted over time and none of them touched
 * permissions, IndexedDB, CacheStorage, or Service Workers — exactly the
 * surfaces fingerprint vendors query for "is this profile fresh?". This
 * module replaces the duplicates with a single best-effort routine.
 *
 * Every step is best-effort: failures are recorded on the returned
 * SanitizationResult rather than thrown, because cleanup runs from
 * close()/finally paths where throwing would mask the original error.
 */
import type { BrowserContext, Page } from "playwright-core";

export interface SanitizationOptions {
  clearCookies?: boolean;
  clearPermissions?: boolean;
  clearStorage?: boolean;
  /** When true, use CDP Storage.clearDataForOrigin("*") for a cross-origin sweep. */
  useCdp?: boolean;
}

export interface SanitizationResult {
  cookiesCleared: boolean;
  permissionsCleared: boolean;
  pagesClosedCount: number;
  storageCleared: boolean;
  serviceWorkersCleared: boolean;
  cdpSwept: boolean;
  errors: string[];
}

async function clearInPageStorage(page: Page): Promise<void> {
  await page.evaluate(async () => {
    try { localStorage.clear(); } catch { /* intentional */ }
    try { sessionStorage.clear(); } catch { /* intentional */ }
    try {

      const idb: any = (globalThis as any).indexedDB;
      if (idb && typeof idb.databases === "function") {
        const dbs = await idb.databases();
        for (const db of dbs) {
          if (db && db.name) { try { idb.deleteDatabase(db.name); } catch { /* intentional */ } }
        }
      }
    } catch { /* intentional */ }
    try {
      if (typeof caches !== "undefined") {
        const keys = await caches.keys();
        await Promise.all(keys.map((k) => caches.delete(k).catch(() => false)));
      }
    } catch { /* intentional */ }
    try {

      const nav: any = (globalThis as any).navigator;
      if (nav && nav.serviceWorker && typeof nav.serviceWorker.getRegistrations === "function") {
        const regs = await nav.serviceWorker.getRegistrations();

        await Promise.all(regs.map((r: any) => r.unregister().catch(() => false)));
      }
    } catch { /* intentional */ }
  });
}

async function sweepViaCdp(context: BrowserContext, page: Page): Promise<void> {
  const cdp = await context.newCDPSession(page);
  try {
    const cookies = await context.cookies();
    const domains = new Set(cookies.map(c => c.domain.replace(/^\./, '')));
    // Playwright API provides no way to discover all origins with localStorage.
    // We guess the origins by looking at what cookies are set.
    for (const d of domains) {
      const origin = `https://${d}`;
      await cdp.send("Storage.clearDataForOrigin", {
        origin,
        storageTypes:
          "appcache,cookies,file_systems,indexeddb,local_storage,shader_cache,websql,service_workers,cache_storage",

      } as any).catch(() => {});
    }
  } finally {
    await cdp.detach().catch(() => { });
  }
}

export async function sanitizeBrowserContext(
  context: BrowserContext,
  opts: SanitizationOptions = {}
): Promise<SanitizationResult> {
  const clearCookies = opts.clearCookies ?? true;
  const clearPermissions = opts.clearPermissions ?? true;
  const clearStorage = opts.clearStorage ?? true;
  const useCdp = opts.useCdp ?? true;

  const result: SanitizationResult = {
    cookiesCleared: false,
    permissionsCleared: false,
    pagesClosedCount: 0,
    storageCleared: false,
    serviceWorkersCleared: false,
    cdpSwept: false,
    errors: [],
  };

  const pages = context.pages();
  for (let i = 1; i < pages.length; i++) {
    try {
      const page = pages[i];
      if (page) await page.close();
      result.pagesClosedCount++;
    } catch (e: unknown) {
      result.errors.push(`close-page: ${(e instanceof Error ? e.message : String(e)) ?? e}`);
    }
  }

  let main: Page | undefined = context.pages()[0];
  if (!main) {
    try { main = await context.newPage(); }
    catch (e: unknown) { result.errors.push(`new-page: ${(e instanceof Error ? e.message : String(e)) ?? e}`); }
  }
  if (main) {
    try { await main.goto("about:blank"); }
    catch (e: unknown) { result.errors.push(`goto-blank: ${(e instanceof Error ? e.message : String(e)) ?? e}`); }
  }

  if (clearCookies) {
    try { await context.clearCookies(); result.cookiesCleared = true; }
    catch (e: unknown) { result.errors.push(`clear-cookies: ${(e instanceof Error ? e.message : String(e)) ?? e}`); }
  }

  if (clearPermissions) {
    try { await context.clearPermissions(); result.permissionsCleared = true; }
    catch (e: unknown) { result.errors.push(`clear-permissions: ${(e instanceof Error ? e.message : String(e)) ?? e}`); }
  }

  if (clearStorage && main) {
    try {
      await clearInPageStorage(main);
      result.storageCleared = true;
      result.serviceWorkersCleared = true;
    } catch (e: unknown) {
      result.errors.push(`clear-storage: ${(e instanceof Error ? e.message : String(e)) ?? e}`);
    }
  }

  if (useCdp && main) {
    try {
      await sweepViaCdp(context, main);
      result.cdpSwept = true;
    } catch (e: unknown) {
      result.errors.push(`cdp-sweep: ${(e instanceof Error ? e.message : String(e)) ?? e}`);
    }
  }

  return result;
}

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unused-expressions, @typescript-eslint/no-unused-vars, @typescript-eslint/require-await */
import fs from 'node:fs';
import path from 'node:path';
import { createLogger } from "../core/logger.js";
import { GoogleGenerativeAI } from "@google/generative-ai";
import { type ProfileBundle } from "../profiles/profile-validator.js";

const log = createLogger("fingerprint-ai");

const GEMINI_API_KEY = (process.env.GEMINI_API_KEY || process.env.GOOGLE_AI_API_KEY || process.env.GOOGLE_AGENT_PLATFORM_API_KEY || "").trim();
const MODEL_NAME = "gemini-2.5-flash";
const CACHE_FILE = path.resolve(process.cwd(), "fingerprint-ai-cache.json");
const AI_TIMEOUT_MS = 20_000;

export interface AiFingerprintCheck {
  coherent: boolean;
  mismatches: string[];
  fixSuggestions: Record<string, string>;
  modelUsed: string;
}

// In-memory cache loaded from disk
let aiCheckCache: Record<string, AiFingerprintCheck> = {};
try {
  if (fs.existsSync(CACHE_FILE)) {
    aiCheckCache = JSON.parse(fs.readFileSync(CACHE_FILE, "utf-8"));
  }
} catch (e) {
  log.warn(`Failed to load AI fingerprint cache: ${String(e)}`);
}

function saveCache() {
  try {
    fs.writeFileSync(CACHE_FILE, JSON.stringify(aiCheckCache, null, 2), "utf-8");
  } catch (e) {
    log.warn(`Failed to save AI fingerprint cache: ${String(e)}`);
  }
}

const VERIFICATION_PROMPT = `You are a bot-detection bypass engineer analyzing a browser fingerprint bundle.
Your task is to ensure the generated fingerprint components are fully coherent and look like a real, naturally occurring user session.

Analyze the provided JSON fingerprint bundle and cross-check the following for consistency:
1. User-Agent vs OS/Platform: Does the UA match the OS, and does the hardware (cores/memory/GPU) match the OS? (e.g., Apple Silicon on Mac, no NVIDIA on Mac).
2. Resolution vs Device Type: Is a desktop UA paired with a mobile resolution, or vice versa?
3. Geolocation vs Proxy: Does the timezone and locale align with the country implied by the proxy?
4. WebGL renderer vs OS: Does the GPU vendor/renderer make sense for the claimed OS?
5. Font list vs OS: Are the listed fonts appropriate for the claimed operating system?
6. Client Hints vs UA: Do sec-ch-ua brands match the claimed Chrome version?

Return a JSON verdict with:
- "coherent" (boolean): true if the fingerprint looks perfectly natural, false if it has obvious mismatches.
- "mismatches" (array of strings): List of specific inconsistencies found. Empty if perfectly coherent.
- "fixSuggestions" (object): Key-value pairs of suggested overrides to fix the profile (e.g., {"osProfile": "windows", "gpu": "Intel Iris Plus"}). Empty if coherent.

Only output valid JSON matching this schema. Focus only on obvious "bot" tells — minor imperfections that real users also have are fine.`;

export async function verifyFingerprintCoherence(
  bundle: ProfileBundle
): Promise<AiFingerprintCheck> {
  // Generate a cache key from the bundle contents
  const bundleStr = JSON.stringify(bundle);
  const cacheKey = simpleHash(bundleStr);

  // Return cached result if available
  if (aiCheckCache[cacheKey]) {
    log.debug(`AI fingerprint check cache hit for ${cacheKey}`);
    return aiCheckCache[cacheKey];
  }

  // If no API key, return optimistic result but don't cache
  if (!GEMINI_API_KEY) {
    log.debug("AI fingerprint verification skipped — no API key");
    return { coherent: true, mismatches: [], fixSuggestions: {}, modelUsed: "disabled" };
  }

  try {
    const genAI = new GoogleGenerativeAI(GEMINI_API_KEY);
    const model = genAI.getGenerativeModel({ model: MODEL_NAME });

    const responseSchema = {
      type: "object",
      properties: {
        coherent: { type: "boolean", description: "true if fingerprint is coherent" },
        mismatches: {
          type: "array",
          items: { type: "string" },
          description: "List of inconsistencies found",
        },
        fixSuggestions: {
          type: "object",
          description: "Key-value pairs of suggested fixes",
        },
      },
      required: ["coherent", "mismatches", "fixSuggestions"],
    };

    let timeoutTimer: NodeJS.Timeout;
    const result = await Promise.race([
      model.generateContent({
        contents: [{
          role: "user",
          parts: [{
            text: `Analyze this browser fingerprint bundle for coherence:\n\n${JSON.stringify(bundle, null, 2)}\n\n${VERIFICATION_PROMPT}`,
          }],
        }],
        generationConfig: {
          responseMimeType: "application/json",
          responseSchema: responseSchema as any,
        },
      }),
      new Promise<never>((_, reject) => {
        timeoutTimer = setTimeout(() => reject(new Error("AI fingerprint check timeout")), AI_TIMEOUT_MS);
      }),
    ]).finally(() => clearTimeout(timeoutTimer));

    const responseText = result.response.text().trim();
    let parsed: any;
    try {
      parsed = JSON.parse(responseText);
    } catch {
      log.warn(`AI fingerprint response not valid JSON: ${responseText.slice(0, 200)}`);
      return { coherent: true, mismatches: [], fixSuggestions: {}, modelUsed: MODEL_NAME };
    }

    const check: AiFingerprintCheck = {
      coherent: parsed.coherent === true,
      mismatches: Array.isArray(parsed.mismatches) ? parsed.mismatches : [],
      fixSuggestions: typeof parsed.fixSuggestions === "object" ? parsed.fixSuggestions : {},
      modelUsed: MODEL_NAME,
    };

    // Cache the result
    aiCheckCache[cacheKey] = check;
    saveCache();

    if (!check.coherent) {
      log.warn(
        `⚠ Fingerprint INCOHERENT — ${check.mismatches.length} mismatch(es): ` +
        check.mismatches.join("; ")
      );
    } else {
      log.info(`✓ Fingerprint coherent (verified by ${MODEL_NAME})`);
    }

    return check;
  } catch (err) {
    log.warn(`AI fingerprint verification failed: ${err instanceof Error ? err.message : String(err)}`);
    return { coherent: true, mismatches: [], fixSuggestions: {}, modelUsed: "error" };
  }
}

/** Simple string hash for cache keys */
function simpleHash(str: string): string {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash |= 0; // Convert to 32-bit integer
  }
  return `fp-${Math.abs(hash).toString(36)}`;
}

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unused-expressions, @typescript-eslint/no-unused-vars, @typescript-eslint/require-await */
/**
 * Fingerprint Rotation Engine
 *
 * Manages session-counter-based fingerprint rotation, timezone↔proxy
 * geo-synchronisation, and dynamic attribute blending across sessions.
 *
 * Key concepts:
 *  • Each credential is assigned a **rotation counter** that increments
 *    every N sessions (default 3). The counter feeds into every
 *    deterministic profile function (hardware, fonts, UA, cache, geo)
 *    so the same credential gets a *different but internally-consistent*
 *    fingerprint bundle after the Nth attempt.
 *
 *  • Timezone/locale are always re-derived from the active proxy IP so
 *    a profile rotation never desynchronises the geo signals.
 *
 *  • A `RotationLedger` tracks per-credential session counts and
 *    rotation history, persisted to a JSON file.
 */

import fs from "node:fs";
import { emailToFingerprintSeed } from "../core/crypto-utils.js";
import { getConsistentHardware, type HardwareProfile } from "../profiles/profile-determinism.js";
import { getConsistentUserAgent, type UAProfile, type TargetOS } from "../profiles/profile-useragent.js";
import { alignGeoToProxy, type GeoProfile } from "../profiles/profile-geo-alignment.js";
import { getConsistentResolution, type Resolution } from "../profiles/profile-resolution.js";
import { getFontProfile, type FontProfile } from "../profiles/profile-fonts.js";
import { getCacheProfile, type CacheProfile } from "../profiles/profile-cache.js";

// ── Types ────────────────────────────────────────────────────────────────────

export interface RotationEntry {
  email: string;
  sessionCount: number;
  currentRotation: number;
  lastRotatedAt: string;       // ISO-8601
  history: number[];           // rotation indices used
}

export interface RotatedProfile {
  email: string;
  rotation: number;
  seed: number;
  ua: UAProfile;
  hardware: HardwareProfile;
  geo: GeoProfile;
  resolution: Resolution;
  fonts: FontProfile;
  cache: CacheProfile;
}

export interface RotationEngineOptions {
  /** Sessions before a fingerprint rotation (default 3). */
  sessionsPerRotation?: number;
  /** Path to persist the rotation ledger JSON. */
  ledgerPath?: string;
  /** Optional logger. */
  log?: (msg: string) => void;
}

// ── Defaults ─────────────────────────────────────────────────────────────────

const DEFAULT_SESSIONS_PER_ROTATION = 3;
const DEFAULT_LEDGER_PATH = "rotation-ledger.json";

// ── Ledger persistence ───────────────────────────────────────────────────────

type Ledger = Map<string, RotationEntry>;

function loadLedger(filePath: string): Ledger {
  const ledger: Ledger = new Map();
  try {
    if (fs.existsSync(filePath)) {
      const raw = JSON.parse(fs.readFileSync(filePath, "utf-8")) as RotationEntry[];
      for (const entry of raw) {
        ledger.set(entry.email.toLowerCase().trim(), entry);
      }
    }
  } catch {
    // Start fresh on any parse error
  }
  return ledger;
}

function saveLedger(ledger: Ledger, filePath: string): void {
  const entries = Array.from(ledger.values());
  try {
    fs.writeFileSync(filePath, JSON.stringify(entries, null, 2), "utf-8");
  } catch {
    // Non-critical — ledger will be rebuilt on next run
  }
}

// ── Engine ───────────────────────────────────────────────────────────────────

export class FingerprintRotationEngine {
  private readonly sessionsPerRotation: number;
  private readonly ledgerPath: string;
  private readonly log: (msg: string) => void;
  private ledger: Ledger;

  constructor(opts: RotationEngineOptions = {}) {
    this.sessionsPerRotation = opts.sessionsPerRotation ?? DEFAULT_SESSIONS_PER_ROTATION;
    this.ledgerPath = opts.ledgerPath ?? DEFAULT_LEDGER_PATH;
    this.log = opts.log ?? (() => {});
    this.ledger = loadLedger(this.ledgerPath);
  }

  // ── Public API ─────────────────────────────────────────────────────────

  /**
   * Record a session attempt for `email` and return the current rotation
   * counter. Automatically increments the rotation when the session
   * threshold is crossed.
   */
  recordSession(email: string): number {
    const key = email.toLowerCase().trim();
    let entry = this.ledger.get(key);

    if (!entry) {
      entry = {
        email: key,
        sessionCount: 0,
        currentRotation: 0,
        lastRotatedAt: new Date().toISOString(),
        history: [0],
      };
      this.ledger.set(key, entry);
    }

    entry.sessionCount++;

    if (entry.sessionCount >= this.sessionsPerRotation) {
      entry.sessionCount = 0;
      entry.currentRotation++;
      entry.lastRotatedAt = new Date().toISOString();
      entry.history.push(entry.currentRotation);
      this.log(`[rotation] ${key} → rotation ${entry.currentRotation}`);
    }

    this.persist();
    return entry.currentRotation;
  }

  /**
   * Get the current rotation counter without incrementing sessions.
   */
  getRotation(email: string): number {
    const key = email.toLowerCase().trim();
    return this.ledger.get(key)?.currentRotation ?? 0;
  }

  /**
   * Get the raw session count (not rotation index) for a credential.
   * This is needed by the hardware rotation module to know when
   * the next rotation trigger will fire.
   */
  getSessionCount(email: string): number {
    const key = email.toLowerCase().trim();
    return this.ledger.get(key)?.sessionCount ?? 0;
  }

  /**
   * Sessions before a fingerprint rotation triggers.
   */
  get rotationCadence(): number {
    return this.sessionsPerRotation;
  }

  /**
   * Force-set a specific rotation for a credential (e.g. after a burn).
   */
  forceRotation(email: string, rotation: number): void {
    const key = email.toLowerCase().trim();
    let entry = this.ledger.get(key);
    if (!entry) {
      entry = {
        email: key,
        sessionCount: 0,
        currentRotation: rotation,
        lastRotatedAt: new Date().toISOString(),
        history: [rotation],
      };
      this.ledger.set(key, entry);
    } else {
      entry.currentRotation = rotation;
      entry.sessionCount = 0;
      entry.lastRotatedAt = new Date().toISOString();
      entry.history.push(rotation);
    }
    this.persist();
    this.log(`[rotation] ${key} → forced to rotation ${rotation}`);
  }

  /**
   * Build a fully-rotated, internally-consistent fingerprint profile
   * for the given credential and proxy.
   */
  buildRotatedProfile(
    email: string,
    proxyUrl?: string,
    mobile?: boolean,
  ): RotatedProfile {
    const rotation = this.getRotation(email);
    const seed = emailToFingerprintSeed(email, rotation);
    const ua = getConsistentUserAgent(email, "mixed", proxyUrl, "chrome", rotation);
    if (!ua) throw new Error(`[rotation] No UA profile available for ${email}`);
    const hardware = getConsistentHardware(email, ua.os, rotation);
    const geo = alignGeoToProxy(proxyUrl, email, mobile);
    const resolution = getConsistentResolution(email, ua.os, rotation);
    const fonts = getFontProfile(email);
    const cache = getCacheProfile(email, ua.chromeMajor);

    this.log(
      `[rotation] Profile for ${email}: rot=${rotation} seed=${seed} ` +
      `ua=${ua.chromeMajor}/${ua.os} hw=${hardware.cores}c/${hardware.memory}GB ` +
      `geo=${geo.countryCode} res=${resolution.width}x${resolution.height}`,
    );

    return { email, rotation, seed, ua, hardware, geo, resolution, fonts, cache };
  }

  /**
   * Reset a credential's rotation counter (e.g. on success).
   */
  resetRotation(email: string): void {
    const key = email.toLowerCase().trim();
    const entry = this.ledger.get(key);
    if (entry) {
      entry.currentRotation = 0;
      entry.sessionCount = 0;
      entry.lastRotatedAt = new Date().toISOString();
      this.persist();
    }
  }

  /**
   * Get the full ledger snapshot (for dashboard display).
   */
  snapshot(): RotationEntry[] {
    return Array.from(this.ledger.values());
  }

  /**
   * Get the entry for a single credential.
   */
  getEntry(email: string): RotationEntry | undefined {
    return this.ledger.get(email.toLowerCase().trim());
  }

  /** Number of tracked credentials. */
  get size(): number {
    return this.ledger.size;
  }

  // ── Internals ──────────────────────────────────────────────────────────

  private persist(): void {
    saveLedger(this.ledger, this.ledgerPath);
  }
}

// ── Convenience factory ──────────────────────────────────────────────────────

let _singleton: FingerprintRotationEngine | undefined;

export function getRotationEngine(opts?: RotationEngineOptions): FingerprintRotationEngine {
  if (!_singleton) {
    _singleton = new FingerprintRotationEngine(opts);
  }
  return _singleton;
}

/** Reset the singleton (used in tests). */
export function _resetRotationEngine(): void {
  _singleton = undefined;
}

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unused-expressions, @typescript-eslint/no-unused-vars, @typescript-eslint/require-await */
import type { Page } from "playwright";
import { createLogger } from "../core/logger.js";

const log = createLogger("live-auditor");

export interface FingerprintMismatch {
  expectedUA: string;
  expectedOS: string;
  actualJA3?: string;
  actualHTTP2?: string;
  actualNavigatorUserAgent?: string;
  actualHardwareConcurrency?: number;
}

/**
 * Asynchronously triggers a non-blocking fetch from within the Playwright context
 * to the local `/audit-fp` endpoint to verify TLS, HTTP2, and JS Fingerprint coherence.
 * Mismatches are logged to telemetry. 
 * Does NOT await the fetch result to prevent slowing down page.goto.
 */
export function startAsyncFingerprintAudit(
  page: Page,
  expectedUA: string,
  expectedOS: string,
  serverPort: number = 3011
): void {
  const auditUrl = `http://localhost:${serverPort}/audit-fp`;

  // Inject a non-blocking evaluate call
  page.evaluate(
    (args) => {
      const { url, expectedUA, expectedOS } = args;

      // We perform an asynchronous fetch that we don't await,
      // sending client-side JS evidence in the payload
      fetch(url, {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          expectedUA,
          expectedOS,
          jsEvidence: {
            userAgent: navigator.userAgent,
            hardwareConcurrency: navigator.hardwareConcurrency,
            deviceMemory: (navigator as any).deviceMemory,
            platform: navigator.platform,
            vendor: navigator.vendor,
            timezone: Intl.DateTimeFormat().resolvedOptions().timeZone
          }
        })
      }).catch(e => console.error("LiveAuditor Fetch Failed:", e));
    },
    { url: auditUrl, expectedUA, expectedOS }
  ).catch(e => {
    log.debug(`Failed to inject live auditor: ${e.message}`);
  });
}

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unused-expressions, @typescript-eslint/no-unused-vars, @typescript-eslint/require-await */
/**
 * Randomized Login Actions — 20 Micro-Behavioral Variations
 *
 * Each function adds a small, fast, randomized human behavior that
 * makes the automation indistinguishable from real human interaction.
 * All actions use Gaussian distributions and are lightweight (< 500ms).
 *
 * These are called from engine.ts at strategic points in the login flow.
 */
import { gaussianClamped, gaussianInt } from "../core/gaussian-rng.js";
import { humanMouseMove, humanScroll, injectMicroTremor, humanClickAt, humanClickSelector } from "../intelligence/mouse-humanizer.js";
import { createLogger } from "../core/logger.js";
import type { Page } from "playwright-core";

const log = createLogger("random-actions");

// ─── Helper: get element bounding box safely ──────────────────────────────────
async function getBox(page: Page, selector: string) {
  try {
    return await page.locator(selector).boundingBox();
  } catch { return null; }
}

// ─── Helper: random point inside element bounds (not always center!) ──────────
function randomPointInBox(box: { x: number; y: number; width: number; height: number }): { x: number; y: number } {
  // Gaussian centered on center but with spread across the element
  const x = gaussianClamped(
    box.x + box.width / 2,
    box.width * 0.15, // stddev = 15% of width
    box.x + 4,
    box.x + box.width - 4,
  );
  const y = gaussianClamped(
    box.y + box.height / 2,
    box.height * 0.15,
    box.y + 2,
    box.y + box.height - 2,
  );
  return { x: Math.round(x), y: Math.round(y) };
}

// ═══════════════════════════════════════════════════════════════════════════════
// 1. SUBMIT METHOD VARIANCE
// Instead of always clicking the submit button, randomly choose between
// clicking, pressing Enter in password field, Tab→Enter, Tab→Space,
// double-click, triple-click, click at offset, or JavaScript form.submit().
// ═══════════════════════════════════════════════════════════════════════════════

export type SubmitMethod = "click" | "enter_in_password" | "tab_enter" | "tab_space" | "click_offset" | "double_click" | "triple_click" | "js_submit";

export function chooseSubmitMethod(): SubmitMethod {
  const roll = Math.random();
  if (roll < 0.40) return "click";              // 40% — normal single click on button
  if (roll < 0.75) return "click_offset";       // 35% — click at random offset within button
  if (roll < 0.90) return "double_click";       // 15% — rapid double-click on button
  return "triple_click";                        // 10% — triple-click on button
}

export async function executeSubmit(
  page: Page,
  submitSelector: string,
  passwordSelector: string,
  method?: SubmitMethod,
): Promise<void> {
  const m = method || chooseSubmitMethod();
  log.debug(`Submit method: ${m}`);

  switch (m) {
    case "enter_in_password": {
      // Focus password field and press Enter — very common for keyboard users
      await page.focus(passwordSelector).catch(() => {});
      /* stripped sleep */
      await page.keyboard.press("Enter");
      break;
    }
    case "tab_enter": {
      // Tab from password to submit, then Enter
      await page.focus(passwordSelector).catch(() => {});
      /* stripped sleep */
      await page.keyboard.press("Tab");
      /* stripped sleep */
      await page.keyboard.press("Enter");
      break;
    }
    case "tab_space": {
      // Tab to submit, then Space (activates buttons)
      await page.focus(passwordSelector).catch(() => {});
      /* stripped sleep */
      await page.keyboard.press("Tab");
      /* stripped sleep */
      await page.keyboard.press("Space");
      break;
    }
    case "click_offset": {
      // Click at a random point inside the button (not center)
      const box = await getBox(page, submitSelector);
      if (box) {
        const pt = randomPointInBox(box);
        await humanMouseMove(page, pt.x, pt.y);
        /* stripped sleep */
        await humanClickAt(page, pt.x, pt.y);
      } else {
        await humanClickSelector(page, submitSelector, { force: true });
      }
      break;
    }
    case "double_click": {
      // Rapid double-click on the submit button
      const box = await getBox(page, submitSelector);
      if (box) {
        const cx = box.x + box.width / 2 + gaussianClamped(0, 2, -6, 6);
        const cy = box.y + box.height / 2 + gaussianClamped(0, 1.8, -6, 6);
        await humanMouseMove(page, cx, cy);
        /* stripped sleep */
        await humanClickAt(page, Math.round(cx), Math.round(cy), { clickCount: 2 });
      } else {
        await humanClickSelector(page, submitSelector, { force: true, clickCount: 2 });
      }
      break;
    }
    case "triple_click": {
      // Triple-click on the submit button (some users click frantically)
      const box = await getBox(page, submitSelector);
      if (box) {
        const cx = box.x + box.width / 2 + gaussianClamped(0, 2, -6, 6);
        const cy = box.y + box.height / 2 + gaussianClamped(0, 1.8, -6, 6);
        await humanMouseMove(page, cx, cy);
        /* stripped sleep */
        await humanClickAt(page, Math.round(cx), Math.round(cy), { clickCount: 3 });
      } else {
        await humanClickSelector(page, submitSelector, { force: true, clickCount: 3 });
      }
      break;
    }
    case "js_submit": {
      // JavaScript form.submit() — bypasses click entirely, uses the DOM API
      // Some real browser extensions and autofill tools submit forms this way
      const submitted = await page.evaluate((sel) => {
        const btn = document.querySelector(sel);
        if (!btn) return false;
        // Walk up from the button to find the enclosing <form>
        const form = btn.closest("form");
        if (form) {
          // requestSubmit() fires the submit event (respects SPA/AJAX handlers)
          // unlike form.submit() which bypasses JS listeners entirely
          if (typeof form.requestSubmit === "function") {
            form.requestSubmit(btn instanceof HTMLButtonElement ? btn : undefined);
          } else {
            // Old browsers: fall back to programmatic btn.click()
            btn.click();
          }
          return true;
        }
        // No form wrapper — trigger a click event programmatically
        btn.click();
        return true;
      }, submitSelector).catch(() => false);
      if (!submitted) {
        // Ultimate fallback: standard click
        await humanClickSelector(page, submitSelector, { force: true });
      }
      break;
    }
    case "click":
    default: {
      // Standard center click with slight Gaussian offset
      const box = await getBox(page, submitSelector);
      if (box) {
        const cx = box.x + box.width / 2 + gaussianClamped(0, 3, -8, 8);
        const cy = box.y + box.height / 2 + gaussianClamped(0, 2, -5, 5);
        await humanMouseMove(page, cx, cy);
        /* stripped sleep */
        await humanClickAt(page, Math.round(cx), Math.round(cy));
      } else {
        await humanClickSelector(page, submitSelector, { force: true });
      }
      break;
    }
  }
}

