        windowsLabel: "Win10",
        os: "windows",
        platformVersion: "10",
        architecture: "x64"
      };
      
      expect(_test.isUAProfile(validBase)).toBe(true);
      expect(_test.isUAProfile({ ...validBase, ua: "NotMozilla" })).toBe(false);
      expect(_test.isUAProfile({ ...validBase, os: "unknown" })).toBe(false);
      
      const validMobile = {
        ...validBase,
        os: "android",
        mobile: true,
        deviceModel: "Pixel 6",
        deviceMemory: 8,
        touchSupport: true,
        screen: { width: 1080, height: 2400, pixelRatio: 2 },
        connection: { type: "4g", downlink: 100, rtt: 20 }
      };
      expect(_test.isUAProfile(validMobile)).toBe(true);
      
      // Invalid mobile subfields
      expect(_test.isUAProfile({ ...validMobile, deviceModel: 123 })).toBe(false);
      expect(_test.isUAProfile({ ...validMobile, deviceMemory: "8GB" })).toBe(false);
      expect(_test.isUAProfile({ ...validMobile, touchSupport: "yes" })).toBe(false);
      expect(_test.isUAProfile({ ...validMobile, webgl: { vendor: "ARM" } })).toBe(false); // missing renderer
      expect(_test.isUAProfile({ ...validMobile, battery: { charging: true } })).toBe(false); // missing level
    });

    it("loadPool handles invalid shapes and unknown connection types gracefully", () => {
      // Temporarily overwrite ua-pool-chrome.json with garbage
      const tmpPath = path.resolve(process.cwd(), "data", "ua-pool-chrome.json");
      let original = "";
      let exists = false;
      if (fs.existsSync(tmpPath)) {
        exists = true;
        original = fs.readFileSync(tmpPath, "utf-8");
      } else {
        fs.mkdirSync(path.dirname(tmpPath), { recursive: true });
      }

      fs.writeFileSync(tmpPath, JSON.stringify([
        { ua: "invalid" }, // dropped
        {
          ua: "Mozilla/5.0", chromeVersion: "130", chromeMajor: 130,
          windowsVersion: "10", windowsLabel: "Win10", os: "windows",
          platformVersion: "10", architecture: "x64",
          connection: { type: "6g-advanced", downlink: 100, rtt: 10 } // accepted but warns
        }
      ]));

      const res = _test.loadPool("ua-pool-chrome.json");
      expect(res.length).toBe(1);

      if (exists) {
        fs.writeFileSync(tmpPath, original);
      } else {
        fs.unlinkSync(tmpPath);
      }
    });

    it("loadPool falls back to BUNDLED_POOL if parsing fails", () => {
      const tmpPath = path.resolve(process.cwd(), "data", "ua-pool-chrome.json");
      let original = "";
      let exists = false;
      if (fs.existsSync(tmpPath)) {
        exists = true;
        original = fs.readFileSync(tmpPath, "utf-8");
      }

      fs.writeFileSync(tmpPath, "}{ not valid json");
      const res = _test.loadPool("ua-pool-chrome.json");
      expect(res.length).toBeGreaterThan(0);
      expect(res[0]!.ua).toBeDefined();

      if (exists) {
        fs.writeFileSync(tmpPath, original);
      } else {
        fs.unlinkSync(tmpPath);
      }
    });
  });

  describe("getConsistentUserAgent auto targeting branches", () => {
    it("falls back to linux when auto target yields a hash >= 95", () => {
      // Find an email that hashes to >= 95
      let targetEmail = "";
      for (let i = 0; i < 1000; i++) {
        const email = `linux-target-${i}@example.com`;
        const h = (require("crypto").createHash("sha256").update(email).digest().readUInt32BE(0)) % 100;
        if (h >= 95) {
          targetEmail = email;
          break;
        }
      }
      if (targetEmail) {
        const ua = getConsistentUserAgent(targetEmail, "auto");
        // Bundled pool only has windows and macos, so it will fall back to 'mixed'
        // But the code branch `else resolvedOs = "linux"` will be covered.
        expect(ua).toBeDefined();
      }
    });

    it("falls back to mixed when auto-proxy is used with non-spider string", () => {
      const ua = getConsistentUserAgent("test@example.com", "auto-proxy", "http://normal-proxy.com");
      expect(ua).toBeDefined();
    });
  });
});

import { describe, it, expect } from "vitest";
import { startProxyForwarder } from "../../src/proxy/proxy-forwarder.js";
import * as net from "net";

describe("Proxy Forwarder", () => {
  it("rejects invalid upstream servers", async () => {
    await expect(startProxyForwarder({ server: "" })).rejects.toThrow("proxy forwarder requires upstream.server");
    await expect(startProxyForwarder({ server: "not-a-url" } as any)).rejects.toThrow("invalid upstream proxy URL");
    await expect(startProxyForwarder({ server: "ftp://proxy.com" })).rejects.toThrow("proxy forwarder only supports http and socks5");
  });

  it("handles basic http proxy forwarding", async () => {
    // Create a dummy HTTP proxy server to act as upstream
    const dummyUpstream = net.createServer((socket) => {
      socket.on("data", (data) => {
        if (data.toString().includes("CONNECT test.com:443")) {
          socket.write("HTTP/1.1 200 Connection Established\r\n\r\n");
        }
      });
    });

    await new Promise<void>(resolve => dummyUpstream.listen(0, "127.0.0.1", resolve));
    const port = (dummyUpstream.address() as net.AddressInfo).port;

    const forwarder = await startProxyForwarder({ server: `http://127.0.0.1:${port}`, username: "usr", password: "pwd" });
    expect(forwarder.serverUrl.startsWith("http://127.0.0.1:")).toBe(true);

    // Test a fake CONNECT request
    const fwdPort = new URL(forwarder.serverUrl).port;
    const client = net.connect(Number(fwdPort), "127.0.0.1");
    client.write("CONNECT test.com:443 HTTP/1.1\r\nHost: test.com:443\r\n\r\n");

    const response = await new Promise<string>((resolve) => {
      client.on("data", (data) => resolve(data.toString()));
    });

    expect(response).toContain("HTTP/1.1 200 Connection Established");

    client.destroy();
    await forwarder.close();
    await new Promise<void>(resolve => dummyUpstream.close(() => resolve()));
  });
  it("handles standard http proxy GET forwarding", async () => {
    const dummyUpstream = net.createServer((socket) => {
      socket.on("data", (data) => {
        if (data.toString().includes("GET")) {
          socket.write("HTTP/1.1 200 OK\r\nContent-Length: 5\r\n\r\nHello");
          socket.end();
        }
      });
    });

    await new Promise<void>(resolve => dummyUpstream.listen(0, "127.0.0.1", resolve));
    const port = (dummyUpstream.address() as net.AddressInfo).port;

    const forwarder = await startProxyForwarder({ server: `http://127.0.0.1:${port}`, username: "usr", password: "pwd" });
    const fwdPort = new URL(forwarder.serverUrl).port;

    const client = net.connect(Number(fwdPort), "127.0.0.1");
    client.write("GET http://example.com/ HTTP/1.1\r\nHost: example.com\r\n\r\n");

    const response = await new Promise<string>((resolve) => {
      let res = "";
      client.on("data", (data) => {
        res += data.toString();
        if (res.includes("Hello")) resolve(res);
      });
      client.on("error", () => resolve(res));
    });

    expect(response).toContain("HTTP/1.1 200 OK");
    expect(response).toContain("Hello");

    client.destroy();
    await forwarder.close();
    await new Promise<void>(resolve => dummyUpstream.close(() => resolve()));
  });

  it("handles non-200 CONNECT proxy errors gracefully", async () => {
    const dummyUpstream = net.createServer((socket) => {
      socket.on("data", (data) => {
        if (data.toString().includes("CONNECT")) {
          socket.write("HTTP/1.1 407 Proxy Auth Required\r\n\r\n");
          socket.end();
        }
      });
    });

    await new Promise<void>(resolve => dummyUpstream.listen(0, "127.0.0.1", resolve));
    const port = (dummyUpstream.address() as net.AddressInfo).port;

    const forwarder = await startProxyForwarder({ server: `http://127.0.0.1:${port}` });
    const fwdPort = new URL(forwarder.serverUrl).port;

    const client = net.connect(Number(fwdPort), "127.0.0.1");
    client.write("CONNECT test.com:443 HTTP/1.1\r\nHost: test.com:443\r\n\r\n");

    const response = await new Promise<string>((resolve) => {
      let res = "";
      client.on("data", (data) => res += data.toString());
      client.on("end", () => resolve(res));
    });

    expect(response).toContain("HTTP/1.1 407 Proxy Auth Required");

    client.destroy();
    await forwarder.close();
    await new Promise<void>(resolve => dummyUpstream.close(() => resolve()));
  });
});

import { describe, it, expect, vi, beforeEach } from "vitest";
import {
  pingTargetUrl,
  pingViaBackendStack,
  preValidatePool,
  preValidateProxy
} from "../../src/proxy/proxy-pre-ping.js";
import fetch from "node-fetch";
import net from "node:net";

vi.mock("node-fetch");
vi.mock("node:net");

vi.mock("../../backends/httpcloak-forwarder.js", () => ({
  startHttpCloakForwarder: vi.fn()
}));
vi.mock("../../src/proxy/proxy-forwarder.js", () => ({
  startProxyForwarder: vi.fn()
}));

describe("proxy-pre-ping", () => {
  beforeEach(() => {
    vi.clearAllMocks();
    vi.spyOn(console, "log").mockImplementation(() => {});
    vi.spyOn(console, "error").mockImplementation(() => {});
    vi.spyOn(console, "warn").mockImplementation(() => {});
    vi.spyOn(console, "debug").mockImplementation(() => {});
  });

  describe("pingTargetUrl", () => {
    const proxy = { server: "http://proxy:8080" } as any;

    it("returns reachable if fetch succeeds with 200", async () => {
      vi.mocked(fetch).mockResolvedValue({ status: 200, statusText: "OK" } as any);
      const res = await pingTargetUrl(proxy, "http://target.com", "target");
      expect(res.reachable).toBe(true);
      expect(res.statusCode).toBe(200);
    });

    it("returns reachable for 302", async () => {
      vi.mocked(fetch).mockResolvedValue({ status: 302, statusText: "Found" } as any);
      const res = await pingTargetUrl(proxy, "http://target.com", "target");
      expect(res.reachable).toBe(true);
    });

    it("returns reachable for 503", async () => {
      vi.mocked(fetch).mockResolvedValue({ status: 503, statusText: "Service Unavailable" } as any);
      const res = await pingTargetUrl(proxy, "http://target.com", "target");
      expect(res.reachable).toBe(true);
    });

    it("returns unreachable for 500", async () => {
      vi.mocked(fetch).mockResolvedValue({ status: 500, statusText: "Server Error" } as any);
      const res = await pingTargetUrl(proxy, "http://target.com", "target");
      expect(res.reachable).toBe(false);
      expect(res.error).toBe("HTTP 500 Server Error");
    });

    it("returns unreachable on throw", async () => {
      vi.mocked(fetch).mockRejectedValue(new Error("Network Error"));
      const res = await pingTargetUrl(proxy, "http://target.com", "target");
      expect(res.reachable).toBe(false);
      expect(res.error).toContain("Network Error");
    });
  });

  describe("pingViaBackendStack", () => {
    const proxy = { server: "http://proxy" } as any;

    it("bypasses for spider backend", async () => {
      const res = await pingViaBackendStack(proxy, "http://target.com", "spider");
      expect(res.reachable).toBe(true);
      expect(res.forwarderType).toBe("direct");
    });

    it("uses proxy-forwarder for stealth backend and succeeds", async () => {
      const { startProxyForwarder } = await import("../../src/proxy/proxy-forwarder.js");
      const forwarderMock = {
        serverUrl: "http://127.0.0.1:9090",
        close: vi.fn().mockResolvedValue(undefined)
      };
      vi.mocked(startProxyForwarder).mockResolvedValue(forwarderMock);

      // Mock net.connect
      const socketMock: any = {
        write: vi.fn(),
        on: vi.fn((event, cb) => {
          if (event === "data") {
            setTimeout(() => cb(Buffer.from("HTTP/1.1 200 OK\r\n\r\n")), 10);
          }
        }),
        destroy: vi.fn()
      };
      vi.mocked(net.connect).mockReturnValue(socketMock);

      const res = await pingViaBackendStack(proxy, "http://target.com", "stealth-chrome");

      expect(res.forwarderType).toBe("proxy-forwarder");
      expect(res.reachable).toBe(true);
      expect(startProxyForwarder).toHaveBeenCalled();
      expect(forwarderMock.close).toHaveBeenCalled();
    });

    it("handles connection failure", async () => {
      const { startHttpCloakForwarder } = await import("../../backends/httpcloak-forwarder.js");
      const forwarderMock = {
        serverUrl: "http://127.0.0.1:9091",
        close: vi.fn().mockResolvedValue(undefined)
      };
      vi.mocked(startHttpCloakForwarder).mockResolvedValue(forwarderMock);

      const socketMock: any = {
        write: vi.fn(),
        on: vi.fn((event, cb) => {
          if (event === "error") {
            setTimeout(() => cb(new Error("Socket closed")), 10);
          }
        }),
        destroy: vi.fn()
      };
      vi.mocked(net.connect).mockReturnValue(socketMock);

      const res = await pingViaBackendStack(proxy, "http://target.com", "cloak-headless");

      expect(res.forwarderType).toBe("httpcloak");
      expect(res.reachable).toBe(false);
      expect(res.error).toContain("Socket error");
    });
  });

  describe("preValidatePool", () => {
    const proxy1 = { server: "http://proxy1" } as any;
    const proxy2 = { server: "http://proxy2" } as any;
    const target = { name: "target1", url: "http://target1.com" } as any;

    it("returns empty array for empty pool", async () => {
      const res = await preValidatePool([], [target]);
      expect(res).toEqual([]);
    });

    it("validates pool correctly", async () => {
      vi.mocked(fetch).mockResolvedValue({ status: 200, statusText: "OK" } as any);

      const res = await preValidatePool([proxy1, proxy2], [target]);
      expect(res).toHaveLength(2);
      expect(res[0]!.allTargetsReachable).toBe(true);
      expect(res[1]!.allTargetsReachable).toBe(true);
    });

    it("runs layer2 if enabled", async () => {
      vi.mocked(fetch).mockResolvedValue({ status: 200, statusText: "OK" } as any);
      const socketMock: any = {
        write: vi.fn(),
        on: vi.fn((event, cb) => {
          if (event === "data") {
            setTimeout(() => cb(Buffer.from("HTTP/1.1 200 OK\r\n\r\n")), 1);
          }
        }),
        destroy: vi.fn()
      };
      vi.mocked(net.connect).mockReturnValue(socketMock);

      const { startHttpCloakForwarder } = await import("../../backends/httpcloak-forwarder.js");
      vi.mocked(startHttpCloakForwarder).mockResolvedValue({
        serverUrl: "http://127.0.0.1:9091",
        close: vi.fn().mockResolvedValue(undefined)
      });

      const res = await preValidatePool([proxy1], [target], { enableBackendPing: true });
      expect(res[0]!.layer2Result).toBeDefined();
      expect(res[0]!.layer2Result?.reachable).toBe(true);
      expect(res[0]!.allTargetsReachable).toBe(true);
    });
  });

  describe("preValidateProxy", () => {
    const proxy = { server: "http://proxy" } as any;
    const target = { name: "target1", url: "http://target1.com" } as any;

    it("returns reachable if all targets succeed", async () => {
      vi.mocked(fetch).mockResolvedValue({ status: 200, statusText: "OK" } as any);
      const res = await preValidateProxy(proxy, [target], "cloak-headless");
      expect(res.reachable).toBe(true);
      expect(res.checkedTargets).toBe(1);
    });

    it("returns unreachable if a target fails", async () => {
      vi.mocked(fetch).mockResolvedValue({ status: 500, statusText: "Error" } as any);
      const res = await preValidateProxy(proxy, [target], "cloak-headless");
      expect(res.reachable).toBe(false);
      expect(res.failedTarget).toBe("target1");
    });
  });
});

