      mockSend.mockImplementation(async (cmd) => {
        if (cmd.constructor.name === "HeadObjectCommand") throw Object.assign(new Error(), { name: "NotFound" });
      });
      vi.mocked(fs.createReadStream).mockReturnValueOnce({} as any);

